import React, { useState, useEffect } from 'react';
import { User, AttendanceRecord } from '../types';
import { getUsers, getAttendance, saveAttendance } from '../services/dataService';
import { ChevronLeft, ChevronRight, CheckCircle, XCircle, AlertCircle, Coffee } from 'lucide-react';

const Attendance: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    getUsers().then(data => {
      setUsers(data);
      if (data.length > 0) setSelectedUser(data[0].id);
    });
  }, []);

  useEffect(() => {
    if (selectedUser) {
      setLoading(true);
      const monthStr = currentDate.toISOString().slice(0, 7); // YYYY-MM
      getAttendance(selectedUser, monthStr).then(data => {
        setRecords(data);
        setLoading(false);
      });
    }
  }, [selectedUser, currentDate]);

  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay(); // 0 is Sunday

  // Adjust so Monday is 0, Sunday is 6
  const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const handleDayClick = async (day: number) => {
    if (!selectedUser) return;

    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const existing = records.find(r => r.date === dateStr);

    // Cycle statuses: Present -> Absent -> Licencia -> Vacaciones -> Remove
    let newStatus: AttendanceRecord['status'] | null = 'Presente';
    if (existing) {
      if (existing.status === 'Presente') newStatus = 'Ausente';
      else if (existing.status === 'Ausente') newStatus = 'Licencia';
      else if (existing.status === 'Licencia') newStatus = 'Vacaciones';
      else newStatus = null; // Remove
    }

    if (newStatus) {
      const newRecord: AttendanceRecord = {
        id: existing?.id || Math.random().toString(36),
        userId: selectedUser,
        date: dateStr,
        status: newStatus
      };
      await saveAttendance(newRecord);
      setRecords(prev => [...prev.filter(p => p.date !== dateStr), newRecord]);
    } else {
        // Here we would ideally delete from backend, for mock we just filter out
        setRecords(prev => prev.filter(p => p.date !== dateStr));
    }
  };

  const getStatusIcon = (status?: string) => {
    switch (status) {
      case 'Presente': return <CheckCircle className="text-green-500 w-5 h-5 mx-auto" />;
      case 'Ausente': return <XCircle className="text-red-500 w-5 h-5 mx-auto" />;
      case 'Licencia': return <AlertCircle className="text-orange-500 w-5 h-5 mx-auto" />;
      case 'Vacaciones': return <Coffee className="text-blue-400 w-5 h-5 mx-auto" />;
      default: return null;
    }
  };

  const changeMonth = (delta: number) => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + delta, 1));
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h1 className="text-3xl font-bold text-slate-800">Gestión de Asistencia</h1>
           <p className="text-slate-500">Selecciona un trabajador para gestionar su calendario</p>
        </div>
        <div className="flex items-center gap-3 bg-white p-2 rounded-lg shadow-sm border border-slate-200">
          <span className="text-sm font-medium text-slate-600 pl-2">Trabajador:</span>
          <select 
            value={selectedUser} 
            onChange={(e) => setSelectedUser(e.target.value)}
            className="p-2 bg-slate-50 border border-slate-200 rounded-md outline-none focus:ring-2 focus:ring-blue-500"
          >
            {users.map(u => <option key={u.id} value={u.id}>{u.name} ({u.role})</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {/* Calendar Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-100">
          <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <ChevronLeft />
          </button>
          <h2 className="text-xl font-bold text-slate-800 capitalize">
            {currentDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
          </h2>
          <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <ChevronRight />
          </button>
        </div>

        {/* Calendar Grid */}
        <div className="p-6">
          <div className="grid grid-cols-7 mb-4">
            {['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'].map(day => (
              <div key={day} className="text-center text-sm font-semibold text-slate-400 uppercase tracking-wider py-2">
                {day}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-2">
            {Array.from({ length: startDay }).map((_, i) => (
              <div key={`empty-${i}`} className="aspect-square"></div>
            ))}

            {Array.from({ length: daysInMonth }).map((_, i) => {
              const day = i + 1;
              const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
              const record = records.find(r => r.date === dateStr);

              return (
                <button
                  key={day}
                  onClick={() => handleDayClick(day)}
                  disabled={loading}
                  className={`
                    aspect-square rounded-lg border flex flex-col items-center justify-center gap-1 transition-all
                    ${record ? 'bg-slate-50 border-slate-200 hover:shadow-md' : 'bg-white border-slate-100 hover:border-blue-300 hover:bg-blue-50'}
                  `}
                >
                  <span className={`text-sm font-medium ${record ? 'text-slate-600' : 'text-slate-400'}`}>{day}</span>
                  {getStatusIcon(record?.status)}
                </button>
              );
            })}
          </div>
        </div>

        <div className="bg-slate-50 p-4 border-t border-slate-100 flex gap-6 text-sm justify-center">
            <div className="flex items-center gap-2"><CheckCircle className="w-4 h-4 text-green-500" /> Presente</div>
            <div className="flex items-center gap-2"><XCircle className="w-4 h-4 text-red-500" /> Ausente</div>
            <div className="flex items-center gap-2"><AlertCircle className="w-4 h-4 text-orange-500" /> Licencia</div>
            <div className="flex items-center gap-2"><Coffee className="w-4 h-4 text-blue-400" /> Vacaciones</div>
        </div>
      </div>
    </div>
  );
};

export default Attendance;

