  return new Promise(resolve => setTimeout(() => {
    const exists = MOCK_PERMISSIONS.find(p => p.id === perm.id);
    if (exists) {
      MOCK_PERMISSIONS = MOCK_PERMISSIONS.map(p => p.id === perm.id ? perm : p);
    } else {
