// --- ATTENDANCE ---

export const getAttendance = async (userId: string, month: string): Promise<AttendanceRecord[]> => {
  return new Promise(resolve => {
    setTimeout(() => {
      const records = attendanceDB.filter(r => r.userId === userId && r.date.startsWith(month));
      resolve(records);
    }, 300);
  });
};

// NEW: Search by range
export const getAttendanceByRange = async (userId: string, startDate: string, endDate: string): Promise<AttendanceRecord[]> => {
    return new Promise(resolve => {
      setTimeout(() => {
        const records = attendanceDB.filter(r => {
            return r.userId === userId && r.date >= startDate && r.date <= endDate;
        });
        resolve(records);
      }, 500); // Slight delay for effect
    });
};

export const saveAttendance = async (record: AttendanceRecord): Promise<void> => {
  return new Promise(resolve => {
    setTimeout(() => {
      // Remove existing record for that user/date combo if exists
      attendanceDB = attendanceDB.filter(r => !(r.userId === record.userId && r.date === record.date));
      attendanceDB.push(record);
      resolve();
    }, 300);
  });
};

// New function to handle bulk upload from CSV
export const bulkSaveAttendance = async (records: AttendanceRecord[]): Promise<void> => {
  return new Promise(resolve => {
    setTimeout(() => {
      records.forEach(newRecord => {
        // Prevent duplicates for the same day/user (Last write wins or keep existing 'Presente')
        const existsIndex = attendanceDB.findIndex(r => r.userId === newRecord.userId && r.date === newRecord.date);
        if (existsIndex === -1) {
            attendanceDB.push(newRecord);
        } else {
            // If already exists, we could update or skip. 
            // Here we skip if already Presente, otherwise update.
            if (attendanceDB[existsIndex].status !== 'Presente') {
                attendanceDB[existsIndex] = newRecord;
            }
        }
      });
      resolve();
    }, 500);
  });
};

import React, { useState, useEffect } from 'react';
import { User, AttendanceRecord } from '../types';
import { getUsers, getAttendanceByRange, saveAttendance } from '../services/dataService';
import { ChevronLeft, ChevronRight, FileSpreadsheet, Search, Calendar, MapPin, Tablet } from 'lucide-react';
import { useAuth } from '../AuthContext';

const Attendance: React.FC = () => {
  const { permissions } = useAuth();

  // Search State
  const [users, setUsers] = useState<User[]>([]);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Data State
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);

  // Calendar View State
  const [currentCalendarDate, setCurrentCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);

  // Check permissions
  const canEdit = permissions?.['Asistencia']?.edit;

  useEffect(() => {
    getUsers().then(data => {
      setUsers(data);
      if (data.length > 0) setSelectedUser(data[0].id);

      // Default Dates: First and Last day of current month
      const now = new Date();
      const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
      const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);

      setStartDate(firstDay.toISOString().split('T')[0]);
      setEndDate(lastDay.toISOString().split('T')[0]);
    });
  }, []);

  const handleSearch = async () => {
    if (!selectedUser || !startDate || !endDate) {
        alert("Por favor seleccione usuario y rango de fechas");
        return;
    }

    setLoading(true);
    setHasSearched(true);
    // Reset selection to clear previous detail view
    setSelectedDay(null); 

    // Sync calendar view to start date
    const startObj = new Date(startDate);
    // Fix timezone offset issue for calendar navigation
    const startObjUTC = new Date(startObj.getUTCFullYear(), startObj.getUTCMonth(), 1);
    setCurrentCalendarDate(startObjUTC);

    try {
        const data = await getAttendanceByRange(selectedUser, startDate, endDate);
        setRecords(data);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const daysInMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), 1).getDay(); 
  const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const handleDayClick = (day: number) => {
    const newDate = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), day);
    setSelectedDay(newDate);
  };

  const toggleAttendance = async () => {
    if (!selectedUser || !selectedDay || !canEdit) return;

    const dateStr = selectedDay.toISOString().split('T')[0];
    const existing = records.find(r => r.date === dateStr);

    if (existing) {
        const newStatus = existing.status === 'Presente' ? 'Ausente' : 'Presente';
        const newRecord = { ...existing, status: newStatus as any };
        await saveAttendance(newRecord);
        setRecords(prev => prev.map(p => p.date === dateStr ? newRecord : p));
    } else {
        const newRecord: AttendanceRecord = {
            id: Math.random().toString(36),
            userId: selectedUser,
            date: dateStr,
            status: 'Presente'
        };
        await saveAttendance(newRecord);
        setRecords(prev => [...prev, newRecord]);
    }
  };

  const changeMonth = (delta: number) => {
    setCurrentCalendarDate(new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + delta, 1));
    setSelectedDay(null);
  };

  const getRecordForDay = (day: number) => {
    const dateStr = `${currentCalendarDate.getFullYear()}-${String(currentCalendarDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    // Check if record exists in the fetched data
    return records.find(r => r.date === dateStr);
  };

  // Helper to generate mock logs for the table view
  const getMockLogs = () => {
    if (!selectedDay || !selectedUser) return [];

    const dateStr = selectedDay.toISOString().split('T')[0];
    const record = records.find(r => r.date === dateStr);

    if (!record || record.status !== 'Presente') return [];

    const user = users.find(u => u.id === selectedUser);

    // Simulate realistic punches based on the date
    return [
        { name: user?.name, dept: 'Casa Colbún', time: `${dateStr} 08:07:02`, device: '001_Colbún' },
