        if (!role) {
            resolve(createEmptyMatrix());
            return;
        }
        const perm = MOCK_PERMISSIONS.find(p => p.id === role.permissionId);
        resolve(perm ? perm.matrix : createEmptyMatrix());
    }, 200));
};

