                            {currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                        </h2>
                        <button onClick={() => changeMonth(1)} className="p-1 hover:bg-white rounded-md transition-all shadow-sm"><ChevronRight size={20} className="text-slate-500"/></button>
                    </div>

                    {/* Calendar Grid */}
                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2">
                            {['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'].map(day => (
                            <div key={day} className="text-center text-xs font-bold text-blue-600 uppercase py-1">
