                            {Array.from({ length: daysInMonth }).map((_, i) => {
                            const day = i + 1;
                            const record = getRecordForDay(day);
                            const isSelected = selectedDay && selectedDay.getDate() === day && selectedDay.getMonth() === currentCalendarDate.getMonth();

                            // Blue box logic for Presente
