const mysql = require('mysql2/promise');
require('dotenv').config();

// Configuración de la conexión a la Base de Datos
// Crea un archivo .env en esta carpeta con estas variables
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'agro_comice_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

module.exports = pool;

const express = require('express');
const cors = require('cors');
const pool = require('./db');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3001;

app.use(cors());
app.use(express.json());

// --- USERS ROUTES ---

// Get All Users (Joined with Role Name)
app.get('/api/users', async (req, res) => {
  try {
    const [rows] = await pool.query(`
      SELECT u.id, u.name, u.email, u.avatar, u.password, r.name as role 
      FROM users u 
      LEFT JOIN roles r ON u.role_id = r.id
    `);
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Save/Update User
app.post('/api/users', async (req, res) => {
  const { id, name, email, role, avatar, password } = req.body;
  try {
    // Buscar el ID del rol basado en el nombre (ya que el frontend manda el nombre del rol)
    const [roles] = await pool.query('SELECT id FROM roles WHERE name = ?', [role]);
    const roleId = roles.length > 0 ? roles[0].id : null;

    // Check if exists
    const [exists] = await pool.query('SELECT id FROM users WHERE id = ?', [id]);

    if (exists.length > 0) {
      await pool.query(
        'UPDATE users SET name=?, email=?, role_id=?, avatar=?, password=? WHERE id=?',
        [name, email, roleId, avatar, password, id]
      );
    } else {
      await pool.query(
        'INSERT INTO users (id, name, email, role_id, avatar, password) VALUES (?, ?, ?, ?, ?, ?)',
        [id, name, email, roleId, avatar, password]
      );
    }
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/users/:id', async (req, res) => {
  try {
    await pool.query('DELETE FROM users WHERE id = ?', [req.params.id]);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- ROLES ROUTES ---

app.get('/api/roles', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT id, name, description, permission_id as permissionId FROM roles');
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/roles', async (req, res) => {
  const { id, name, description, permissionId } = req.body;
  try {
    const [exists] = await pool.query('SELECT id FROM roles WHERE id = ?', [id]);
    if (exists.length > 0) {
      await pool.query('UPDATE roles SET name=?, description=?, permission_id=? WHERE id=?', [name, description, permissionId, id]);
    } else {
      await pool.query('INSERT INTO roles (id, name, description, permission_id) VALUES (?, ?, ?, ?)', [id, name, description, permissionId]);
    }
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/roles/:id', async (req, res) => {
  try {
    await pool.query('DELETE FROM roles WHERE id = ?', [req.params.id]);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- PERMISSIONS ROUTES ---

app.get('/api/permissions', async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT * FROM permissions');
    // Matrix is automatically parsed from JSON column by mysql2
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/permissions/role/:roleName', async (req, res) => {
    try {
