            SELECT p.matrix 
            FROM roles r 
            JOIN permissions p ON r.permission_id = p.id 
            WHERE r.name = ?
        `, [req.params.roleName]);

        if (rows.length > 0) res.json(rows[0].matrix);
        else res.json({});
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/permissions', async (req, res) => {
  const { id, name, description, matrix } = req.body;
  try {
    const matrixJson = JSON.stringify(matrix);
    const [exists] = await pool.query('SELECT id FROM permissions WHERE id = ?', [id]);
    if (exists.length > 0) {
      await pool.query('UPDATE permissions SET name=?, description=?, matrix=? WHERE id=?', [name, description, matrixJson, id]);
    } else {
      await pool.query('INSERT INTO permissions (id, name, description, matrix) VALUES (?, ?, ?, ?)', [id, name, description, matrixJson]);
    }
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

