app.get('/api/attendance/range', async (req, res) => {
    const { userId, start, end } = req.query;
    try {
        const [rows] = await pool.query(
            'SELECT id, user_id as userId, date, status, notes FROM attendance_records WHERE user_id = ? AND date BETWEEN ? AND ?',
            [userId, start, end]
        );
        // Format date to string YYYY-MM-DD to match frontend types
        const formatted = rows.map(r => ({
            ...r,
            date: r.date instanceof Date ? r.date.toISOString().split('T')[0] : r.date
        }));
        res.json(formatted);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.get('/api/attendance/logs', async (req, res) => {
    const { userId, date } = req.query;
    try {
        // Search logs for that day (User ID and Date match)
        // Note: logsDB uses exact datetime, we filter by LIKE date%
        const [rows] = await pool.query(
            `SELECT id, user_id as userId, user_name as userName, department, date_time as dateTime, device_id as deviceId 
             FROM attendance_logs 
             WHERE user_id = ? AND date_time LIKE ? ORDER BY date_time ASC`,
            [userId, `${date}%`]
        );
         // Format datetime
         const formatted = rows.map(r => ({
            ...r,
            dateTime: new Date(r.dateTime).toISOString().replace('T', ' ').substring(0, 19)
        }));
        res.json(formatted);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/attendance', async (req, res) => {
    const { id, userId, date, status, notes } = req.body;
    try {
        // Upsert logic for daily record
        const query = `
            INSERT INTO attendance_records (id, user_id, date, status, notes)
            VALUES (?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE status = VALUES(status), notes = VALUES(notes)
        `;
        await pool.query(query, [id, userId, date, status, notes]);
        res.json({ success: true });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/attendance/bulk', async (req, res) => {
    const { records, logs } = req.body;
    const connection = await pool.getConnection();
    try {
        await connection.beginTransaction();

        // 1. Insert Logs
        if (logs && logs.length > 0) {
            const logValues = logs.map(l => [l.id, l.userId, l.userName, l.department, l.dateTime, l.deviceId]);
            await connection.query(
                'INSERT IGNORE INTO attendance_logs (id, user_id, user_name, department, date_time, device_id) VALUES ?',
                [logValues]
            );
        }

        // 2. Upsert Daily Records
        if (records && records.length > 0) {
            for (const r of records) {
                await connection.query(
                    `INSERT INTO attendance_records (id, user_id, date, status, notes) VALUES (?, ?, ?, ?, ?)
                     ON DUPLICATE KEY UPDATE status = IF(status != 'Presente', VALUES(status), status)`, 
                    [r.id, r.userId, r.date, r.status, r.notes]
                );
            }
        }

        await connection.commit();
        res.json({ success: true });
    } catch (err) {
        await connection.rollback();
        res.status(500).json({ error: err.message });
    } finally {
        connection.release();
    }
});


