// Helper for Mock Encryption (still used for frontend compatibility, though backend handles storage)
const mockEncrypt = (pass: string) => btoa(pass);

// Default Matrix Builder
const createEmptyMatrix = () => {
  const matrix: any = {};
  APP_ENTITIES.forEach(ent => {
    matrix[ent] = { view: false, create: false, edit: false, delete: false };
  });
  return matrix;
};

// --- HELPER: Resolve Permissions ---
export const resolveUserPermissions = async (roleName: string): Promise<PermissionMatrix> => {
    try {
        const res = await fetch(`${API_URL}/permissions/role/${roleName}`);
        if (!res.ok) return createEmptyMatrix();
        const matrix = await res.json();
        // If empty object returned, return default
        return Object.keys(matrix).length > 0 ? matrix : createEmptyMatrix();
    } catch (e) {
        console.error("Error fetching permissions", e);
        return createEmptyMatrix();
    }
};

