    // Upsert (Insert or Update) en Postgres
    const query = `
      INSERT INTO users (id, name, email, role_id, avatar, password)
      VALUES ($1, $2, $3, $4, $5, $6)
      ON CONFLICT (id) DO UPDATE 
      SET name = EXCLUDED.name, 
          email = EXCLUDED.email, 
          role_id = EXCLUDED.role_id, 
          avatar = EXCLUDED.avatar, 
          password = EXCLUDED.password
    `;
    await pool.query(query, [id, name, email, roleId, avatar, password]);
