app.get('/api/attendance/range', async (req, res) => {
    const { userId, start, end } = req.query;
    try {
        const { rows } = await pool.query(
            'SELECT id, user_id as "userId", date, status, notes FROM attendance_records WHERE user_id = $1 AND date BETWEEN $2 AND $3',
            [userId, start, end]
        );

        // Ajuste de fecha para evitar problemas de zona horaria al serializar
        const formatted = rows.map(r => {
             // Postgres devuelve objetos Date. Convertimos a string YYYY-MM-DD
             const d = new Date(r.date);
             const dateStr = d.toISOString().split('T')[0];
             return { ...r, date: dateStr };
        });

        res.json(formatted);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.get('/api/attendance/logs', async (req, res) => {
    const { userId, date } = req.query;
    try {
        // En Postgres casteamos TIMESTAMP a TEXT para hacer el LIKE
        const { rows } = await pool.query(
            `SELECT id, user_id as "userId", user_name as "userName", department, date_time as "dateTime", device_id as "deviceId"
             FROM attendance_logs 
             WHERE user_id = $1 AND date_time::text LIKE $2 
             ORDER BY date_time ASC`,
            [userId, `${date}%`]
        );
         const formatted = rows.map(r => ({
            ...r,
            dateTime: new Date(r.dateTime).toISOString().replace('T', ' ').substring(0, 19)
        }));
        res.json(formatted);
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/attendance', async (req, res) => {
    const { id, userId, date, status, notes } = req.body;
    try {
        const query = `
            INSERT INTO attendance_records (id, user_id, date, status, notes)
            VALUES ($1, $2, $3, $4, $5)
            ON CONFLICT (user_id, date) DO UPDATE 
            SET status = EXCLUDED.status, notes = EXCLUDED.notes
        `;
        await pool.query(query, [id, userId, date, status, notes]);
        res.json({ success: true });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/attendance/bulk', async (req, res) => {
    const { records, logs } = req.body;
    const client = await pool.connect();
    try {
        await client.query('BEGIN');

        // 1. Insert Logs
        if (logs && logs.length > 0) {
            for (const l of logs) {
                await client.query(
                    `INSERT INTO attendance_logs (id, user_id, user_name, department, date_time, device_id)
                     VALUES ($1, $2, $3, $4, $5, $6)
                     ON CONFLICT (user_id, date_time) DO NOTHING`,
                    [l.id, l.userId, l.userName, l.department, l.dateTime, l.deviceId]
                );
            }
        }

        // 2. Upsert Daily Records
        if (records && records.length > 0) {
            for (const r of records) {
                await client.query(
                    `INSERT INTO attendance_records (id, user_id, date, status, notes) 
                     VALUES ($1, $2, $3, $4, $5)
                     ON CONFLICT (user_id, date) DO UPDATE 
                     SET status = CASE WHEN attendance_records.status != 'Presente' THEN EXCLUDED.status ELSE attendance_records.status END`, 
                    [r.id, r.userId, r.date, r.status, r.notes]
                );
            }
        }

        await client.query('COMMIT');
        res.json({ success: true });
    } catch (err) {
        await client.query('ROLLBACK');
        res.status(500).json({ error: err.message });
    } finally {
        client.release();
    }
});

