import React from 'react';

export interface User {
  id: string;
  name: string;
  email: string;
  role: string; // This links to RoleDef.name or RoleDef.id
  avatar: string;
  password?: string; // Mock encrypted
}

export type RoleDef = {
  id: string;
  name: string;
  description?: string;
  permissionId: string; // Linked to a Permission Matrix
};

export interface PermissionMatrix {
  [entity: string]: {
    view: boolean;
    create: boolean;
    edit: boolean;
    delete: boolean;
  }
}

export interface Permission {
  id: string;
  name: string; // e.g., "Acceso Total", "Solo Lectura"
  description: string;
  matrix: PermissionMatrix;
}

export interface AttendanceRecord {
  id: string;
  userId: string;
  date: string; // YYYY-MM-DD
  status: 'Presente' | 'Ausente' | 'Licencia' | 'Vacaciones';
  notes?: string;
}

export interface AttendanceLog {
  id: string;
  userId: string;
  userName: string;
  department: string;
  dateTime: string; // YYYY-MM-DD HH:mm:ss
  deviceId: string;
}

export type ActivityStatus = 'Pendiente' | 'En Progreso' | 'Completada' | 'Cancelada';

export interface ActivityAttachment {
  name: string;
  url: string; // Base64 data URI
  type: string;
