                        </div>
                    )) : (
                        <div className="p-8 text-center text-slate-400 text-sm">
                            No hay actividades próximas agendadas.
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* Side Column (Weather + Calendar) */}
        <div className="space-y-6">

            {/* Weather Widget */}
            <div className="bg-gradient-to-br from-sky-500 to-blue-600 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
                <div className="relative z-10">
                    <h3 className="font-bold text-lg mb-1 flex items-center gap-2"><CloudSun size={20}/> Tiempo en Colbún</h3>
                    <p className="text-sky-100 text-sm mb-6 opacity-90">Región del Maule, Chile</p>

                    <div className="flex items-center justify-between mb-6">
                    <div>
                        <span className="text-5xl font-bold">22°</span>
                        <p className="text-sky-100 mt-1 font-medium">Parcialmente Nublado</p>
                    </div>
                    <Sun size={56} className="text-yellow-300 animate-pulse opacity-90" />
                    </div>

                    <div className="grid grid-cols-2 gap-2 text-center text-sm">
                        <div className="bg-white/20 rounded-lg p-3 backdrop-blur-sm flex flex-col items-center">
                            <Droplets size={16} className="mb-1 opacity-80"/>
                            <span className="block opacity-70 text-xs">Humedad</span>
                            <span className="font-bold">58%</span>
                        </div>
                        <div className="bg-white/20 rounded-lg p-3 backdrop-blur-sm flex flex-col items-center">
                            <Wind size={16} className="mb-1 opacity-80"/>
                            <span className="block opacity-70 text-xs">Viento</span>
                            <span className="font-bold">14 km/h</span>
                        </div>
                    </div>
                </div>
                <div className="absolute -top-10 -right-10 w-40 h-40 bg-white opacity-10 rounded-full blur-3xl"></div>
            </div>

            {/* Visual Calendar */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
                     <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronLeft size={18}/></button>
                     <h3 className="font-bold text-slate-700 capitalize">
                         {currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                     </h3>
                     <button onClick={() => changeMonth(1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronRight size={18}/></button>
                </div>

                <div className="p-4">
                    <div className="grid grid-cols-7 mb-2 text-center">
                         {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                             <span key={d} className="text-xs font-bold text-slate-400">{d}</span>
                         ))}
                    </div>
                    <div className="grid grid-cols-7 gap-1">
                        {Array.from({ length: startDay }).map((_, i) => (
                            <div key={`empty-${i}`} className="aspect-square"></div>
                        ))}
                        {Array.from({ length: daysInMonth }).map((_, i) => {
                            const day = i + 1;
                            const dayActivities = getActivitiesForDay(day);
                            const hasActivity = dayActivities.length > 0;

                            // Determine color based on most critical status
                            let dotColor = 'bg-slate-300';
                            if (dayActivities.some(a => a.status === 'En Progreso')) dotColor = 'bg-orange-500';
                            else if (dayActivities.some(a => a.status === 'Pendiente')) dotColor = 'bg-blue-500';
                            else if (dayActivities.some(a => a.status === 'Completada')) dotColor = 'bg-green-500';

                            return (
                                <div key={day} className="aspect-square flex flex-col items-center justify-center relative rounded-lg hover:bg-slate-50 cursor-default">
                                    <span className={`text-xs font-medium ${hasActivity ? 'text-slate-800' : 'text-slate-500'}`}>{day}</span>
                                    {hasActivity && (
                                        <span className={`absolute bottom-1.5 w-1.5 h-1.5 rounded-full ${dotColor}`}></span>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                    <div className="mt-4 flex flex-wrap gap-2 text-[10px] text-slate-500 justify-center">
                        <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-500"></span> Pendiente</div>
                        <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-orange-500"></span> En Progreso</div>
                        <div className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> Completada</div>
                    </div>
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

