                     <div>
                         <h3 className="text-xs font-bold uppercase text-slate-500 mb-1">Periodo Visualizado</h3>
                         <p className="text-lg font-bold text-slate-900 capitalize">{currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}</p>
                         <p className="text-sm text-slate-600">Rango búsqueda: {startDate} al {endDate}</p>
                     </div>
                </div>
            )}

            {/* Calendar Snapshot */}
            <div className="mb-8">
                <h3 className="font-bold text-lg mb-4 text-slate-800 border-l-4 border-blue-600 pl-3">Resumen del Mes</h3>
                <div className="border border-slate-300">
                     <div className="grid grid-cols-7 bg-slate-100 border-b border-slate-300">
                        {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(d => (
                            <div key={d} className="p-2 text-center font-bold text-xs uppercase">{d}</div>
                        ))}
                     </div>
                     <div className="grid grid-cols-7">
                        {Array.from({ length: startDay }).map((_, i) => (
                            <div key={`p-empty-${i}`} className="h-16 border-r border-b border-slate-200"></div>
                        ))}
                        {Array.from({ length: daysInMonth }).map((_, i) => {
                            const day = i + 1;
                            const record = getRecordForDay(day);
                            const isPresent = record?.status === 'Presente';
                            return (
                                <div key={`p-day-${day}`} className="h-16 border-r border-b border-slate-200 p-1 relative">
                                    <span className="text-xs font-bold text-slate-500">{day}</span>
                                    {isPresent && (
                                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                                            <span className="text-2xl text-blue-600/20 font-bold">✔</span>
                                        </div>
                                    )}
                                    {record?.status === 'Ausente' && (
                                        <div className="absolute bottom-1 right-1 text-[10px] bg-red-100 text-red-700 px-1 rounded">AUS</div>
                                    )}
                                </div>
                            );
                        })}
                     </div>
                </div>
            </div>

            {/* Detail Table */}
            {selectedDay ? (
                <div>
                     <h3 className="font-bold text-lg mb-4 text-slate-800 border-l-4 border-blue-600 pl-3">
                         Detalle del Día: {selectedDay.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'})}
                     </h3>
                     {logs.length > 0 ? (
                         <table className="w-full text-left border border-slate-300">
                             <thead>
                                 <tr className="bg-slate-100 border-b border-slate-300">
                                     <th className="p-2 text-sm font-bold">Hora</th>
                                     <th className="p-2 text-sm font-bold">Departamento</th>
                                     <th className="p-2 text-sm font-bold">Dispositivo</th>
                                 </tr>
                             </thead>
                             <tbody>
                                 {logs.map((log, i) => (
                                     <tr key={i} className="border-b border-slate-200">
                                         <td className="p-2 text-sm font-mono">{log.dateTime.split(' ')[1]}</td>
                                         <td className="p-2 text-sm">{log.department}</td>
                                         <td className="p-2 text-sm">{log.deviceId}</td>
                                     </tr>
                                 ))}
                             </tbody>
                         </table>
                     ) : (
                         <div className="p-4 border border-slate-200 text-center text-slate-500 italic rounded">
                             No hay registros de marcaje para este día.
                         </div>
                     )}
                </div>
            ) : (
                <div className="p-4 bg-slate-50 border border-slate-200 rounded text-center text-slate-500 text-sm">
                    * No se ha seleccionado un día específico para el detalle en este reporte.
                </div>
            )}

            <div className="mt-12 pt-8 border-t border-slate-300 text-center text-xs text-slate-400">
                Generado automáticamente por Sistema Agro Comice Ltda.
            </div>
          </div>
      </div>
    </div>
  );
};

