                            <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px]">
                                <p>Seleccione un día del calendario para ver el detalle.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

        </div>
      )}

