         We set a fixed width of 800px which maps well to A4 PDF generation.
      */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
          <div ref={reportRef} className="w-[800px] bg-white p-12 text-slate-900">
            {/* Report Header */}
            <div className="border-b-2 border-slate-800 pb-6 mb-8 flex justify-between items-end">
                <div>
                    <h1 className="text-4xl font-bold text-slate-900">Agro Comice Ltda</h1>
                    <p className="text-slate-500 text-lg mt-1">Reporte de Asistencia Personal</p>
