            ) : (
                <div className="p-6 bg-slate-50 border border-slate-200 rounded-lg text-center text-slate-500 text-sm italic">
                    * No se ha seleccionado un día específico para el detalle en este reporte.
                </div>
            )}

            <div className="mt-16 pt-8 border-t border-slate-300 text-center text-xs text-slate-400">
                <p>Generado automáticamente por Sistema Agro Comice Ltda.</p>
                <p className="mt-1">Documento de uso interno.</p>
            </div>
          </div>
      </div>
    </div>
  );
};

