    { id: 2, day: 'Vie', fullDay: 'viernes', date: 'Provisión', max: 30, min: 12, current: 28, condition: 'Despejado', icon: Sun, hourly: generateHourlyData(26, 'sunny'), humidity: 38, wind: 12, rainProb: 0 },
