  useEffect(() => {
    const loadData = async () => {
        const [acts, usrs] = await Promise.all([getActivities(), getUsers()]);
        const sorted = acts.sort((a,b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
        setActivities(sorted);
        setUsers(usrs);
