          case 'wind':
              return { dataKey: 'wind', color: '#10b981', fillId: 'colorWind', unit: ' km/h', domain: ['dataMin', 'dataMax + 10'] };
          default: 
              return { dataKey: 'temp', color: '#f59e0b', fillId: 'colorTemp', unit: '°', domain: ['dataMin - 5', 'dataMax + 5'] };
      }
  }, [activeMetric]);

  const CustomTick = (props: any) => {
