// Synthesize AttendanceRecords (for Calendar) from Logs (Present) and Absences (Licencia/Vacaciones)
export const getAttendanceByRange = async (userId: string, startDate: string, endDate: string): Promise<AttendanceRecord[]> => {
    const records: AttendanceRecord[] = [];

    // 1. Fetch Logs (Presence)
    // We get unique dates where the user has at least one log
    const { data: logs, error: logsError } = await supabase
        .from('attendance_logs')
        .select('date_time')
        .eq('user_id', userId)
        .gte('date_time', `${startDate} 00:00:00`)
        .lte('date_time', `${endDate} 23:59:59`);

    if (logsError) throw logsError;

    // Map unique log dates to "Presente" records
    const presentDates = new Set<string>();
    logs?.forEach(l => {
        const dateOnly = l.date_time.split('T')[0];
        if (!presentDates.has(dateOnly)) {
            presentDates.add(dateOnly);
            records.push({
                id: `log-${dateOnly}`,
                userId,
                date: dateOnly,
                status: 'Presente'
            });
        }
    });

    // 2. Fetch Absences (Exceptions)
    const { data: absences, error: absError } = await supabase
        .from('absences')
        .select('*')
        .eq('user_id', userId)
        .lte('start_date', endDate)
        .gte('end_date', startDate);

    if (absError) throw absError;

    // Expand absence ranges to individual days
    absences?.forEach(abs => {
        let current = new Date(abs.start_date < startDate ? startDate : abs.start_date);
        const end = new Date(abs.end_date > endDate ? endDate : abs.end_date);

        while (current <= end) {
            const dateStr = current.toISOString().split('T')[0];

            // Priority Rule: If logged as present, ignore absence? Or show both?
            // Current Logic: If NOT already marked present, add absence. 
            // If marked present (e.g. came to work during vacation), keep Presente.
            if (!presentDates.has(dateStr)) {
                records.push({
                    id: `abs-${abs.id}-${dateStr}`,
                    userId,
                    date: dateStr,
                    status: abs.type as any, // 'Licencia' | 'Vacaciones'
                    notes: abs.reason
                });
            }
            current.setDate(current.getDate() + 1);
        }
    });

    return records;
};

