  const defaultMatrix = () => {
    const m: any = {};
    APP_ENTITIES.forEach(e => m[e] = { view: false, create: false, edit: false, delete: false });
    return m;
  };

  const [editingPerm, setEditingPerm] = useState<Partial<Permission>>({});

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    getPermissions().then(setPerms);
  };

  const handleView = (perm: Permission) => {
    setEditingPerm(JSON.parse(JSON.stringify(perm))); // Deep copy
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleEdit = (perm: Permission) => {
    if (!canEdit) return;
    setEditingPerm(JSON.parse(JSON.stringify(perm))); // Deep copy
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingPerm({ name: '', description: '', matrix: defaultMatrix() });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (!canDelete) return;

    // 1. Confirmación
    if (window.confirm('¿Está seguro que desea eliminar este perfil de permisos?')) {
      try {
        // 2. Intento de borrado
        await deletePermission(id);

        // 3. Éxito
        alert("Perfil de permisos eliminado correctamente.");
        loadData();
      } catch (error) {
        // 4. Error
        console.error("Error al eliminar permiso:", error);
        alert("No se puede eliminar este perfil. Razón: Está asignado actualmente a uno o más Roles. Por favor asigne otro perfil a esos roles antes de eliminar este.");
      }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPerm.name && editingPerm.matrix) {
      try {
        await savePermission(editingPerm as Permission);
        setIsModalOpen(false);
        loadData();
      } catch (error) {
        console.error("Error al guardar permiso:", error);
        alert("Error al guardar el perfil de permisos.");
      }
    }
  };

  const toggleMatrix = (entity: string, action: 'view' | 'create' | 'edit' | 'delete') => {
    if (isViewMode) return;
    setEditingPerm(prev => {
        const newMatrix = { ...prev.matrix };

        // CORRECCIÓN: Si la entidad es nueva y no existe en el JSON guardado, la inicializamos
        if (!newMatrix[entity]) {
            newMatrix[entity] = { view: false, create: false, edit: false, delete: false };
        }

        newMatrix[entity] = { ...newMatrix[entity], [action]: !newMatrix[entity][action] };
        return { ...prev, matrix: newMatrix };
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Perfiles de Permisos</h1>
            <p className="text-slate-500">Configura matrices de acceso granular por entidad.</p>
        </div>
        {canCreate && (
          <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2">
            <Plus size={18} /> Nuevo Perfil
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="p-4 font-semibold text-slate-600">Nombre del Perfil</th>
              <th className="p-4 font-semibold text-slate-600">Descripción</th>
              <th className="p-4 font-semibold text-slate-600 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {perms.map((p) => (
              <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                <td className="p-4">
                  <div className="flex items-center gap-3">
                    <div className="bg-orange-100 p-2 rounded-lg text-orange-600">
                      <Key size={18} />
                    </div>
                    <span className="font-bold text-slate-800">{p.name}</span>
                  </div>
                </td>
                <td className="p-4 text-slate-600">{p.description}</td>
                <td className="p-4 text-right space-x-2">
                  <button onClick={() => handleView(p)} className="p-2 hover:bg-emerald-50 rounded text-slate-500 hover:text-emerald-600 transition-colors">
                    <Eye size={18} />
                  </button>
                  {canEdit && (
                    <button onClick={() => handleEdit(p)} className="p-2 hover:bg-blue-50 rounded text-slate-500 hover:text-blue-600 transition-colors">
                      <Edit2 size={18} />
                    </button>
                  )}
                  {canDelete && (
                    <button onClick={(e) => handleDelete(p.id, e)} className="p-2 hover:bg-red-50 rounded text-slate-500 hover:text-red-600 transition-colors">
                      <Trash2 size={18} />
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

       {/* Modal with Matrix */}
       {isModalOpen && editingPerm.matrix && (
        <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh] animate-fade-in">
            <div className="flex justify-between items-center p-6 border-b border-slate-100">
              <h2 className="text-xl font-bold text-slate-800">
                  {isViewMode ? 'Ver Permisos' : (editingPerm.id ? 'Editar Permisos' : 'Nuevo Perfil de Permisos')}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Nombre del Perfil</label>
                    <input 
                    type="text" 
                    required
                    disabled={isViewMode}
                    value={editingPerm.name || ''}
                    onChange={e => setEditingPerm({...editingPerm, name: e.target.value})}
                    className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100"
                    placeholder="Ej: Administrador, Vendedor"
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                    <input 
                    type="text" 
                    required
                    disabled={isViewMode}
                    value={editingPerm.description || ''}
                    onChange={e => setEditingPerm({...editingPerm, description: e.target.value})}
                    className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100"
                    />
                </div>
              </div>

              {/* Permission Matrix */}
              <div className="border rounded-lg overflow-hidden">
                <div className="bg-slate-100 p-3 grid grid-cols-5 text-sm font-bold text-slate-700">
                    <div className="col-span-1">Entidad</div>
                    <div className="text-center">Ver</div>
                    <div className="text-center">Crear</div>
                    <div className="text-center">Editar</div>
                    <div className="text-center">Eliminar</div>
                </div>
                <div className="divide-y divide-slate-100">
                    {APP_ENTITIES.map(entity => (
                        <div key={entity} className="p-3 grid grid-cols-5 items-center hover:bg-slate-50">
                            <div className="col-span-1 font-medium text-slate-700 text-sm">{entity}</div>
                            {['view', 'create', 'edit', 'delete'].map((action) => (
                                <div key={action} className="flex justify-center">
                                    <input 
                                        type="checkbox"
                                        disabled={isViewMode}
                                        checked={editingPerm.matrix?.[entity]?.[action as 'view'|'create'|'edit'|'delete'] || false}
                                        onChange={() => toggleMatrix(entity, action as any)}
                                        className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500 cursor-pointer disabled:opacity-50"
                                    />
                                </div>
                            ))}
                        </div>
                    ))}
                </div>
              </div>
            </form>

            <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                  {isViewMode ? 'Cerrar' : 'Cancelar'}
                </button>
                {!isViewMode && (
                    <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Guardar
                    </button>
                )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PermissionsPage;

import React, { useEffect, useState } from 'react';
import { Activity, ActivityStatus, User } from '../types';
import { getActivities, saveActivity, deleteActivity, getUsers } from '../services/dataService';
import { Plus, Edit2, Trash2, X, Save, Paperclip, FileText, Calendar, CheckCircle2, Clock, AlertCircle, Ban, Eye, ChevronLeft, ChevronRight } from 'lucide-react';
import { useAuth } from '../AuthContext';

const ActivitiesPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [activities, setActivities] = useState<Activity[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingActivity, setEditingActivity] = useState<Partial<Activity>>({});

  // State para Calendario
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  const canCreate = permissions?.['Actividades']?.create;
  const canEdit = permissions?.['Actividades']?.edit;
  const canDelete = permissions?.['Actividades']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [acts, usrs] = await Promise.all([getActivities(), getUsers()]);
    setActivities(acts);
    setUsers(usrs);
  };

  // --- LÓGICA DE CALENDARIO ---
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay(); 
  const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1; // Lunes = 0 visualmente en este grid ajustado

  const changeMonth = (delta: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + delta, 1);
    setCurrentMonth(newDate);
    setSelectedDate(null); // Resetear día seleccionado al cambiar mes
  };

  const handleDayClick = (day: number) => {
      const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
      if (selectedDate && newDate.getTime() === selectedDate.getTime()) {
          setSelectedDate(null); // Deseleccionar si ya estaba seleccionado
      } else {
          setSelectedDate(newDate);
      }
  };

  // Helper para verificar actividades en un día específico (para colorear el calendario)
  const getActivitiesForDay = (day: number) => {
      const dateStr = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
      return activities.filter(act => {
          // Chequeo simple de rango inclusivo
          return dateStr >= act.startDate && dateStr <= act.endDate;
      });
  };

  // --- FILTRADO DE LISTA ---
  const getProcessedActivities = () => {
      let filtered = [];

      if (selectedDate) {
          // 1. Filtrar por día específico seleccionado
          const dateStr = selectedDate.toISOString().split('T')[0];
          filtered = activities.filter(act => dateStr >= act.startDate && dateStr <= act.endDate);
      } else {
          // 2. Si no hay día seleccionado, mostrar todo el MES visible
          const targetMonth = currentMonth.getMonth();
          const targetYear = currentMonth.getFullYear();

          filtered = activities.filter(act => {
              const actDate = new Date(act.startDate);
              // Ajuste simple: Ver si la actividad inicia o existe dentro de este mes
              // Para simplificar, usamos la fecha de inicio, pero idealmente sería superposición
              const startParts = act.startDate.split('-');
              const y = parseInt(startParts[0]);
              const m = parseInt(startParts[1]) - 1;
              return y === targetYear && m === targetMonth;
          });
      }

      // 3. Ordenar por Fecha de Inicio ASC
      return filtered.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  const processedActivities = getProcessedActivities();

  // Agrupar por estado
  const groupedActivities = {
      'Pendiente': processedActivities.filter(a => a.status === 'Pendiente'),
      'En Progreso': processedActivities.filter(a => a.status === 'En Progreso'),
      'Completada': processedActivities.filter(a => a.status === 'Completada'),
      'Cancelada': processedActivities.filter(a => a.status === 'Cancelada'),
  };

  const statusOrder: ActivityStatus[] = ['Pendiente', 'En Progreso', 'Completada', 'Cancelada'];

  // --- MANEJO DE MODAL ---

  const handleNew = () => {
    if (!canCreate) return;
    setEditingActivity({
        name: '',
        startDate: new Date().toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        description: '',
        status: 'Pendiente',
        assigneeId: currentUser?.id || '',
        attachments: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleEdit = (act: Activity) => {
    if (!canEdit) return;
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (act: Activity) => {
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (!canDelete) return;

    // 1. Confirmación
    if (confirm('¿Está seguro que desea eliminar esta actividad?')) {
        try {
            // 2. Borrado
            await deleteActivity(id);
            // 3. Éxito
            alert('Actividad eliminada correctamente.');
            loadData();
        } catch (error) {
            // 4. Error
            console.error(error);
            alert("No se pudo eliminar la actividad. Verifique que no existan otros registros dependiendo de ella.");
        }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingActivity.name && editingActivity.startDate) {
        try {
            await saveActivity(editingActivity as Activity);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Error al guardar la actividad.");
        }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingActivity(prev => ({
                      ...prev,
                      attachments: [...(prev.attachments || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removeAttachment = (index: number) => {
      setEditingActivity(prev => ({
          ...prev,
          attachments: prev.attachments?.filter((_, i) => i !== index)
      }));
  };

  const getStatusIcon = (status?: ActivityStatus) => {
      switch(status) {
          case 'Pendiente': return <Clock size={14}/>;
          case 'En Progreso': return <AlertCircle size={14}/>;
          case 'Completada': return <CheckCircle2 size={14}/>;
          case 'Cancelada': return <Ban size={14}/>;
          default: return null;
      }
  };

  const formatDate = (dateStr: string | undefined) => {
      if (!dateStr) return '';
      const parts = dateStr.split('-');
      if (parts.length === 3) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return dateStr;
  };

  return (
    <div className="space-y-6">

      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Actividades y Tareas</h1>
            <p className="text-slate-500">Gestión operativa y planificación.</p>
        </div>

        <div className="flex items-center gap-3">
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nueva Actividad</span>
            </button>
            )}
        </div>
      </div>

      {/* MAIN GRID: CALENDAR + LIST */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">

          {/* COLUMN 1: CALENDAR WIDGET (Mobile: Top, Desktop: Right) */}
          <div className="lg:col-span-1 lg:order-last space-y-4">
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden sticky top-24">
                   {/* Calendar Header */}
                    <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                         <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronLeft size={20}/></button>
                         <h3 className="font-bold text-slate-800 capitalize text-lg">
                             {currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                         </h3>
                         <button onClick={() => changeMonth(1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronRight size={20}/></button>
                    </div>

                    {/* Calendar Grid */}
                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2 text-center">
                             {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                                 <span key={d} className="text-xs font-bold text-slate-400">{d}</span>
                             ))}
                        </div>
                        <div className="grid grid-cols-7 gap-1">
                            {Array.from({ length: startDay }).map((_, i) => (
                                <div key={`empty-${i}`} className="aspect-square"></div>
                            ))}
                            {Array.from({ length: daysInMonth }).map((_, i) => {
                                const day = i + 1;
                                const dayActivities = getActivitiesForDay(day);
                                const hasActivity = dayActivities.length > 0;
                                const isSelected = selectedDate && 
                                                   selectedDate.getDate() === day && 
                                                   selectedDate.getMonth() === currentMonth.getMonth();

                                let bgClass = 'bg-white text-slate-600 hover:bg-slate-50 border border-transparent';
                                let textClass = '';

                                if (hasActivity) {
                                    // Color priority: En Progreso > Pendiente > Completada
                                    if (dayActivities.some(a => a.status === 'En Progreso')) {
                                        bgClass = 'bg-orange-50 border border-orange-200 text-orange-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Pendiente')) {
                                        bgClass = 'bg-blue-50 border border-blue-200 text-blue-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Completada')) {
                                        bgClass = 'bg-green-50 border border-green-200 text-green-700 font-bold';
                                    }
                                }

                                const ringClass = isSelected ? 'ring-2 ring-blue-600 ring-offset-2 z-10' : '';

                                return (
                                    <button 
                                        key={day} 
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square flex items-center justify-center rounded-lg transition-all text-sm ${bgClass} ${ringClass}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        {/* Legend */}
                        <div className="mt-6 flex flex-wrap gap-3 text-[10px] text-slate-500 justify-center border-t border-slate-100 pt-4">
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-blue-500"></span> Pendiente</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-orange-500"></span> En Progreso</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-green-500"></span> Completada</div>
                        </div>
                    </div>
               </div>
          </div>

          {/* COLUMN 2: ACTIVITY LIST (Mobile: Bottom, Desktop: Left) */}
          <div className="lg:col-span-2">
              <div className="bg-blue-50/50 border border-blue-100 p-3 rounded-lg text-sm text-blue-800 flex items-center justify-between mb-6">
                  <div className="flex items-center gap-2">
                    <Calendar size={16} />
                    <span>
                        Viendo: <span className="font-bold capitalize">
                            {selectedDate 
                                ? selectedDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' }) 
                                : currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })
                            }
                        </span>
                    </span>
                  </div>
                  {selectedDate && (
                      <button onClick={() => setSelectedDate(null)} className="text-xs bg-white px-2 py-1 rounded border border-blue-200 hover:bg-blue-50 text-blue-600 font-medium flex items-center gap-1">
                          <X size={12}/> Ver todo el mes
                      </button>
                  )}
              </div>

              <div className="space-y-8">
                  {statusOrder.map(status => {
                      const items = groupedActivities[status];
                      if (items.length === 0) return null;

                      return (
                          <div key={status} className="animate-fade-in">
                              <h3 className={`font-bold text-lg mb-4 flex items-center gap-2 
                                ${status === 'Pendiente' ? 'text-blue-700' : 
                                  status === 'En Progreso' ? 'text-orange-700' :
                                  status === 'Completada' ? 'text-green-700' : 'text-slate-600'}
                              `}>
                                  {getStatusIcon(status)} 
                                  {status} 
                                  <span className="text-sm font-normal text-slate-400 bg-white px-2 py-0.5 rounded-full border border-slate-100 shadow-sm ml-2">
                                      {items.length}
                                  </span>
                              </h3>

                              <div className="grid grid-cols-1 gap-4">
                                  {items.map(act => {
                                      const assignee = users.find(u => u.id === act.assigneeId);
                                      return (
                                          <div key={act.id} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 flex flex-col md:flex-row justify-between gap-4 hover:shadow-md transition-shadow relative overflow-hidden group">
                                              {/* Status Stripe */}
                                              <div className={`absolute left-0 top-0 bottom-0 w-1 ${
                                                  status === 'Pendiente' ? 'bg-blue-500' : 
                                                  status === 'En Progreso' ? 'bg-orange-500' :
                                                  status === 'Completada' ? 'bg-green-500' : 'bg-slate-400'
                                              }`}></div>

                                              <div className="flex-1 space-y-2 pl-2">
                                                  <div className="flex items-start justify-between md:justify-start gap-4">
                                                    <h3 className="font-bold text-base text-slate-800">{act.name}</h3>
                                                  </div>
                                                  <p className="text-slate-600 text-sm line-clamp-2">{act.description}</p>

                                                  <div className="flex flex-wrap gap-4 text-xs text-slate-500 mt-2 items-center">
                                                      <div className="flex items-center gap-1 bg-slate-50 px-2 py-1 rounded border border-slate-100">
                                                          <Calendar size={12} className="text-slate-400"/>
                                                          <span className="font-medium text-slate-700">{formatDate(act.startDate)}</span>
                                                      </div>
                                                      <div className="flex items-center gap-1">
                                                          <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-600">
                                                              {assignee?.name.charAt(0)}
                                                          </div>
                                                          {assignee?.name || 'Sin asignar'}
                                                      </div>
                                                      {act.attachments.length > 0 && (
                                                          <div className="flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded">
                                                              <Paperclip size={12} /> {act.attachments.length}
                                                          </div>
                                                      )}
                                                  </div>
                                              </div>

                                              <div className="flex items-center gap-2 border-t pt-3 md:border-t-0 md:pt-0 md:border-l md:pl-4 border-slate-100 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                                  <button onClick={() => handleView(act)} title="Ver Detalle" className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors">
                                                      <Eye size={18} />
                                                  </button>
                                                  {canEdit && (
                                                      <button onClick={() => handleEdit(act)} title="Editar" className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                                          <Edit2 size={18} />
                                                      </button>
                                                  )}
                                                  {canDelete && (
                                                      <button onClick={(e) => handleDelete(act.id, e)} title="Eliminar" className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                                                          <Trash2 size={18} />
                                              </button>
                                                  )}
                                              </div>
                                          </div>
                                      )
                                  })}
                              </div>
                          </div>
                      );
                  })}

                  {processedActivities.length === 0 && (
                      <div className="text-center py-12 bg-white rounded-xl border border-slate-200 border-dashed">
                          <div className="inline-flex p-4 rounded-full bg-slate-50 mb-3">
                              <FileText size={32} className="text-slate-300"/>
                          </div>
                          <p className="text-slate-500 font-medium">No hay actividades para esta fecha.</p>
                          <p className="text-xs text-slate-400 mt-1">Selecciona otro día en el calendario.</p>
                      </div>
                  )}
              </div>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle de Actividad' : (editingActivity.id ? 'Editar Actividad' : 'Nueva Actividad')}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      {/* 1. Nombre */}
                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Nombre Actividad</label>
                          <input 
                              type="text" required
                              disabled={isViewMode}
                              value={editingActivity.name}
                              onChange={e => setEditingActivity({...editingActivity, name: e.target.value})}
                              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              placeholder="Ej: Mantenimiento Riego"
                          />
                      </div>

                      {/* 2. Descripción */}
                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                          <textarea 
                              required
                              disabled={isViewMode}
                              value={editingActivity.description}
                              onChange={e => setEditingActivity({...editingActivity, description: e.target.value})}
                              className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none h-24 disabled:bg-slate-100 disabled:text-slate-500"
                          />
                      </div>

                      {/* 3. Fechas */}
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha Inicio</label>
                              <input 
                                  type="date" required
                                  disabled={isViewMode}
                                  value={editingActivity.startDate}
                                  onChange={e => setEditingActivity({...editingActivity, startDate: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              />
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha Término</label>
                              <input 
                                  type="date" required
                                  disabled={isViewMode}
                                  value={editingActivity.endDate}
                                  onChange={e => setEditingActivity({...editingActivity, endDate: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              />
                          </div>
                      </div>

                      {/* 4. Encargado y Estado */}
                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Encargado</label>
                              <select 
                                  value={editingActivity.assigneeId}
                                  disabled={isViewMode}
                                  onChange={e => setEditingActivity({...editingActivity, assigneeId: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              >
                                  <option value="">Seleccionar...</option>
                                  {users.map(u => (
                                      <option key={u.id} value={u.id}>{u.name}</option>
                                  ))}
                              </select>
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Estado</label>
                              <select 
                                  value={editingActivity.status}
                                  disabled={isViewMode}
                                  onChange={e => setEditingActivity({...editingActivity, status: e.target.value as ActivityStatus})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              >
                                  <option value="Pendiente">Pendiente</option>
                                  <option value="En Progreso">En Progreso</option>
                                  <option value="Completada">Completada</option>
                                  <option value="Cancelada">Cancelada</option>
                              </select>
                          </div>
                      </div>

                      {/* 5. Adjuntos */}
                      <div>
                          <label className="block text-sm font-bold text-slate-700 mb-2">Evidencia y Documentos</label>

                          {!isViewMode && (
                            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors">
                                <input 
                                    type="file" multiple 
                                    id="file-upload" 
                                    className="hidden" 
                                    onChange={handleFileUpload}
                                />
                                <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-2">
                                    <Paperclip className="text-slate-400" size={24} />
                                    <span className="text-blue-600 font-medium">Adjuntar archivos</span>
                                    <span className="text-xs text-slate-400">PDF, JPG, PNG (Max 5MB)</span>
                                </label>
                            </div>
                          )}

                          {editingActivity.attachments && editingActivity.attachments.length > 0 ? (
                              <div className="mt-4 space-y-2">
                                  {editingActivity.attachments.map((file, idx) => (
                                      <div key={idx} className="flex items-center justify-between p-2 bg-slate-50 rounded border border-slate-200 text-sm">
                                          <div className="flex items-center gap-2 truncate">
                                              <FileText size={16} className="text-slate-500" />
                                              <span className="truncate max-w-[300px]">{file.name}</span>
                                          </div>
                                          {!isViewMode && (
                                              <button type="button" onClick={() => removeAttachment(idx)} className="text-red-500 hover:text-red-700">
                                                  <X size={16} />
                                              </button>
                                          )}
                                      </div>
                                  ))}
                              </div>
                          ) : isViewMode && (
                              <div className="text-slate-400 text-sm italic p-2">Sin adjuntos</div>
                          )}
                      </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                      <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                          {isViewMode ? 'Cerrar' : 'Cancelar'}
                      </button>
                      {!isViewMode && (
                        <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <Save size={18} /> Guardar
                        </button>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default ActivitiesPage;

import React, { useEffect, useState } from 'react';
import { MeterReading, User } from '../types';
import { getMeterReadings, saveMeterReading, deleteMeterReading, getUsers } from '../services/dataService';
import { Plus, Trash2, X, Save, Eye, Gauge, Droplets, Zap, Flame, Calendar, MapPin, User as UserIcon, Upload, ImageIcon } from 'lucide-react';
import { useAuth } from '../AuthContext';

const MeterReadingsPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [readings, setReadings] = useState<MeterReading[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingReading, setEditingReading] = useState<Partial<MeterReading>>({});

  // Filters
  const [serviceFilter, setServiceFilter] = useState<string>('Todos');

  const canCreate = permissions?.['Estado Medidores']?.create;
  const canDelete = permissions?.['Estado Medidores']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [data, usrs] = await Promise.all([getMeterReadings(), getUsers()]);
    setReadings(data);
    setUsers(usrs);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingReading({
        userId: currentUser?.id || '',
        date: new Date().toISOString().split('T')[0],
        location: 'Casa Grande',
        serviceType: 'Agua',
        photos: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (reading: MeterReading) => {
    setEditingReading(JSON.parse(JSON.stringify(reading)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (!canDelete) return;

    // 1. Confirmación
    if (confirm('¿Está seguro que desea eliminar este registro de medidor?')) {
        try {
            // 2. Borrado
            await deleteMeterReading(id);
            // 3. Éxito
            alert('Registro eliminado correctamente.');
            loadData();
        } catch (error) {
            // 4. Error
            console.error("Error al eliminar medidor:", error);
            alert("No se pudo eliminar el registro. Intente nuevamente.");
        }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingReading.date && editingReading.photos && editingReading.photos.length > 0) {
        try {
            await saveMeterReading(editingReading as MeterReading);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            console.error("Error al guardar medidor:", error);
            alert("Error al guardar registro.");
        }
    } else if (!editingReading.photos || editingReading.photos.length === 0) {
        alert("Debes subir al menos una foto del medidor.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingReading(prev => ({
                      ...prev,
                      photos: [...(prev.photos || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removePhoto = (index: number) => {
      setEditingReading(prev => ({
          ...prev,
          photos: prev.photos?.filter((_, i) => i !== index)
      }));
  };

  const getUserName = (id: string) => {
      return users.find(u => u.id === id)?.name || 'Usuario desconocido';
  };

  const getServiceIcon = (type?: string) => {
      switch(type) {
          case 'Agua': return <Droplets size={20} className="text-blue-500" />;
          case 'Luz': return <Zap size={20} className="text-yellow-500" />;
          case 'Gas': return <Flame size={20} className="text-orange-500" />;
          default: return <Gauge size={20} className="text-slate-500" />;
      }
  };

  const getServiceColor = (type?: string) => {
      switch(type) {
          case 'Agua': return 'bg-blue-50 border-blue-200 text-blue-700';
          case 'Luz': return 'bg-yellow-50 border-yellow-200 text-yellow-700';
          case 'Gas': return 'bg-orange-50 border-orange-200 text-orange-700';
          default: return 'bg-slate-50 border-slate-200 text-slate-700';
      }
  };

  const filteredReadings = serviceFilter === 'Todos' 
    ? readings 
    : readings.filter(r => r.serviceType === serviceFilter);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <Gauge className="text-slate-600" /> Estado de Medidores
            </h1>
            <p className="text-slate-500">Registro fotográfico de lecturas de servicios básicos.</p>
        </div>

        <div className="flex items-center gap-3">
             <div className="bg-white px-3 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                 <span className="text-sm font-medium text-slate-600">Servicio:</span>
                 <select 
                    value={serviceFilter}
                    onChange={(e) => setServiceFilter(e.target.value)}
                    className="outline-none text-sm font-bold text-slate-800 bg-transparent cursor-pointer"
                 >
                     <option value="Todos">Todos</option>
                     <option value="Agua">Agua</option>
                     <option value="Luz">Luz</option>
                     <option value="Gas">Gas</option>
                 </select>
             </div>
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nuevo Registro</span>
            </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredReadings.map(reading => (
            <div key={reading.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow group">
                {/* Image Cover */}
                <div className="h-48 bg-slate-100 relative overflow-hidden">
                    {reading.photos && reading.photos.length > 0 ? (
                        <img src={reading.photos[0].url} alt="Lectura" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/>
                    ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                            <ImageIcon size={48} />
                        </div>
                    )}
                    <div className="absolute top-3 right-3 bg-black/50 text-white px-2 py-1 rounded-md text-xs backdrop-blur-sm flex items-center gap-1">
                        <ImageIcon size={12} /> {reading.photos.length}
                    </div>
                    <div className="absolute bottom-3 left-3">
                         <span className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 border ${getServiceColor(reading.serviceType)} bg-white`}>
                            {getServiceIcon(reading.serviceType)} {reading.serviceType}
                         </span>
                    </div>
                </div>

                <div className="p-4 space-y-3">
                    <div className="flex justify-between items-start">
                        <div>
                            <h3 className="font-bold text-slate-800 flex items-center gap-1">
                                <MapPin size={16} className="text-slate-400"/> {reading.location}
                            </h3>
                            <p className="text-sm text-slate-500 flex items-center gap-1 mt-1">
                                <Calendar size={14} /> {reading.date}
                            </p>
                        </div>
                    </div>

                    <div className="border-t border-slate-100 pt-3 flex justify-between items-center">
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                             <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center font-bold text-slate-600">
                                 {getUserName(reading.userId).charAt(0)}
                             </div>
                             <span className="truncate max-w-[100px]">{getUserName(reading.userId)}</span>
                        </div>

                        <div className="flex items-center gap-1">
                            <button onClick={() => handleView(reading)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                <Eye size={18} />
                            </button>
                            {canDelete && (
                                <button onClick={(e) => handleDelete(reading.id, e)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                                    <Trash2 size={18} />
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        ))}

        {filteredReadings.length === 0 && (
            <div className="col-span-full py-12 text-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl">
                <Gauge size={48} className="mx-auto mb-3 opacity-30" />
                <p>No se encontraron registros de medidores.</p>
            </div>
        )}
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle Registro' : 'Nuevo Registro de Medidor'}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      <div className="grid grid-cols-2 gap-4">
                           {/* 1. Fecha */}
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha</label>
                              <input 
                                  type="date" required
                                  disabled={isViewMode}
                                  value={editingReading.date}
                                  onChange={e => setEditingReading({...editingReading, date: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              />
                          </div>

                           {/* 2. Usuario (Solo Lectura) */}
                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Reportado Por</label>
                              <div className="w-full p-2 border border-slate-200 bg-slate-50 rounded-lg text-slate-600 flex items-center gap-2">
                                  <UserIcon size={16} />
                                  <span className="text-sm truncate">{getUserName(editingReading.userId!)}</span>
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                           {/* 3. Lugar */}
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Lugar</label>
                              <select 
                                  required
                                  disabled={isViewMode}
                                  value={editingReading.location}
                                  onChange={e => setEditingReading({...editingReading, location: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              >
                                  <option value="Casa Grande">Casa Grande</option>
                                  <option value="Casa Chica">Casa Chica</option>
                              </select>
                          </div>

                           {/* 4. Servicio */}
                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Servicio</label>
                              <select 
                                  required
                                  disabled={isViewMode}
                                  value={editingReading.serviceType}
                                  onChange={e => setEditingReading({...editingReading, serviceType: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none disabled:bg-slate-100 disabled:text-slate-500"
                              >
                                  <option value="Agua">Agua</option>
                                  <option value="Luz">Luz</option>
                                  <option value="Gas">Gas</option>
                              </select>
                          </div>
                      </div>

                      {/* 5. Fotos */}
                      <div>
                          <label className="block text-sm font-bold text-slate-700 mb-2">Fotografías del Medidor</label>

                          {!isViewMode && (
                            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors mb-4">
                                <input 
                                    type="file" multiple accept="image/*"
                                    id="file-upload" 
                                    className="hidden" 
                                    onChange={handleFileUpload}
                                />
                                <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-2">
                                    <Upload className="text-slate-400" size={24} />
                                    <span className="text-blue-600 font-medium">Subir Fotos</span>
                                    <span className="text-xs text-slate-400">JPG, PNG (Max 5MB)</span>
                                </label>
                            </div>
                          )}

                          <div className="grid grid-cols-3 gap-2">
                                {editingReading.photos?.map((photo, idx) => (
                                    <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border border-slate-200 group">
                                        <img src={photo.url} alt="Evidencia" className="w-full h-full object-cover" />
                                        {!isViewMode && (
                                            <button 
                                                type="button" 
                                                onClick={() => removePhoto(idx)}
                                                className="absolute top-1 right-1 bg-red-500 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                <X size={12} />
                                            </button>
                                        )}
                                        {isViewMode && (
                                            <a href={photo.url} download={`medidor_${idx}.png`} className="absolute bottom-1 right-1 bg-black/50 text-white p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity text-xs">
                                                Descargar
                                            </a>
                                        )}
                                    </div>
                                ))}
                                {editingReading.photos?.length === 0 && isViewMode && (
                                    <p className="col-span-3 text-center text-sm text-slate-400 italic py-4">Sin fotos adjuntas.</p>
                                )}
                          </div>
                      </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                      <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                          {isViewMode ? 'Cerrar' : 'Cancelar'}
                      </button>
                      {!isViewMode && (
                        <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <Save size={18} /> Guardar
                        </button>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

