import React, { useEffect, useState } from 'react';
import { getUsers, saveUser, deleteUser, getRoles } from '../services/dataService';
import { User, RoleDef } from '../types';
import { Edit2, Trash2, Plus, X, Save, Eye, Upload, Image as ImageIcon } from 'lucide-react';
import { useAuth } from '../AuthContext';

const UsersPage: React.FC = () => {
  const { permissions } = useAuth();
  const [users, setUsers] = useState<User[]>([]);
  const [roles, setRoles] = useState<RoleDef[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<Partial<User>>({});
  const [isViewMode, setIsViewMode] = useState(false);

  // Permissions
  const canCreate = permissions?.['Usuarios']?.create;
  const canEdit = permissions?.['Usuarios']?.edit;
  const canDelete = permissions?.['Usuarios']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    getUsers().then(setUsers);
    getRoles().then(setRoles);
  };

  const handleView = (user: User) => {
    setEditingUser(user);
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleEdit = (user: User) => {
    if (!canEdit) return;
    setEditingUser({ ...user, password: '' });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingUser({ name: '', email: '', role: 'Trabajador', avatar: '', password: '' });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  // --- LÓGICA DE ELIMINACIÓN ROBUSTA ---
  const handleDelete = async (id: string, e: React.MouseEvent) => {
    // 1. Detener cualquier otro evento (clicks en fila, etc)
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        alert("No tiene permisos para eliminar usuarios.");
        return;
    }

    if (!id) {
        alert("Error: Identificador de usuario no válido.");
        return;
    }

    // 2. Confirmación Explicita
    const confirmed = window.confirm("¿Está SEGURO que desea eliminar este usuario?\n\nSi presiona Aceptar, el registro se borrará permanentemente de la base de datos.");

    if (confirmed) {
        try {
            // 3. Intento de borrado
            await deleteUser(id);

            // 4. Éxito
            alert("Usuario eliminado correctamente.");
            loadData();
        } catch (error: any) {
            // 5. Manejo de Errores (Integridad Referencial)
            console.error("Error al eliminar:", error);

            // Código de error Postgres 23503 = Violación de llave foránea
            if (error?.code === '23503' || JSON.stringify(error).includes('violates foreign key constraint')) {
                alert("NO SE PUDO ELIMINAR EL USUARIO.\n\nRazón: Este usuario tiene registros asociados (Asistencia, Medidores, Actividades, etc.).\n\nSolución: Debe eliminar primero todos los registros creados por o asignados a este usuario.");
            } else {
                alert("Ocurrió un error al intentar eliminar el usuario. Revise la consola para más detalles.");
            }
        }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser.name && editingUser.email) {
      try {
        await saveUser(editingUser as User);
        setIsModalOpen(false);
        loadData();
      } catch (error) {
        console.error("Error saving:", error);
        alert("Error al guardar usuario.");
      }
    }
  };

  const handleAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        if (file.size > 5 * 1024 * 1024) { 
            alert("La imagen es muy pesada. Máximo 5MB.");
            return;
        }
        const reader = new FileReader();
        reader.onloadend = () => {
            setEditingUser(prev => ({ ...prev, avatar: reader.result as string }));
        };
        reader.readAsDataURL(file);
    }
  };

  const UserAvatar = ({ user, size = 'sm' }: { user: Partial<User>, size?: 'sm' | 'lg' }) => {
      const dim = size === 'sm' ? 'w-10 h-10 text-sm' : 'w-32 h-32 text-4xl';
      if (user.avatar) {
        return <img src={user.avatar} alt={user.name} className={`${dim} rounded-full object-cover border border-slate-200 bg-white`} />;
      }
      return (
        <div className={`${dim} rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold border border-indigo-200 select-none`}>
          {user.name ? user.name.charAt(0).toUpperCase() : '?'}
        </div>
      );
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Gestión de Usuarios</h1>
            <p className="text-slate-500">Administra el acceso y la información del personal.</p>
        </div>
        {canCreate && (
          <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors">
            <Plus size={18} /> Nuevo Usuario
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="p-4 font-semibold text-slate-600">Usuario</th>
              <th className="p-4 font-semibold text-slate-600">Email</th>
              <th className="p-4 font-semibold text-slate-600">Rol</th>
              <th className="p-4 font-semibold text-slate-600 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {users.map((user) => (
              <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                <td className="p-4 flex items-center gap-3">
                  <UserAvatar user={user} size="sm" />
                  <span className="font-medium text-slate-800">{user.name}</span>
                </td>
                <td className="p-4 text-slate-600">{user.email}</td>
                <td className="p-4">
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold border
                    ${user.role === 'Admin' ? 'bg-purple-50 text-purple-700 border-purple-200' : 
                      user.role === 'Supervisor' ? 'bg-blue-50 text-blue-700 border-blue-200' : 
                      'bg-green-50 text-green-700 border-green-200'}`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-right space-x-2">
                  <button onClick={() => handleView(user)} className="p-2 hover:bg-emerald-50 rounded text-slate-500 hover:text-emerald-600 transition-colors">
                    <Eye size={18} />
                  </button>
                  {canEdit && (
                    <button onClick={() => handleEdit(user)} className="p-2 hover:bg-blue-50 rounded text-slate-500 hover:text-blue-600 transition-colors">
                      <Edit2 size={18} />
                    </button>
                  )}
                  {canDelete && (
                    <button 
                        onClick={(e) => handleDelete(user.id, e)} 
                        className="p-2 hover:bg-red-50 rounded text-slate-500 hover:text-red-600 transition-colors"
                        title="Eliminar Usuario"
                    >
                      <Trash2 size={18} />
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg p-6 animate-fade-in">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-slate-800">
                {isViewMode ? 'Detalles de Usuario' : (editingUser.id ? 'Editar Usuario' : 'Nuevo Usuario')}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSave} className="space-y-4">
              <div className="flex flex-col items-center gap-4 py-4 border-b border-slate-100 mb-4">
                 <UserAvatar user={editingUser} size="lg" />
                 {!isViewMode && (
                     <div className="flex gap-2">
                        <label className="cursor-pointer bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <Upload size={16} /> Subir Foto
                            <input type="file" className="hidden" accept="image/*" onChange={handleAvatarUpload} />
                        </label>
                        {editingUser.avatar && (
                            <button 
                                type="button"
                                onClick={() => setEditingUser(prev => ({...prev, avatar: ''}))}
                                className="bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-2"
                            >
                                <Trash2 size={16} /> Eliminar
                            </button>
                        )}
                     </div>
                 )}
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nombre Completo</label>
                <input 
                  type="text" required disabled={isViewMode}
                  value={editingUser.name || ''}
                  onChange={e => setEditingUser({...editingUser, name: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
                <input 
                  type="email" required disabled={isViewMode}
                  value={editingUser.email || ''}
                  onChange={e => setEditingUser({...editingUser, email: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                />
              </div>

               {!isViewMode && (
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">
                        {editingUser.id ? 'Nueva Contraseña (opcional)' : 'Contraseña'}
                    </label>
                    <input 
                        type="password" required={!editingUser.id}
                        value={editingUser.password || ''}
                        onChange={e => setEditingUser({...editingUser, password: e.target.value})}
                        className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="••••••••"
                    />
                </div>
               )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Rol</label>
                <select 
                  value={editingUser.role || ''} disabled={isViewMode}
                  onChange={e => setEditingUser({...editingUser, role: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                >
                  {roles.map(r => (
                    <option key={r.id} value={r.name}>{r.name}</option>
                  ))}
                </select>
              </div>

              <div className="pt-4 flex justify-end gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                  {isViewMode ? 'Cerrar' : 'Cancelar'}
                </button>
                {!isViewMode && (
                    <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Guardar
                    </button>
                )}
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UsersPage;

import React, { useEffect, useState } from 'react';
import { getRoles, saveRole, deleteRole, getPermissions } from '../services/dataService';
import { RoleDef, Permission } from '../types';
import { Shield, Plus, Edit2, Trash2, X, Save, Eye } from 'lucide-react';
import { useAuth } from '../AuthContext';

const RolesPage: React.FC = () => {
  const { permissions } = useAuth();
  const [roles, setRoles] = useState<RoleDef[]>([]);
  const [permsData, setPermsData] = useState<Permission[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingRole, setEditingRole] = useState<Partial<RoleDef>>({});

  const canCreate = permissions?.['Roles']?.create;
  const canEdit = permissions?.['Roles']?.edit;
  const canDelete = permissions?.['Roles']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    getRoles().then(setRoles);
    getPermissions().then(setPermsData);
  };

  const handleView = (role: RoleDef) => {
    setEditingRole(role);
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleEdit = (role: RoleDef) => {
    if (!canEdit) return;
    setEditingRole(role);
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleNew = () => {
    if (!canCreate) return;
    const defaultPermId = permsData.length > 0 ? permsData[0].id : '';
    setEditingRole({ name: '', description: '', permissionId: defaultPermId });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  // --- LÓGICA DE ELIMINACIÓN ROBUSTA ---
  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        alert("No tiene permisos para eliminar roles.");
        return;
    }

    if (!id) {
        alert("Error: Identificador de rol no válido.");
        return;
    }

    const confirmed = window.confirm("¿Está SEGURO que desea eliminar este Rol?\n\nSi presiona Aceptar, el rol se borrará permanentemente.");

    if (confirmed) {
      try {
        await deleteRole(id);
        alert("Rol eliminado correctamente.");
        loadData();
      } catch (error: any) {
        console.error("Error al eliminar rol:", error);
        if (error?.code === '23503' || JSON.stringify(error).includes('violates foreign key constraint')) {
            alert("NO SE PUDO ELIMINAR EL ROL.\n\nRazón: Existen usuarios asignados a este rol.\n\nSolución: Primero debe reasignar a todos los usuarios de este rol a otro rol diferente, luego podrá eliminarlo.");
        } else {
            alert("Error desconocido al eliminar el rol.");
        }
      }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingRole.name && editingRole.permissionId) {
      try {
        await saveRole(editingRole as RoleDef);
        setIsModalOpen(false);
        loadData();
      } catch (error) {
        console.error("Error saving role:", error);
        alert("Error al guardar el rol.");
      }
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Roles del Sistema</h1>
            <p className="text-slate-500">Define los roles de trabajo y sus niveles de acceso asociados.</p>
        </div>
        {canCreate && (
          <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2">
            <Plus size={18} /> Nuevo Rol
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="p-4 font-semibold text-slate-600">Nombre del Rol</th>
              <th className="p-4 font-semibold text-slate-600">Descripción</th>
              <th className="p-4 font-semibold text-slate-600">Perfil de Permisos</th>
              <th className="p-4 font-semibold text-slate-600 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {roles.map((role) => {
                const permName = permsData.find(p => p.id === role.permissionId)?.name || 'Sin Asignar';
                return (
                    <tr key={role.id} className="hover:bg-slate-50 transition-colors">
                        <td className="p-4">
                        <div className="flex items-center gap-3">
                            <div className="bg-indigo-100 p-2 rounded-lg text-indigo-600">
                            <Shield size={18} />
                            </div>
                            <span className="font-bold text-slate-800">{role.name}</span>
                        </div>
                        </td>
                        <td className="p-4 text-slate-600">{role.description}</td>
                        <td className="p-4">
                            <span className="bg-slate-100 text-slate-600 px-2 py-1 rounded text-sm border border-slate-200">
                                {permName}
                            </span>
                        </td>
                        <td className="p-4 text-right space-x-2">
                            <button onClick={() => handleView(role)} className="p-2 hover:bg-emerald-50 rounded text-slate-500 hover:text-emerald-600 transition-colors">
                                <Eye size={18} />
                            </button>
                            {canEdit && (
                              <button onClick={() => handleEdit(role)} className="p-2 hover:bg-blue-50 rounded text-slate-500 hover:text-blue-600 transition-colors">
                                  <Edit2 size={18} />
                              </button>
                            )}
                            {canDelete && (
                              <button 
                                onClick={(e) => handleDelete(role.id, e)} 
                                className="p-2 hover:bg-red-50 rounded text-slate-500 hover:text-red-600 transition-colors"
                                title="Eliminar Rol"
                              >
                                  <Trash2 size={18} />
                              </button>
                            )}
                        </td>
                    </tr>
                );
            })}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg p-6 animate-fade-in">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-slate-800">
                  {isViewMode ? 'Detalle Rol' : (editingRole.id ? 'Editar Rol' : 'Nuevo Rol')}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSave} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nombre</label>
                <input 
                  type="text" required disabled={isViewMode}
                  value={editingRole.name || ''}
                  onChange={e => setEditingRole({...editingRole, name: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                <textarea 
                  required disabled={isViewMode}
                  value={editingRole.description || ''}
                  onChange={e => setEditingRole({...editingRole, description: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none h-24 focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Asignar Permiso (Matriz)</label>
                <select 
                  required disabled={isViewMode}
                  value={editingRole.permissionId || ''}
                  onChange={e => setEditingRole({...editingRole, permissionId: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                >
                    <option value="" disabled>Seleccione un perfil de permisos</option>
                    {permsData.map(p => (
                        <option key={p.id} value={p.id}>{p.name}</option>
                    ))}
                </select>
                <p className="text-xs text-slate-500 mt-1">Los permisos se configuran en el módulo "Permisos".</p>
              </div>

              <div className="pt-4 flex justify-end gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                  {isViewMode ? 'Cerrar' : 'Cancelar'}
                </button>
                {!isViewMode && (
                    <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Guardar
                    </button>
                )}
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default RolesPage;

import React, { useEffect, useState } from 'react';
import { getPermissions, savePermission, deletePermission } from '../services/dataService';
import { Permission, APP_ENTITIES } from '../types';
import { Key, Plus, Edit2, Trash2, X, Save, Eye } from 'lucide-react';
import { useAuth } from '../AuthContext';

const PermissionsPage: React.FC = () => {
  const { permissions } = useAuth();
  const [perms, setPerms] = useState<Permission[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingPerm, setEditingPerm] = useState<Partial<Permission>>({});

  const canCreate = permissions?.['Permisos']?.create;
  const canEdit = permissions?.['Permisos']?.edit;
  const canDelete = permissions?.['Permisos']?.delete;

  const defaultMatrix = () => {
    const m: any = {};
    APP_ENTITIES.forEach(e => m[e] = { view: false, create: false, edit: false, delete: false });
    return m;
  };

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    getPermissions().then(setPerms);
  };

  const handleView = (perm: Permission) => {
    setEditingPerm(JSON.parse(JSON.stringify(perm)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleEdit = (perm: Permission) => {
    if (!canEdit) return;
    setEditingPerm(JSON.parse(JSON.stringify(perm)));
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingPerm({ name: '', description: '', matrix: defaultMatrix() });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  // --- LÓGICA DE ELIMINACIÓN ROBUSTA ---
  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        alert("No tiene permisos para eliminar perfiles.");
        return;
    }

    if (!id) {
        alert("Error: Identificador de permiso no válido.");
        return;
    }

    const confirmed = window.confirm("¿Está SEGURO que desea eliminar este Perfil de Permisos?\n\nSi presiona Aceptar, se borrará permanentemente.");

    if (confirmed) {
      try {
        await deletePermission(id);
        alert("Perfil de permisos eliminado correctamente.");
        loadData();
      } catch (error: any) {
        console.error("Error al eliminar permiso:", error);
        if (error?.code === '23503' || JSON.stringify(error).includes('violates foreign key constraint')) {
            alert("NO SE PUDO ELIMINAR EL PERFIL.\n\nRazón: Este perfil está asignado a uno o más Roles.\n\nSolución: Debe asignar otro perfil a esos roles antes de eliminar este.");
        } else {
            alert("Error desconocido al eliminar el permiso.");
        }
      }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingPerm.name && editingPerm.matrix) {
      try {
        await savePermission(editingPerm as Permission);
        setIsModalOpen(false);
        loadData();
      } catch (error) {
        console.error("Error saving permission:", error);
        alert("Error al guardar el perfil de permisos.");
      }
    }
  };

  const toggleMatrix = (entity: string, action: 'view' | 'create' | 'edit' | 'delete') => {
    if (isViewMode) return;
    setEditingPerm(prev => {
        const newMatrix = { ...prev.matrix };
        if (!newMatrix[entity]) {
            newMatrix[entity] = { view: false, create: false, edit: false, delete: false };
        }
        newMatrix[entity] = { ...newMatrix[entity], [action]: !newMatrix[entity][action] };
        return { ...prev, matrix: newMatrix };
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Perfiles de Permisos</h1>
            <p className="text-slate-500">Configura matrices de acceso granular por entidad.</p>
        </div>
        {canCreate && (
          <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2">
            <Plus size={18} /> Nuevo Perfil
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="p-4 font-semibold text-slate-600">Nombre del Perfil</th>
              <th className="p-4 font-semibold text-slate-600">Descripción</th>
              <th className="p-4 font-semibold text-slate-600 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {perms.map((p) => (
              <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                <td className="p-4">
                  <div className="flex items-center gap-3">
                    <div className="bg-orange-100 p-2 rounded-lg text-orange-600">
                      <Key size={18} />
                    </div>
                    <span className="font-bold text-slate-800">{p.name}</span>
                  </div>
                </td>
                <td className="p-4 text-slate-600">{p.description}</td>
                <td className="p-4 text-right space-x-2">
                  <button onClick={() => handleView(p)} className="p-2 hover:bg-emerald-50 rounded text-slate-500 hover:text-emerald-600 transition-colors">
                    <Eye size={18} />
                  </button>
                  {canEdit && (
                    <button onClick={() => handleEdit(p)} className="p-2 hover:bg-blue-50 rounded text-slate-500 hover:text-blue-600 transition-colors">
                      <Edit2 size={18} />
                    </button>
                  )}
                  {canDelete && (
                    <button 
                        onClick={(e) => handleDelete(p.id, e)} 
                        className="p-2 hover:bg-red-50 rounded text-slate-500 hover:text-red-600 transition-colors"
                        title="Eliminar Perfil"
                    >
                      <Trash2 size={18} />
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

       {isModalOpen && editingPerm.matrix && (
        <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh] animate-fade-in">
            <div className="flex justify-between items-center p-6 border-b border-slate-100">
              <h2 className="text-xl font-bold text-slate-800">
                  {isViewMode ? 'Ver Permisos' : (editingPerm.id ? 'Editar Permisos' : 'Nuevo Perfil de Permisos')}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Nombre del Perfil</label>
                    <input 
                        type="text" required disabled={isViewMode}
                        value={editingPerm.name || ''}
                        onChange={e => setEditingPerm({...editingPerm, name: e.target.value})}
                        className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                    <input 
                        type="text" required disabled={isViewMode}
                        value={editingPerm.description || ''}
                        onChange={e => setEditingPerm({...editingPerm, description: e.target.value})}
                        className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                    />
                </div>
              </div>

              <div className="border rounded-lg overflow-hidden">
                <div className="bg-slate-100 p-3 grid grid-cols-5 text-sm font-bold text-slate-700">
                    <div className="col-span-1">Entidad</div>
                    <div className="text-center">Ver</div>
                    <div className="text-center">Crear</div>
                    <div className="text-center">Editar</div>
                    <div className="text-center">Eliminar</div>
                </div>
                <div className="divide-y divide-slate-100">
                    {APP_ENTITIES.map(entity => (
                        <div key={entity} className="p-3 grid grid-cols-5 items-center hover:bg-slate-50">
                            <div className="col-span-1 font-medium text-slate-700 text-sm">{entity}</div>
                            {['view', 'create', 'edit', 'delete'].map((action) => (
                                <div key={action} className="flex justify-center">
                                    <input 
                                        type="checkbox"
                                        disabled={isViewMode}
                                        checked={editingPerm.matrix?.[entity]?.[action as 'view'|'create'|'edit'|'delete'] || false}
                                        onChange={() => toggleMatrix(entity, action as any)}
                                        className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500 cursor-pointer disabled:opacity-50"
                                    />
                                </div>
                            ))}
                        </div>
                    ))}
                </div>
              </div>
            </form>

            <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                  {isViewMode ? 'Cerrar' : 'Cancelar'}
                </button>
                {!isViewMode && (
                    <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Guardar
                    </button>
                )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PermissionsPage;

import React, { useEffect, useState } from 'react';
import { Activity, ActivityStatus, User } from '../types';
import { getActivities, saveActivity, deleteActivity, getUsers } from '../services/dataService';
import { Plus, Edit2, Trash2, X, Save, Paperclip, FileText, Calendar, CheckCircle2, Clock, AlertCircle, Ban, Eye, ChevronLeft, ChevronRight } from 'lucide-react';
import { useAuth } from '../AuthContext';

const ActivitiesPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [activities, setActivities] = useState<Activity[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingActivity, setEditingActivity] = useState<Partial<Activity>>({});

  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  const canCreate = permissions?.['Actividades']?.create;
  const canEdit = permissions?.['Actividades']?.edit;
  const canDelete = permissions?.['Actividades']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [acts, usrs] = await Promise.all([getActivities(), getUsers()]);
    setActivities(acts);
    setUsers(usrs);
  };

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay(); 
  const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const changeMonth = (delta: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + delta, 1);
    setCurrentMonth(newDate);
    setSelectedDate(null);
  };

  const handleDayClick = (day: number) => {
      const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
      if (selectedDate && newDate.getTime() === selectedDate.getTime()) {
          setSelectedDate(null);
      } else {
          setSelectedDate(newDate);
      }
  };

  const getActivitiesForDay = (day: number) => {
      const dateStr = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
      return activities.filter(act => {
          return dateStr >= act.startDate && dateStr <= act.endDate;
      });
  };

  const getProcessedActivities = () => {
      let filtered = [];
      if (selectedDate) {
          const dateStr = selectedDate.toISOString().split('T')[0];
          filtered = activities.filter(act => dateStr >= act.startDate && dateStr <= act.endDate);
      } else {
          const targetMonth = currentMonth.getMonth();
          const targetYear = currentMonth.getFullYear();
          filtered = activities.filter(act => {
              const startParts = act.startDate.split('-');
              const y = parseInt(startParts[0]);
              const m = parseInt(startParts[1]) - 1;
              return y === targetYear && m === targetMonth;
          });
      }
      return filtered.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  const processedActivities = getProcessedActivities();

  const groupedActivities = {
      'Pendiente': processedActivities.filter(a => a.status === 'Pendiente'),
      'En Progreso': processedActivities.filter(a => a.status === 'En Progreso'),
      'Completada': processedActivities.filter(a => a.status === 'Completada'),
      'Cancelada': processedActivities.filter(a => a.status === 'Cancelada'),
  };

  const statusOrder: ActivityStatus[] = ['Pendiente', 'En Progreso', 'Completada', 'Cancelada'];

  const handleNew = () => {
    if (!canCreate) return;
    setEditingActivity({
        name: '',
        startDate: new Date().toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        description: '',
        status: 'Pendiente',
        assigneeId: currentUser?.id || '',
        attachments: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleEdit = (act: Activity) => {
    if (!canEdit) return;
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (act: Activity) => {
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  // --- LÓGICA DE ELIMINACIÓN ROBUSTA ---
  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        alert("No tiene permisos para eliminar actividades.");
        return;
    }

    if (!id) {
        alert("Error: Identificador de actividad inválido.");
        return;
    }

    const confirmed = window.confirm("¿Está SEGURO que desea eliminar esta Actividad?\n\nSi presiona Aceptar, se borrará permanentemente.");

    if (confirmed) {
        try {
            await deleteActivity(id);
            alert("Actividad eliminada correctamente.");
            loadData();
        } catch (error) {
            console.error(error);
            alert("No se pudo eliminar la actividad. Es posible que existan otros registros vinculados a ella.");
        }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingActivity.name && editingActivity.startDate) {
        try {
            await saveActivity(editingActivity as Activity);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            alert("Error al guardar la actividad.");
        }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingActivity(prev => ({
                      ...prev,
                      attachments: [...(prev.attachments || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removeAttachment = (index: number) => {
      setEditingActivity(prev => ({
          ...prev,
          attachments: prev.attachments?.filter((_, i) => i !== index)
      }));
  };

  const getStatusIcon = (status?: ActivityStatus) => {
      switch(status) {
          case 'Pendiente': return <Clock size={14}/>;
          case 'En Progreso': return <AlertCircle size={14}/>;
          case 'Completada': return <CheckCircle2 size={14}/>;
          case 'Cancelada': return <Ban size={14}/>;
          default: return null;
      }
  };

  const formatDate = (dateStr: string | undefined) => {
      if (!dateStr) return '';
      const parts = dateStr.split('-');
      if (parts.length === 3) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return dateStr;
  };

  return (
    <div className="space-y-6">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Actividades y Tareas</h1>
            <p className="text-slate-500">Gestión operativa y planificación.</p>
        </div>

        <div className="flex items-center gap-3">
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nueva Actividad</span>
            </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          <div className="lg:col-span-1 lg:order-last space-y-4">
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden sticky top-24">
                    <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                         <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronLeft size={20}/></button>
                         <h3 className="font-bold text-slate-800 capitalize text-lg">
                             {currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                         </h3>
                         <button onClick={() => changeMonth(1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronRight size={20}/></button>
                    </div>

                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2 text-center">
                             {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                                 <span key={d} className="text-xs font-bold text-slate-400">{d}</span>
                             ))}
                        </div>
                        <div className="grid grid-cols-7 gap-1">
                            {Array.from({ length: startDay }).map((_, i) => (
                                <div key={`empty-${i}`} className="aspect-square"></div>
                            ))}
                            {Array.from({ length: daysInMonth }).map((_, i) => {
                                const day = i + 1;
                                const dayActivities = getActivitiesForDay(day);
                                const hasActivity = dayActivities.length > 0;
                                const isSelected = selectedDate && 
                                                   selectedDate.getDate() === day && 
                                                   selectedDate.getMonth() === currentMonth.getMonth();

                                let bgClass = 'bg-white text-slate-600 hover:bg-slate-50 border border-transparent';
                                if (hasActivity) {
                                    if (dayActivities.some(a => a.status === 'En Progreso')) {
                                        bgClass = 'bg-orange-50 border border-orange-200 text-orange-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Pendiente')) {
                                        bgClass = 'bg-blue-50 border border-blue-200 text-blue-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Completada')) {
                                        bgClass = 'bg-green-50 border border-green-200 text-green-700 font-bold';
                                    }
                                }
                                const ringClass = isSelected ? 'ring-2 ring-blue-600 ring-offset-2 z-10' : '';

                                return (
                                    <button 
                                        key={day} 
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square flex items-center justify-center rounded-lg transition-all text-sm ${bgClass} ${ringClass}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="mt-6 flex flex-wrap gap-3 text-[10px] text-slate-500 justify-center border-t border-slate-100 pt-4">
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-blue-500"></span> Pendiente</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-orange-500"></span> En Progreso</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-green-500"></span> Completada</div>
                        </div>
                    </div>
               </div>
          </div>

          <div className="lg:col-span-2">
              <div className="bg-blue-50/50 border border-blue-100 p-3 rounded-lg text-sm text-blue-800 flex items-center justify-between mb-6">
                  <div className="flex items-center gap-2">
                    <Calendar size={16} />
                    <span>
                        Viendo: <span className="font-bold capitalize">
                            {selectedDate 
                                ? selectedDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' }) 
                                : currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })
                            }
                        </span>
                    </span>
                  </div>
                  {selectedDate && (
                      <button onClick={() => setSelectedDate(null)} className="text-xs bg-white px-2 py-1 rounded border border-blue-200 hover:bg-blue-50 text-blue-600 font-medium flex items-center gap-1">
                          <X size={12}/> Ver todo el mes
                      </button>
                  )}
              </div>

              <div className="space-y-8">
                  {statusOrder.map(status => {
                      const items = groupedActivities[status];
                      if (items.length === 0) return null;

                      return (
                          <div key={status} className="animate-fade-in">
                              <h3 className={`font-bold text-lg mb-4 flex items-center gap-2 
                                ${status === 'Pendiente' ? 'text-blue-700' : 
                                  status === 'En Progreso' ? 'text-orange-700' :
                                  status === 'Completada' ? 'text-green-700' : 'text-slate-600'}
                              `}>
                                  {getStatusIcon(status)} 
                                  {status} 
                                  <span className="text-sm font-normal text-slate-400 bg-white px-2 py-0.5 rounded-full border border-slate-100 shadow-sm ml-2">
                                      {items.length}
                                  </span>
                              </h3>

                              <div className="grid grid-cols-1 gap-4">
                                  {items.map(act => {
                                      const assignee = users.find(u => u.id === act.assigneeId);
                                      return (
                                          <div key={act.id} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 flex flex-col md:flex-row justify-between gap-4 hover:shadow-md transition-shadow relative overflow-hidden group">
                                              <div className={`absolute left-0 top-0 bottom-0 w-1 ${
                                                  status === 'Pendiente' ? 'bg-blue-500' : 
                                                  status === 'En Progreso' ? 'bg-orange-500' :
                                                  status === 'Completada' ? 'bg-green-500' : 'bg-slate-400'
                                              }`}></div>

                                              <div className="flex-1 space-y-2 pl-2">
                                                  <div className="flex items-start justify-between md:justify-start gap-4">
                                                    <h3 className="font-bold text-base text-slate-800">{act.name}</h3>
                                                  </div>
                                                  <p className="text-slate-600 text-sm line-clamp-2">{act.description}</p>

                                                  <div className="flex flex-wrap gap-4 text-xs text-slate-500 mt-2 items-center">
                                                      <div className="flex items-center gap-1 bg-slate-50 px-2 py-1 rounded border border-slate-100">
                                                          <Calendar size={12} className="text-slate-400"/>
                                                          <span className="font-medium text-slate-700">{formatDate(act.startDate)}</span>
                                                      </div>
                                                      <div className="flex items-center gap-1">
                                                          <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-600">
                                                              {assignee?.name.charAt(0)}
                                                          </div>
                                                          {assignee?.name || 'Sin asignar'}
                                                      </div>
                                                      {act.attachments.length > 0 && (
                                                          <div className="flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded">
                                                              <Paperclip size={12} /> {act.attachments.length}
                                                          </div>
                                                      )}
                                                  </div>
                                              </div>

                                              <div className="flex items-center gap-2 border-t pt-3 md:border-t-0 md:pt-0 md:border-l md:pl-4 border-slate-100 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                                  <button onClick={() => handleView(act)} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors">
                                                      <Eye size={18} />
                                                  </button>
                                                  {canEdit && (
                                                      <button onClick={() => handleEdit(act)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                                          <Edit2 size={18} />
                                                      </button>
                                                  )}
                                                  {canDelete && (
                                                      <button 
                                                        onClick={(e) => handleDelete(act.id, e)} 
                                                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                        title="Eliminar Actividad"
                                                      >
                                                          <Trash2 size={18} />
                                                      </button>
                                                  )}
                                              </div>
                                          </div>
                                      )
                                  })}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle de Actividad' : (editingActivity.id ? 'Editar Actividad' : 'Nueva Actividad')}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Nombre Actividad</label>
                          <input 
                              type="text" required disabled={isViewMode}
                              value={editingActivity.name}
                              onChange={e => setEditingActivity({...editingActivity, name: e.target.value})}
                              className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              placeholder="Ej: Mantenimiento Riego"
                          />
                      </div>

                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                          <textarea 
                              required disabled={isViewMode}
                              value={editingActivity.description}
                              onChange={e => setEditingActivity({...editingActivity, description: e.target.value})}
                              className="w-full p-2 border border-slate-300 rounded-lg outline-none h-24 focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                          />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha Inicio</label>
                              <input 
                                  type="date" required disabled={isViewMode}
                                  value={editingActivity.startDate}
