import React, { useEffect, useState } from 'react';
import { MeterReading, User } from '../types';
import { getMeterReadings, saveMeterReading, deleteMeterReading, getUsers } from '../services/dataService';
import { Plus, Trash2, X, Save, Eye, Gauge, Droplets, Zap, Flame, Calendar, MapPin, User as UserIcon, Upload, ImageIcon } from 'lucide-react';
import { useAuth } from '../AuthContext';

const MeterReadingsPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [readings, setReadings] = useState<MeterReading[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingReading, setEditingReading] = useState<Partial<MeterReading>>({});

  const [serviceFilter, setServiceFilter] = useState<string>('Todos');

  const canCreate = permissions?.['Estado Medidores']?.create;
  const canDelete = permissions?.['Estado Medidores']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [data, usrs] = await Promise.all([getMeterReadings(), getUsers()]);
    setReadings(data);
    setUsers(usrs);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingReading({
        userId: currentUser?.id || '',
        date: new Date().toISOString().split('T')[0],
        location: 'Casa Grande',
        serviceType: 'Agua',
        photos: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (reading: MeterReading) => {
    setEditingReading(JSON.parse(JSON.stringify(reading)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  // --- LÓGICA DE ELIMINACIÓN ROBUSTA ---
  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        alert("No tiene permisos para eliminar registros.");
        return;
    }

    if (!id) {
        alert("Error: Identificador inválido.");
        return;
    }

    const confirmed = window.confirm("¿Está SEGURO que desea eliminar este registro de medidor?\n\nSi presiona Aceptar, se borrará permanentemente.");

    if (confirmed) {
        try {
            await deleteMeterReading(id);
            alert("Registro eliminado correctamente.");
            loadData();
        } catch (error) {
            console.error("Error al eliminar medidor:", error);
            alert("No se pudo eliminar el registro. Intente nuevamente o verifique su conexión.");
        }
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingReading.date && editingReading.photos && editingReading.photos.length > 0) {
        try {
            await saveMeterReading(editingReading as MeterReading);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            console.error("Error al guardar medidor:", error);
            alert("Error al guardar registro.");
        }
    } else if (!editingReading.photos || editingReading.photos.length === 0) {
        alert("Debes subir al menos una foto del medidor.");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingReading(prev => ({
                      ...prev,
                      photos: [...(prev.photos || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removePhoto = (index: number) => {
      setEditingReading(prev => ({
          ...prev,
          photos: prev.photos?.filter((_, i) => i !== index)
      }));
  };

  const getUserName = (id: string) => {
      return users.find(u => u.id === id)?.name || 'Usuario desconocido';
  };

  const getServiceIcon = (type?: string) => {
      switch(type) {
          case 'Agua': return <Droplets size={20} className="text-blue-500" />;
          case 'Luz': return <Zap size={20} className="text-yellow-500" />;
          case 'Gas': return <Flame size={20} className="text-orange-500" />;
          default: return <Gauge size={20} className="text-slate-500" />;
      }
  };

  const getServiceColor = (type?: string) => {
      switch(type) {
          case 'Agua': return 'bg-blue-50 border-blue-200 text-blue-700';
          case 'Luz': return 'bg-yellow-50 border-yellow-200 text-yellow-700';
          case 'Gas': return 'bg-orange-50 border-orange-200 text-orange-700';
          default: return 'bg-slate-50 border-slate-200 text-slate-700';
      }
  };

  const filteredReadings = serviceFilter === 'Todos' 
    ? readings 
    : readings.filter(r => r.serviceType === serviceFilter);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <Gauge className="text-slate-600" /> Estado de Medidores
            </h1>
            <p className="text-slate-500">Registro fotográfico de lecturas de servicios básicos.</p>
        </div>

        <div className="flex items-center gap-3">
             <div className="bg-white px-3 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                 <span className="text-sm font-medium text-slate-600">Servicio:</span>
                 <select 
                    value={serviceFilter}
                    onChange={(e) => setServiceFilter(e.target.value)}
                    className="outline-none text-sm font-bold text-slate-800 bg-transparent cursor-pointer"
                 >
                     <option value="Todos">Todos</option>
                     <option value="Agua">Agua</option>
                     <option value="Luz">Luz</option>
                     <option value="Gas">Gas</option>
                 </select>
             </div>
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nuevo Registro</span>
            </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredReadings.map(reading => (
            <div key={reading.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow group">
                <div className="h-48 bg-slate-100 relative overflow-hidden">
                    {reading.photos && reading.photos.length > 0 ? (
                        <img src={reading.photos[0].url} alt="Lectura" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/>
                    ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                            <ImageIcon size={48} />
                        </div>
                    )}
                    <div className="absolute top-3 right-3 bg-black/50 text-white px-2 py-1 rounded-md text-xs backdrop-blur-sm flex items-center gap-1">
                        <ImageIcon size={12} /> {reading.photos.length}
                    </div>
                    <div className="absolute bottom-3 left-3">
                         <span className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 border ${getServiceColor(reading.serviceType)} bg-white`}>
                            {getServiceIcon(reading.serviceType)} {reading.serviceType}
                         </span>
                    </div>
                </div>

                <div className="p-4 space-y-3">
                    <div className="flex justify-between items-start">
                        <div>
                            <h3 className="font-bold text-slate-800 flex items-center gap-1">
                                <MapPin size={16} className="text-slate-400"/> {reading.location}
                            </h3>
                            <p className="text-sm text-slate-500 flex items-center gap-1 mt-1">
                                <Calendar size={14} /> {reading.date}
                            </p>
                        </div>
                    </div>

                    <div className="border-t border-slate-100 pt-3 flex justify-between items-center">
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                             <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center font-bold text-slate-600">
                                 {getUserName(reading.userId).charAt(0)}
                             </div>
                             <span className="truncate max-w-[100px]">{getUserName(reading.userId)}</span>
                        </div>

                        <div className="flex items-center gap-1">
                            <button onClick={() => handleView(reading)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                <Eye size={18} />
                            </button>
                            {canDelete && (
                                <button 
                                    onClick={(e) => handleDelete(reading.id, e)} 
                                    className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Eliminar Registro"
                                >
                                    <Trash2 size={18} />
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        ))}
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle Registro' : 'Nuevo Registro de Medidor'}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha</label>
                              <input 
                                  type="date" required disabled={isViewMode}
                                  value={editingReading.date}
                                  onChange={e => setEditingReading({...editingReading, date: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              />
                          </div>

                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Reportado Por</label>
                              <div className="w-full p-2 border border-slate-200 bg-slate-50 rounded-lg text-slate-600 flex items-center gap-2">
                                  <UserIcon size={16} />
                                  <span className="text-sm truncate">{getUserName(editingReading.userId!)}</span>
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Lugar</label>
                              <select 
                                  required disabled={isViewMode}
                                  value={editingReading.location}
                                  onChange={e => setEditingReading({...editingReading, location: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              >
                                  <option value="Casa Grande">Casa Grande</option>
                                  <option value="Casa Chica">Casa Chica</option>
                              </select>
                          </div>

                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Servicio</label>
                              <select 
                                  required disabled={isViewMode}
                                  value={editingReading.serviceType}
                                  onChange={e => setEditingReading({...editingReading, serviceType: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              >
                                  <option value="Agua">Agua</option>
                                  <option value="Luz">Luz</option>
                                  <option value="Gas">Gas</option>
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-slate-700 mb-2">Fotografías del Medidor</label>
                          {!isViewMode && (
                            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors mb-4">
                                <input 
                                    type="file" multiple accept="image/*"
                                    id="file-upload" 
                                    className="hidden" 
                                    onChange={handleFileUpload}
                                />
                                <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-2">
                                    <Upload className="text-slate-400" size={24} />
                                    <span className="text-blue-600 font-medium">Subir Fotos</span>
                                    <span className="text-xs text-slate-400">JPG, PNG (Max 5MB)</span>
                                </label>
                            </div>
                          )}
                          <div className="grid grid-cols-3 gap-2">
                                {editingReading.photos?.map((photo, idx) => (
                                    <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border border-slate-200 group">
                                        <img src={photo.url} alt="Evidencia" className="w-full h-full object-cover" />
                                        {!isViewMode && (
                                            <button 
                                                type="button" 
                                                onClick={() => removePhoto(idx)}
                                                className="absolute top-1 right-1 bg-red-500 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                <X size={12} />
                                            </button>
                                        )}
                                        {isViewMode && (
                                            <a href={photo.url} download={`medidor_${idx}.png`} className="absolute bottom-1 right-1 bg-black/50 text-white p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity text-xs">
                                                Descargar
                                            </a>
                                        )}
                                    </div>
                                ))}
                          </div>
                      </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                      <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                          {isViewMode ? 'Cerrar' : 'Cancelar'}
                      </button>
                      {!isViewMode && (
                        <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <Save size={18} /> Guardar
                        </button>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

