export default ActivitiesPage;

import React, { useEffect, useState } from 'react';
import { MeterReading, User } from '../types';
import { getMeterReadings, saveMeterReading, deleteMeterReading, getUsers } from '../services/dataService';
import { Plus, Trash2, X, Save, Eye, Gauge, Droplets, Zap, Flame, Calendar, MapPin, User as UserIcon, Upload, ImageIcon } from 'lucide-react';
import { useAuth } from '../AuthContext';
import { ConfirmModal, AlertModal } from '../components/Modals';

const MeterReadingsPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [readings, setReadings] = useState<MeterReading[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingReading, setEditingReading] = useState<Partial<MeterReading>>({});

  const [serviceFilter, setServiceFilter] = useState<string>('Todos');

  // Modals
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [alertState, setAlertState] = useState<{isOpen: boolean, title: string, message: string, type: 'success'|'error'|'info'}>({
      isOpen: false, title: '', message: '', type: 'info'
  });

  const canCreate = permissions?.['Estado Medidores']?.create;
  const canDelete = permissions?.['Estado Medidores']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [data, usrs] = await Promise.all([getMeterReadings(), getUsers()]);
    setReadings(data);
    setUsers(usrs);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingReading({
        userId: currentUser?.id || '',
        date: new Date().toISOString().split('T')[0],
        location: 'Casa Grande',
        serviceType: 'Agua',
        photos: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (reading: MeterReading) => {
    setEditingReading(JSON.parse(JSON.stringify(reading)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  // 1. Trigger
  const handleDeleteClick = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        setAlertState({isOpen: true, title: 'Acceso Denegado', message: 'No tiene permisos para eliminar registros.', type: 'error'});
        return;
    }
    setDeleteId(id);
  };

  // 2. Execute
  const confirmDelete = async () => {
    if (!deleteId) return;

    try {
        await deleteMeterReading(deleteId);
        setAlertState({
            isOpen: true, 
            title: 'Registro Eliminado', 
            message: 'El registro de medidor ha sido eliminado correctamente.', 
            type: 'success'
        });
        loadData();
    } catch (error) {
        console.error("Error al eliminar medidor:", error);
        setAlertState({
            isOpen: true,
            title: 'Error',
            message: 'No se pudo eliminar el registro. Intente nuevamente o verifique su conexión.',
            type: 'error'
        });
    } finally {
        setDeleteId(null);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingReading.date && editingReading.photos && editingReading.photos.length > 0) {
        try {
            await saveMeterReading(editingReading as MeterReading);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            console.error("Error al guardar medidor:", error);
            setAlertState({isOpen: true, title: 'Error', message: 'Error al guardar el registro.', type: 'error'});
        }
    } else if (!editingReading.photos || editingReading.photos.length === 0) {
        setAlertState({isOpen: true, title: 'Falta Foto', message: 'Debes subir al menos una foto del medidor.', type: 'error'});
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingReading(prev => ({
                      ...prev,
                      photos: [...(prev.photos || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removePhoto = (index: number) => {
      setEditingReading(prev => ({
          ...prev,
          photos: prev.photos?.filter((_, i) => i !== index)
      }));
  };

  const getUserName = (id: string) => {
      return users.find(u => u.id === id)?.name || 'Usuario desconocido';
  };

  const getServiceIcon = (type?: string) => {
      switch(type) {
          case 'Agua': return <Droplets size={20} className="text-blue-500" />;
          case 'Luz': return <Zap size={20} className="text-yellow-500" />;
          case 'Gas': return <Flame size={20} className="text-orange-500" />;
          default: return <Gauge size={20} className="text-slate-500" />;
      }
  };

  const getServiceColor = (type?: string) => {
      switch(type) {
          case 'Agua': return 'bg-blue-50 border-blue-200 text-blue-700';
          case 'Luz': return 'bg-yellow-50 border-yellow-200 text-yellow-700';
          case 'Gas': return 'bg-orange-50 border-orange-200 text-orange-700';
          default: return 'bg-slate-50 border-slate-200 text-slate-700';
      }
  };

  const filteredReadings = serviceFilter === 'Todos' 
    ? readings 
    : readings.filter(r => r.serviceType === serviceFilter);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <Gauge className="text-slate-600" /> Estado de Medidores
            </h1>
            <p className="text-slate-500">Registro fotográfico de lecturas de servicios básicos.</p>
        </div>

        <div className="flex items-center gap-3">
             <div className="bg-white px-3 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                 <span className="text-sm font-medium text-slate-600">Servicio:</span>
                 <select 
                    value={serviceFilter}
                    onChange={(e) => setServiceFilter(e.target.value)}
                    className="outline-none text-sm font-bold text-slate-800 bg-transparent cursor-pointer"
                 >
                     <option value="Todos">Todos</option>
                     <option value="Agua">Agua</option>
                     <option value="Luz">Luz</option>
                     <option value="Gas">Gas</option>
                 </select>
             </div>
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nuevo Registro</span>
            </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredReadings.map(reading => (
            <div key={reading.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow group">
                <div className="h-48 bg-slate-100 relative overflow-hidden">
                    {reading.photos && reading.photos.length > 0 ? (
                        <img src={reading.photos[0].url} alt="Lectura" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/>
                    ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                            <ImageIcon size={48} />
                        </div>
                    )}
                    <div className="absolute top-3 right-3 bg-black/50 text-white px-2 py-1 rounded-md text-xs backdrop-blur-sm flex items-center gap-1">
                        <ImageIcon size={12} /> {reading.photos.length}
                    </div>
                    <div className="absolute bottom-3 left-3">
                         <span className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 border ${getServiceColor(reading.serviceType)} bg-white`}>
                            {getServiceIcon(reading.serviceType)} {reading.serviceType}
                         </span>
                    </div>
                </div>

                <div className="p-4 space-y-3">
                    <div className="flex justify-between items-start">
                        <div>
                            <h3 className="font-bold text-slate-800 flex items-center gap-1">
                                <MapPin size={16} className="text-slate-400"/> {reading.location}
                            </h3>
                            <p className="text-sm text-slate-500 flex items-center gap-1 mt-1">
                                <Calendar size={14} /> {reading.date}
                            </p>
                        </div>
                    </div>

                    <div className="border-t border-slate-100 pt-3 flex justify-between items-center">
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                             <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center font-bold text-slate-600">
                                 {getUserName(reading.userId).charAt(0)}
                             </div>
                             <span className="truncate max-w-[100px]">{getUserName(reading.userId)}</span>
                        </div>

                        <div className="flex items-center gap-1">
                            <button onClick={() => handleView(reading)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                <Eye size={18} />
                            </button>
                            {canDelete && (
                                <button 
                                    onClick={(e) => handleDeleteClick(reading.id, e)} 
                                    className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Eliminar Registro"
                                >
                                    <Trash2 size={18} />
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        ))}
      </div>

      <ConfirmModal 
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={confirmDelete}
        title="¿Eliminar Registro?"
        message="¿Está seguro que desea eliminar este registro de medidor? Esta acción no se puede deshacer."
        confirmText="Eliminar"
      />

      <AlertModal
        isOpen={alertState.isOpen}
        onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
        title={alertState.title}
        message={alertState.message}
        type={alertState.type}
      />

      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle Registro' : 'Nuevo Registro de Medidor'}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha</label>
                              <input 
                                  type="date" required disabled={isViewMode}
                                  value={editingReading.date}
                                  onChange={e => setEditingReading({...editingReading, date: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              />
                          </div>

                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Reportado Por</label>
                              <div className="w-full p-2 border border-slate-200 bg-slate-50 rounded-lg text-slate-600 flex items-center gap-2">
                                  <UserIcon size={16} />
                                  <span className="text-sm truncate">{getUserName(editingReading.userId!)}</span>
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Lugar</label>
                              <select 
                                  required disabled={isViewMode}
                                  value={editingReading.location}
                                  onChange={e => setEditingReading({...editingReading, location: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              >
                                  <option value="Casa Grande">Casa Grande</option>
                                  <option value="Casa Chica">Casa Chica</option>
                              </select>
                          </div>

                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Servicio</label>
                              <select 
                                  required disabled={isViewMode}
                                  value={editingReading.serviceType}
                                  onChange={e => setEditingReading({...editingReading, serviceType: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              >
                                  <option value="Agua">Agua</option>
                                  <option value="Luz">Luz</option>
                                  <option value="Gas">Gas</option>
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-slate-700 mb-2">Fotografías del Medidor</label>
                          {!isViewMode && (
                            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors mb-4">
                                <input 
                                    type="file" multiple accept="image/*"
                                    id="file-upload" 
                                    className="hidden" 
                                    onChange={handleFileUpload}
                                />
                                <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-2">
                                    <Upload className="text-slate-400" size={24} />
                                    <span className="text-blue-600 font-medium">Subir Fotos</span>
                                    <span className="text-xs text-slate-400">JPG, PNG (Max 5MB)</span>
                                </label>
                            </div>
                          )}
                          <div className="grid grid-cols-3 gap-2">
                                {editingReading.photos?.map((photo, idx) => (
                                    <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border border-slate-200 group">
                                        <img src={photo.url} alt="Evidencia" className="w-full h-full object-cover" />
                                        {!isViewMode && (
                                            <button 
                                                type="button" 
                                                onClick={() => removePhoto(idx)}
                                                className="absolute top-1 right-1 bg-red-500 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                <X size={12} />
                                            </button>
                                        )}
                                        {isViewMode && (
                                            <a href={photo.url} download={`medidor_${idx}.png`} className="absolute bottom-1 right-1 bg-black/50 text-white p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity text-xs">
                                                Descargar
                                            </a>
                                        )}
                                    </div>
                                ))}
                          </div>
                      </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                      <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                          {isViewMode ? 'Cerrar' : 'Cancelar'}
                      </button>
                      {!isViewMode && (
                        <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <Save size={18} /> Guardar
                        </button>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default MeterReadingsPage;

import React, { useEffect, useState } from 'react';
import { MeterReading, User } from '../types';
import { getMeterReadings, saveMeterReading, deleteMeterReading, getUsers } from '../services/dataService';
import { Plus, Trash2, X, Save, Eye, Gauge, Droplets, Zap, Flame, Calendar, MapPin, User as UserIcon, Upload, ImageIcon, ZoomIn } from 'lucide-react';
import { useAuth } from '../AuthContext';
import { ConfirmModal, AlertModal } from '../components/Modals';

const MeterReadingsPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [readings, setReadings] = useState<MeterReading[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Modal de Edición/Creación
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingReading, setEditingReading] = useState<Partial<MeterReading>>({});

  // Modal de Previsualización de Imagen
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // Filtros
  const [serviceFilter, setServiceFilter] = useState<string>('Todos');

  // Modals Alertas
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [alertState, setAlertState] = useState<{isOpen: boolean, title: string, message: string, type: 'success'|'error'|'info'}>({
      isOpen: false, title: '', message: '', type: 'info'
  });

  const canCreate = permissions?.['Estado Medidores']?.create;
  const canDelete = permissions?.['Estado Medidores']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [data, usrs] = await Promise.all([getMeterReadings(), getUsers()]);
    // Asegurar ordenamiento DESC por fecha
    const sortedData = data.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    setReadings(sortedData);
    setUsers(usrs);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingReading({
        userId: currentUser?.id || '',
        date: new Date().toISOString().split('T')[0],
        location: 'Casa Grande',
        serviceType: 'Agua',
        photos: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (reading: MeterReading) => {
    setEditingReading(JSON.parse(JSON.stringify(reading)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  // --- LÓGICA DE ELIMINACIÓN ---
  const handleDeleteClick = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        setAlertState({isOpen: true, title: 'Acceso Denegado', message: 'No tiene permisos para eliminar registros.', type: 'error'});
        return;
    }
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;

    try {
        await deleteMeterReading(deleteId);
        setAlertState({
            isOpen: true, 
            title: 'Registro Eliminado', 
            message: 'El registro de medidor ha sido eliminado correctamente.', 
            type: 'success'
        });
        loadData();
    } catch (error) {
        console.error("Error al eliminar medidor:", error);
        setAlertState({
            isOpen: true,
            title: 'Error',
            message: 'No se pudo eliminar el registro. Intente nuevamente.',
            type: 'error'
        });
    } finally {
        setDeleteId(null);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingReading.date && editingReading.photos && editingReading.photos.length > 0) {
        try {
            await saveMeterReading(editingReading as MeterReading);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            console.error("Error al guardar medidor:", error);
            setAlertState({isOpen: true, title: 'Error', message: 'Error al guardar el registro.', type: 'error'});
        }
    } else if (!editingReading.photos || editingReading.photos.length === 0) {
        setAlertState({isOpen: true, title: 'Falta Foto', message: 'Debes subir al menos una foto del medidor.', type: 'error'});
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingReading(prev => ({
                      ...prev,
                      photos: [...(prev.photos || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removePhoto = (index: number) => {
      setEditingReading(prev => ({
          ...prev,
          photos: prev.photos?.filter((_, i) => i !== index)
      }));
  };

  const getUserName = (id: string) => {
      return users.find(u => u.id === id)?.name || 'Usuario desconocido';
  };

  const getServiceIcon = (type?: string) => {
      switch(type) {
          case 'Agua': return <Droplets size={16} className="text-blue-500" />;
          case 'Luz': return <Zap size={16} className="text-yellow-500" />;
          case 'Gas': return <Flame size={16} className="text-orange-500" />;
          default: return <Gauge size={16} className="text-slate-500" />;
      }
  };

  const getServiceColor = (type?: string) => {
      switch(type) {
          case 'Agua': return 'bg-blue-50 border-blue-200 text-blue-700';
          case 'Luz': return 'bg-yellow-50 border-yellow-200 text-yellow-700';
          case 'Gas': return 'bg-orange-50 border-orange-200 text-orange-700';
          default: return 'bg-slate-50 border-slate-200 text-slate-700';
      }
  };

  // --- ESTRUCTURA DE AGRUPAMIENTO ---
  const locations = ['Casa Grande', 'Casa Chica'];
  const services = ['Agua', 'Luz', 'Gas'];

  const getFilteredReadings = (location: string, service: string) => {
      return readings.filter(r => {
          const locMatch = r.location === location;
          const srvMatch = r.serviceType === service;

          // Si el filtro global está activo, respetarlo
          if (serviceFilter !== 'Todos' && r.serviceType !== serviceFilter) return false;

          return locMatch && srvMatch;
      });
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <Gauge className="text-slate-600" /> Estado de Medidores
            </h1>
            <p className="text-slate-500">Registro fotográfico histórico por ubicación y servicio.</p>
        </div>

        <div className="flex items-center gap-3">
             <div className="bg-white px-3 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                 <span className="text-sm font-medium text-slate-600">Filtrar:</span>
                 <select 
                    value={serviceFilter}
                    onChange={(e) => setServiceFilter(e.target.value)}
                    className="outline-none text-sm font-bold text-slate-800 bg-transparent cursor-pointer"
                 >
                     <option value="Todos">Todos</option>
                     <option value="Agua">Agua</option>
                     <option value="Luz">Luz</option>
                     <option value="Gas">Gas</option>
                 </select>
             </div>
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nuevo Registro</span>
            </button>
            )}
        </div>
      </div>

      {/* --- VISTA AGRUPADA --- */}
      <div className="space-y-12">
        {locations.map(location => {
            // Verificar si esta ubicación tiene datos visibles (para no renderizar secciones vacías si se filtra)
            const hasDataInLocation = services.some(srv => getFilteredReadings(location, srv).length > 0);
            if (!hasDataInLocation) return null;

            return (
                <div key={location} className="animate-fade-in">
                    <div className="flex items-center gap-3 mb-6 pb-2 border-b border-slate-300">
                        <MapPin className="text-slate-400" size={24} />
                        <h2 className="text-2xl font-bold text-slate-800">{location}</h2>
                    </div>

                    <div className="space-y-8 pl-4 border-l-2 border-slate-100">
                        {services.map(service => {
                            const items = getFilteredReadings(location, service);
                            if (items.length === 0) return null;

                            return (
                                <div key={service}>
                                    <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                                        {getServiceIcon(service)} {service} 
                                        <span className="bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full text-xs font-normal border border-slate-200">{items.length}</span>
                                    </h3>

                                    {/* --- GRID DE TARJETAS --- */}
                                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                                        {items.map(reading => (
                                            <div key={reading.id} className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow group flex flex-col">

                                                {/* Imagen (Click para Preview) */}
                                                <div className="h-32 bg-slate-100 relative overflow-hidden cursor-pointer" onClick={() => reading.photos?.[0] && setPreviewImage(reading.photos[0].url)}>
                                                    {reading.photos && reading.photos.length > 0 ? (
                                                        <>
                                                            <img src={reading.photos[0].url} alt="Lectura" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/>
                                                            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                                                                <ZoomIn className="text-white drop-shadow-md" size={24}/>
                                                            </div>
                                                        </>
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                                                            <ImageIcon size={32} />
                                                        </div>
                                                    )}

                                                    {/* Badge de Cantidad de Fotos */}
                                                    {reading.photos && reading.photos.length > 1 && (
                                                        <div className="absolute top-2 right-2 bg-black/60 text-white px-1.5 py-0.5 rounded text-[10px] backdrop-blur-sm flex items-center gap-1">
                                                            <ImageIcon size={10} /> +{reading.photos.length - 1}
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Info Card */}
                                                <div className="p-3 flex-1 flex flex-col justify-between">
                                                    <div>
                                                        <div className="flex items-center gap-1.5 text-xs text-slate-500 mb-1">
                                                            <Calendar size={12} /> {reading.date}
                                                        </div>
                                                    </div>

                                                    <div className="border-t border-slate-100 pt-2 mt-2 flex justify-between items-center">
                                                        <div className="flex items-center gap-1.5 overflow-hidden">
                                                             <div className="w-5 h-5 rounded-full bg-slate-100 flex items-center justify-center font-bold text-[10px] text-slate-500 shrink-0">
                                                                 {getUserName(reading.userId).charAt(0)}
                                                             </div>
                                                             <span className="truncate text-xs text-slate-600 max-w-[60px]">{getUserName(reading.userId).split(' ')[0]}</span>
                                                        </div>

                                                        <div className="flex items-center gap-1">
                                                            <button onClick={() => handleView(reading)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                                                <Eye size={16} />
                                                            </button>
                                                            {canDelete && (
                                                                <button 
                                                                    onClick={(e) => handleDeleteClick(reading.id, e)} 
                                                                    className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                                >
                                                                    <Trash2 size={16} />
                                                                </button>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            );
        })}

        {readings.length === 0 && (
            <div className="col-span-full py-12 text-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl">
                <Gauge size={48} className="mx-auto mb-3 opacity-30" />
                <p>No se encontraron registros de medidores.</p>
            </div>
        )}
      </div>

      {/* --- MODALS --- */}

      <ConfirmModal 
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={confirmDelete}
        title="¿Eliminar Registro?"
        message="¿Está seguro que desea eliminar este registro de medidor? Esta acción no se puede deshacer."
        confirmText="Eliminar"
      />

      <AlertModal
        isOpen={alertState.isOpen}
        onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
        title={alertState.title}
        message={alertState.message}
        type={alertState.type}
      />

      {/* Image Preview Modal (Lightbox) */}
      {previewImage && (
          <div 
            className="fixed inset-0 z-[150] bg-black/90 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in"
            onClick={() => setPreviewImage(null)}
          >
              <button 
                onClick={() => setPreviewImage(null)}
                className="absolute top-4 right-4 text-white/70 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors"
              >
                  <X size={32} />
              </button>
              <img 
                src={previewImage} 
                alt="Vista Previa" 
                className="max-w-full max-h-[90vh] object-contain rounded shadow-2xl"
                onClick={(e) => e.stopPropagation()} // Evitar cerrar al hacer click en la imagen
              />
          </div>
      )}

      {/* Edit/Create Modal */}
      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle Registro' : 'Nuevo Registro de Medidor'}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha</label>
                              <input 
                                  type="date" required disabled={isViewMode}
                                  value={editingReading.date}
                                  onChange={e => setEditingReading({...editingReading, date: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100 disabled:text-slate-500"
                              />
                          </div>

                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Reportado Por</label>
                              <div className="w-full p-2 border border-slate-200 bg-slate-50 rounded-lg text-slate-600 flex items-center gap-2">
                                  <UserIcon size={16} />
                                  <span className="text-sm truncate">{getUserName(editingReading.userId!)}</span>
                              </div>
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Lugar</label>
                              <select 
                                  required disabled={isViewMode}
                                  value={editingReading.location}
                                  onChange={e => setEditingReading({...editingReading, location: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100 disabled:text-slate-500"
                              >
                                  <option value="Casa Grande">Casa Grande</option>
                                  <option value="Casa Chica">Casa Chica</option>
                              </select>
                          </div>

                           <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Servicio</label>
                              <select 
                                  required disabled={isViewMode}
                                  value={editingReading.serviceType}
                                  onChange={e => setEditingReading({...editingReading, serviceType: e.target.value as any})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100 disabled:text-slate-500"
                              >
                                  <option value="Agua">Agua</option>
                                  <option value="Luz">Luz</option>
                                  <option value="Gas">Gas</option>
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-slate-700 mb-2">Fotografías del Medidor</label>
                          {!isViewMode && (
                            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors mb-4">
                                <input 
                                    type="file" multiple accept="image/*"
                                    id="file-upload" 
                                    className="hidden" 
                                    onChange={handleFileUpload}
                                />
                                <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-2">
                                    <Upload className="text-slate-400" size={24} />
                                    <span className="text-blue-600 font-medium">Subir Fotos</span>
                                    <span className="text-xs text-slate-400">JPG, PNG (Max 5MB)</span>
                                </label>
                            </div>
                          )}
                          <div className="grid grid-cols-3 gap-2">
                                {editingReading.photos?.map((photo, idx) => (
                                    <div key={idx} className="relative aspect-square rounded-lg overflow-hidden border border-slate-200 group">
                                        <img 
                                            src={photo.url} 
                                            alt="Evidencia" 
                                            className="w-full h-full object-cover cursor-pointer" 
                                            onClick={() => setPreviewImage(photo.url)}
                                        />
                                        {!isViewMode && (
                                            <button 
                                                type="button" 
                                                onClick={() => removePhoto(idx)}
                                                className="absolute top-1 right-1 bg-red-500 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                            >
                                                <X size={12} />
                                            </button>
                                        )}
                                    </div>
                                ))}
                          </div>
                          {editingReading.photos?.length === 0 && isViewMode && (
                              <p className="text-center text-sm text-slate-400 italic">No hay fotos adjuntas.</p>
                          )}
                      </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                      <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                          {isViewMode ? 'Cerrar' : 'Cancelar'}
                      </button>
                      {!isViewMode && (
                        <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <Save size={18} /> Guardar
                        </button>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default MeterReadingsPage;

import React, { useState, useEffect, useRef } from 'react';
import { User, AttendanceRecord, AttendanceLog } from '../types';
import { getUsers, getAttendanceByRange, getAttendanceLogs } from '../services/dataService';
import { ChevronLeft, ChevronRight, Search, Calendar, MapPin, Tablet, Printer, Loader2 } from 'lucide-react';
import { useAuth } from '../AuthContext';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

const Attendance: React.FC = () => {
  const { permissions } = useAuth();

  // Search State
  const [users, setUsers] = useState<User[]>([]);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Data State
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [logs, setLogs] = useState<AttendanceLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [generatingPdf, setGeneratingPdf] = useState(false);

  // Calendar View State
  const [currentCalendarDate, setCurrentCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);

  // PDF Report Ref
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    getUsers().then(data => {
      setUsers(data);
      // Default to Alfonso (ID 1) as he has most data in the sample
      const defaultUser = data.find(u => u.id === '1') || data[0];
      if (defaultUser) setSelectedUser(defaultUser.id);

      // Default Dates: Today
      const today = new Date();
      // Adjust for local timezone to ensure we get the correct "today" string yyyy-mm-dd
      const localToday = new Date(today.getTime() - (today.getTimezoneOffset() * 60000));
      const todayStr = localToday.toISOString().split('T')[0];

      setStartDate(todayStr);
      setEndDate(todayStr);

      setCurrentCalendarDate(new Date(today.getFullYear(), today.getMonth(), 1));
    });
  }, []);

  // Fetch logs when a day is selected
  useEffect(() => {
    if (selectedDay && selectedUser) {
        const dateStr = selectedDay.toISOString().split('T')[0];
        getAttendanceLogs(selectedUser, dateStr).then(setLogs);
    } else {
        setLogs([]);
    }
  }, [selectedDay, selectedUser]);

  const handleSearch = async () => {
    if (!selectedUser || !startDate || !endDate) {
        alert("Por favor seleccione usuario y rango de fechas");
        return;
    }

    setLoading(true);
    setHasSearched(true);
    // Reset selection to clear previous detail view
    setSelectedDay(null); 

    // Sync calendar view to start date
    const startObj = new Date(startDate);
    // Fix timezone offset issue for calendar navigation
    const startObjUTC = new Date(startObj.getUTCFullYear(), startObj.getUTCMonth(), 1);
    setCurrentCalendarDate(startObjUTC);

    try {
        const data = await getAttendanceByRange(selectedUser, startDate, endDate);
        setRecords(data);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const daysInMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), 1).getDay(); 

  // Fix: Calendar uses Sunday as 0. Our header is Dom, Lun... so we use standard getDay()
  const startDay = firstDayOfMonth; 

  const handleDayClick = (day: number) => {
    const newDate = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), day);
    setSelectedDay(newDate);
  };

  const changeMonth = (delta: number) => {
    setCurrentCalendarDate(new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + delta, 1));
    setSelectedDay(null);
  };

  const getRecordForDay = (day: number) => {
    const dateStr = `${currentCalendarDate.getFullYear()}-${String(currentCalendarDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    // Check if record exists in the fetched data
    return records.find(r => r.date === dateStr);
  };

  const selectedDateStr = selectedDay ? selectedDay.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
  const selectedISODate = selectedDay ? selectedDay.toISOString().split('T')[0] : '';
  const currentRecord = records.find(r => r.date === selectedISODate);

  // --- Logic for navigation restriction ---
  // Normalize dates to the first of the month for comparison
  const getMonthTime = (d: Date) => new Date(d.getFullYear(), d.getMonth(), 1).getTime();

  const currentMonthTime = getMonthTime(currentCalendarDate);
  const startMonthTime = startDate ? getMonthTime(new Date(startDate)) : -Infinity;
  const endMonthTime = endDate ? getMonthTime(new Date(endDate)) : Infinity;

  const canGoBack = currentMonthTime > startMonthTime;
  const canGoForward = currentMonthTime < endMonthTime;

  // Helper for Print View
  const getSelectedUserInfo = () => users.find(u => u.id === selectedUser);

  // Generate PDF Handler
  const handlePrint = async () => {
    if (!reportRef.current) return;

    try {
        setGeneratingPdf(true);

        // Wait a bit to ensure rendering
        await new Promise(resolve => setTimeout(resolve, 200));

        // Get elements
        const headerPart = document.getElementById('report-part-1');
        const tablePart = document.getElementById('report-part-2');

        const pdf = new jsPDF('p', 'mm', 'a4');
        const pageWidth = 210;
        const pageHeight = 297;

        // Render Header & Info (Part 1)
        let currentY = 0;
        if (headerPart) {
            const canvas1 = await html2canvas(headerPart, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            // Full width image
            const imgH1 = (canvas1.height * pageWidth) / canvas1.width;

            pdf.addImage(canvas1.toDataURL('image/png'), 'PNG', 0, 0, pageWidth, imgH1);
            currentY = imgH1; 
        }

        // Render Table (Part 2)
        if (tablePart && selectedDay) {
            const canvas2 = await html2canvas(tablePart, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            // Align widths by using full page width (padding handled by CSS)
            const imgH2 = (canvas2.height * pageWidth) / canvas2.width;

            // Check if it fits on the current page
            const spaceLeft = pageHeight - currentY;

            if (imgH2 > spaceLeft) {
                // Not enough space? Add new page and reset Y
                pdf.addPage();
                currentY = 0;
            }

            pdf.addImage(canvas2.toDataURL('image/png'), 'PNG', 0, currentY, pageWidth, imgH2);
        }

        const userName = getSelectedUserInfo()?.name.replace(/\s+/g, '_') || 'Reporte';
        pdf.save(`Asistencia_${userName}_${currentCalendarDate.getMonth()+1}_${currentCalendarDate.getFullYear()}.pdf`);

    } catch (error) {
        console.error("Error generating PDF:", error);
        alert("Hubo un error al generar el PDF. Por favor intente nuevamente.");
    } finally {
        setGeneratingPdf(false);
    }
  };

  return (
