        .gte('date_time', `${date} 00:00:00`)
        .lte('date_time', `${date} 23:59:59`)
        .order('date_time', { ascending: true });

    if (error) throw error;

    return data.map((l: any) => ({
        id: l.id,
        userId: l.user_id,
