import { ConfirmModal, AlertModal } from '../components/Modals';

const UsersPage: React.FC = () => {
  const { permissions } = useAuth();
  const [users, setUsers] = useState<User[]>([]);
  const [roles, setRoles] = useState<RoleDef[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<Partial<User>>({});
  const [isViewMode, setIsViewMode] = useState(false);

  // States for Custom Modals
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [alertState, setAlertState] = useState<{isOpen: boolean, title: string, message: string, type: 'success'|'error'|'info'}>({
      isOpen: false, title: '', message: '', type: 'info'
  });

  const canCreate = permissions?.['Usuarios']?.create;
  const canEdit = permissions?.['Usuarios']?.edit;
  const canDelete = permissions?.['Usuarios']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = () => {
    getUsers().then(setUsers);
    getRoles().then(setRoles);
  };

  const handleView = (user: User) => {
    setEditingUser(user);
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  const handleEdit = (user: User) => {
    if (!canEdit) return;
    setEditingUser({ ...user, password: '' });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleNew = () => {
    if (!canCreate) return;
    setEditingUser({ name: '', email: '', role: 'Trabajador', avatar: '', password: '', active: true });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  // 1. Trigger Delete (Opens Confirm Modal)
  const handleDeleteClick = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        setAlertState({isOpen: true, title: 'Acceso Denegado', message: 'No tiene permisos para eliminar usuarios.', type: 'error'});
        return;
    }
    setDeleteId(id);
  };

  // 2. Execute Delete (Called by Modal) - LOGIC DELETE
  const confirmDelete = async () => {
    if (!deleteId) return;

    try {
        await deleteUser(deleteId);
        setAlertState({
            isOpen: true, 
            title: 'Usuario Desactivado', 
            message: 'El usuario ha sido desactivado correctamente. No podrá ingresar al sistema hasta que sea reactivado.', 
            type: 'success'
        });
        loadData();
    } catch (error: any) {
        console.error("Error al eliminar:", error);
        setAlertState({
            isOpen: true,
            title: 'Error del Sistema',
            message: 'Ocurrió un error inesperado al intentar desactivar el usuario.',
            type: 'error'
        });
    } finally {
        setDeleteId(null);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser.name && editingUser.email) {
      try {
        await saveUser(editingUser as User);
        setIsModalOpen(false);
        loadData();
      } catch (error) {
        setAlertState({isOpen: true, title: 'Error', message: 'No se pudo guardar el usuario.', type: 'error'});
      }
    }
  };

  const handleAvatarUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        if (file.size > 5 * 1024 * 1024) { 
            setAlertState({isOpen: true, title: 'Archivo muy pesado', message: 'La imagen no debe superar los 5MB.', type: 'error'});
            return;
        }
        const reader = new FileReader();
        reader.onloadend = () => {
            setEditingUser(prev => ({ ...prev, avatar: reader.result as string }));
        };
        reader.readAsDataURL(file);
    }
  };

  const UserAvatar = ({ user, size = 'sm' }: { user: Partial<User>, size?: 'sm' | 'lg' }) => {
      const dim = size === 'sm' ? 'w-10 h-10 text-sm' : 'w-32 h-32 text-4xl';
      if (user.avatar) {
        return <img src={user.avatar} alt={user.name} className={`${dim} rounded-full object-cover border border-slate-200 bg-white`} />;
      }
      return (
        <div className={`${dim} rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold border border-indigo-200 select-none`}>
          {user.name ? user.name.charAt(0).toUpperCase() : '?'}
        </div>
      );
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Gestión de Usuarios</h1>
            <p className="text-slate-500">Administra el acceso y la información del personal.</p>
        </div>
        {canCreate && (
          <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors">
            <Plus size={18} /> Nuevo Usuario
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="p-4 font-semibold text-slate-600">Usuario</th>
              <th className="p-4 font-semibold text-slate-600">Email</th>
              <th className="p-4 font-semibold text-slate-600">Rol</th>
              <th className="p-4 font-semibold text-slate-600">Estado</th>
              <th className="p-4 font-semibold text-slate-600 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {users.map((user) => (
              <tr key={user.id} className={`hover:bg-slate-50 transition-colors ${!user.active ? 'opacity-60 bg-slate-50/50' : ''}`}>
                <td className="p-4 flex items-center gap-3">
                  <UserAvatar user={user} size="sm" />
                  <span className="font-medium text-slate-800">{user.name}</span>
                </td>
                <td className="p-4 text-slate-600">{user.email}</td>
                <td className="p-4">
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold border
                    ${user.role === 'Admin' ? 'bg-purple-50 text-purple-700 border-purple-200' : 
                      user.role === 'Supervisor' ? 'bg-blue-50 text-blue-700 border-blue-200' : 
                      'bg-green-50 text-green-700 border-green-200'}`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4">
                     {user.active ? (
                         <span className="inline-flex items-center gap-1 text-xs font-bold text-green-600 bg-green-50 px-2 py-1 rounded border border-green-200">
                             <span className="w-2 h-2 bg-green-500 rounded-full"></span> Activo
                         </span>
                     ) : (
                         <span className="inline-flex items-center gap-1 text-xs font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded border border-slate-200">
                             <span className="w-2 h-2 bg-slate-400 rounded-full"></span> Inactivo
                         </span>
                     )}
                </td>
                <td className="p-4 text-right space-x-2">
                  <button onClick={() => handleView(user)} className="p-2 hover:bg-emerald-50 rounded text-slate-500 hover:text-emerald-600 transition-colors">
                    <Eye size={18} />
                  </button>
                  {canEdit && (
                    <button onClick={() => handleEdit(user)} className="p-2 hover:bg-blue-50 rounded text-slate-500 hover:text-blue-600 transition-colors">
                      <Edit2 size={18} />
                    </button>
                  )}
                  {canDelete && user.active && (
                    <button 
                        onClick={(e) => handleDeleteClick(user.id, e)} 
                        className="p-2 hover:bg-red-50 rounded text-slate-500 hover:text-red-600 transition-colors"
                        title="Desactivar Usuario"
                    >
                      <Trash2 size={18} />
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* MODALS */}
      <ConfirmModal 
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={confirmDelete}
        title="¿Desactivar Usuario?"
        message="¿Está seguro que desea desactivar este usuario? No podrá iniciar sesión en el sistema, pero sus registros históricos se mantendrán."
        confirmText="Sí, Desactivar"
        isDestructive={true}
      />

      <AlertModal
        isOpen={alertState.isOpen}
        onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
        title={alertState.title}
        message={alertState.message}
        type={alertState.type}
      />

      {/* EDIT MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg p-6 animate-fade-in">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-slate-800">
                {isViewMode ? 'Detalles de Usuario' : (editingUser.id ? 'Editar Usuario' : 'Nuevo Usuario')}
              </h2>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSave} className="space-y-4">
              <div className="flex flex-col items-center gap-4 py-4 border-b border-slate-100 mb-4">
                 <UserAvatar user={editingUser} size="lg" />
                 {!isViewMode && (
                     <div className="flex gap-2">
                        <label className="cursor-pointer bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-2">
                            <Upload size={16} /> Subir Foto
                            <input type="file" className="hidden" accept="image/*" onChange={handleAvatarUpload} />
                        </label>
                        {editingUser.avatar && (
                            <button 
                                type="button"
                                onClick={() => setEditingUser(prev => ({...prev, avatar: ''}))}
                                className="bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-2"
                            >
                                <Trash2 size={16} /> Eliminar
                            </button>
                        )}
                     </div>
                 )}
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Nombre Completo</label>
                    <input 
                      type="text" required disabled={isViewMode}
                      value={editingUser.name || ''}
                      onChange={e => setEditingUser({...editingUser, name: e.target.value})}
                      className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Estado</label>
                    <div className="flex items-center gap-2 mt-2">
                         <button 
                             type="button"
                             disabled={isViewMode}
                             onClick={() => setEditingUser(prev => ({...prev, active: !prev.active}))}
                             className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${editingUser.active ? 'bg-green-500' : 'bg-slate-300'} ${isViewMode ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
                         >
                             <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${editingUser.active ? 'translate-x-6' : 'translate-x-1'}`} />
                         </button>
                         <span className="text-sm text-slate-600 font-medium">
                             {editingUser.active ? 'Activo' : 'Inactivo'}
                         </span>
                    </div>
                  </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
                <input 
                  type="email" required disabled={isViewMode}
                  value={editingUser.email || ''}
                  onChange={e => setEditingUser({...editingUser, email: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                />
              </div>

               {!isViewMode && (
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">
                        {editingUser.id ? 'Nueva Contraseña (opcional)' : 'Contraseña'}
                    </label>
                    <input 
                        type="password" required={!editingUser.id}
                        value={editingUser.password || ''}
                        onChange={e => setEditingUser({...editingUser, password: e.target.value})}
                        className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                        placeholder="••••••••"
                    />
                </div>
               )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Rol</label>
                <select 
                  value={editingUser.role || ''} disabled={isViewMode}
                  onChange={e => setEditingUser({...editingUser, role: e.target.value})}
                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                >
                  {roles.map(r => (
                    <option key={r.id} value={r.name}>{r.name}</option>
                  ))}
                </select>
              </div>

              <div className="pt-4 flex justify-end gap-3">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                  {isViewMode ? 'Cerrar' : 'Cancelar'}
                </button>
                {!isViewMode && (
                    <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                        <Save size={18} /> Guardar
                    </button>
                )}
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UsersPage;

import React, { useState, useEffect, useRef } from 'react';
import { User, AttendanceRecord, AttendanceLog } from '../types';
import { getUsers, getAttendanceByRange, getAttendanceLogs } from '../services/dataService';
import { ChevronLeft, ChevronRight, Search, Calendar, MapPin, Tablet, Printer, Loader2 } from 'lucide-react';
import { useAuth } from '../AuthContext';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

const Attendance: React.FC = () => {
  const { permissions } = useAuth();

  // Search State
  const [users, setUsers] = useState<User[]>([]);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Data State
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [logs, setLogs] = useState<AttendanceLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [generatingPdf, setGeneratingPdf] = useState(false);

  // Calendar View State
  const [currentCalendarDate, setCurrentCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);

  // PDF Report Ref
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    getUsers().then(data => {
      setUsers(data);
      // Default to Alfonso (ID 1) as he has most data in the sample
      const defaultUser = data.find(u => u.id === '1') || data[0];
      if (defaultUser) setSelectedUser(defaultUser.id);

      // Default Dates: Today
      const today = new Date();
      // Adjust for local timezone to ensure we get the correct "today" string yyyy-mm-dd
      const localToday = new Date(today.getTime() - (today.getTimezoneOffset() * 60000));
      const todayStr = localToday.toISOString().split('T')[0];

      setStartDate(todayStr);
      setEndDate(todayStr);

      setCurrentCalendarDate(new Date(today.getFullYear(), today.getMonth(), 1));
    });
  }, []);

  // Fetch logs when a day is selected
  useEffect(() => {
    if (selectedDay && selectedUser) {
        const dateStr = selectedDay.toISOString().split('T')[0];
        getAttendanceLogs(selectedUser, dateStr).then(setLogs);
    } else {
        setLogs([]);
    }
  }, [selectedDay, selectedUser]);

  const handleSearch = async () => {
    if (!selectedUser || !startDate || !endDate) {
        alert("Por favor seleccione usuario y rango de fechas");
        return;
    }

    setLoading(true);
    setHasSearched(true);
    // Reset selection to clear previous detail view
    setSelectedDay(null); 

    // Sync calendar view to start date
    const startObj = new Date(startDate);
    // Fix timezone offset issue for calendar navigation
    const startObjUTC = new Date(startObj.getUTCFullYear(), startObj.getUTCMonth(), 1);
    setCurrentCalendarDate(startObjUTC);

    try {
        const data = await getAttendanceByRange(selectedUser, startDate, endDate);
        setRecords(data);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const daysInMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), 1).getDay(); 

  // Fix: Calendar uses Sunday as 0. Our header is Dom, Lun... so we use standard getDay()
  const startDay = firstDayOfMonth; 

  const handleDayClick = (day: number) => {
    const newDate = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), day);
    setSelectedDay(newDate);
  };

  const changeMonth = (delta: number) => {
    setCurrentCalendarDate(new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + delta, 1));
    setSelectedDay(null);
  };

  const getRecordForDay = (day: number) => {
    const dateStr = `${currentCalendarDate.getFullYear()}-${String(currentCalendarDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    // Check if record exists in the fetched data
    return records.find(r => r.date === dateStr);
  };

  const selectedDateStr = selectedDay ? selectedDay.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
  const selectedISODate = selectedDay ? selectedDay.toISOString().split('T')[0] : '';
  const currentRecord = records.find(r => r.date === selectedISODate);

  // --- Logic for navigation restriction ---
  // Normalize dates to the first of the month for comparison
  const getMonthTime = (d: Date) => new Date(d.getFullYear(), d.getMonth(), 1).getTime();

  const currentMonthTime = getMonthTime(currentCalendarDate);
  const startMonthTime = startDate ? getMonthTime(new Date(startDate)) : -Infinity;
  const endMonthTime = endDate ? getMonthTime(new Date(endDate)) : Infinity;

  const canGoBack = currentMonthTime > startMonthTime;
  const canGoForward = currentMonthTime < endMonthTime;

  // Helper for Print View
  const getSelectedUserInfo = () => users.find(u => u.id === selectedUser);

  // Helper date format dd-mm-yyyy
  const formatDateForReport = (dateStr: string) => {
      if (!dateStr) return '';
      const parts = dateStr.split('-');
      if (parts.length === 3) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return dateStr;
  };

  // Generate PDF Handler
  const handlePrint = async () => {
    if (!reportRef.current) return;

    try {
        setGeneratingPdf(true);

        // Wait a bit to ensure rendering
        await new Promise(resolve => setTimeout(resolve, 300));

        // Get elements
        const headerPart = document.getElementById('report-part-1');
        const tablePart = document.getElementById('report-part-2');

        const pdf = new jsPDF('p', 'mm', 'letter'); // Tamaño Carta
        const pageWidth = 216; // Letter width in mm approx
        const pageHeight = 279; // Letter height in mm approx
        const margin = 15; // 15mm margin
        const printWidth = pageWidth - (margin * 2);

        // Render Header & Info (Part 1)
        let currentY = margin;
        if (headerPart) {
            const canvas1 = await html2canvas(headerPart, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            // Scale to print width
            const imgH1 = (canvas1.height * printWidth) / canvas1.width;

            pdf.addImage(canvas1.toDataURL('image/png'), 'PNG', margin, currentY, printWidth, imgH1);
            currentY += imgH1; // Remove extra gap, HTML padding handles spacing
        }

        // Render Table (Part 2)
        if (tablePart && selectedDay) {
            const canvas2 = await html2canvas(tablePart, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            const imgH2 = (canvas2.height * printWidth) / canvas2.width;

            // Check if it fits on the current page
            const spaceLeft = pageHeight - margin - currentY;

            if (imgH2 > spaceLeft) {
                pdf.addPage();
                currentY = margin;
            }

            pdf.addImage(canvas2.toDataURL('image/png'), 'PNG', margin, currentY, printWidth, imgH2);
        }

        const userName = getSelectedUserInfo()?.name.replace(/\s+/g, '_') || 'Reporte';
        pdf.save(`Asistencia_${userName}_${currentCalendarDate.getMonth()+1}_${currentCalendarDate.getFullYear()}.pdf`);

    } catch (error) {
        console.error("Error generating PDF:", error);
        alert("Hubo un error al generar el PDF. Por favor intente nuevamente.");
    } finally {
        setGeneratingPdf(false);
    }
  };

  return (
    <div className="space-y-6 relative">

      {/* SCREEN VIEW HEADER & FILTERS */}
      <div className="space-y-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <Search className="text-blue-600" /> Búsqueda Asistencia
            </h1>
            <p className="text-slate-500 mt-1">Consulta y gestiona los registros históricos de asistencia del personal.</p>
        </div>

        {/* FILTER BAR */}
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">Usuario</label>
                <select 
                    value={selectedUser} 
                    onChange={(e) => setSelectedUser(e.target.value)}
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-700 font-medium"
                >
                    {users.map(u => <option key={u.id} value={u.id}>{u.name} ({u.role})</option>)}
                </select>
            </div>

            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">Fecha Inicio</label>
                <input 
                    type="date" 
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-700"
                />
            </div>

            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">Fecha Término</label>
                <input 
                    type="date" 
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-700"
                />
            </div>

            <div>
                <button 
                    onClick={handleSearch}
                    disabled={loading}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-2.5 rounded-lg transition-colors flex items-center justify-center gap-2 disabled:opacity-70"
                >
                    {loading ? <span className="animate-spin w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span> : <Search size={18} />}
                    Buscar
                </button>
            </div>
        </div>
      </div>

      {!hasSearched && (
        <div className="text-center py-20 bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl">
            <Search size={48} className="mx-auto text-slate-300 mb-4" />
            <p className="text-slate-500 text-lg">Seleccione filtros y presione "Buscar" para ver la asistencia.</p>
        </div>
      )}

      {hasSearched && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-fade-in">

            {/* LEFT COLUMN: COMPACT CALENDAR */}
            <div className="lg:col-span-4 flex flex-col gap-4">
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    {/* Calendar Header */}
                    <div className="bg-slate-50 p-4 border-b border-slate-200 flex items-center justify-between">
                        <button 
                            onClick={() => changeMonth(-1)} 
                            disabled={!canGoBack}
                            className="p-1 hover:bg-white rounded-md transition-all shadow-sm disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:shadow-none"
                        >
                            <ChevronLeft size={20} className="text-slate-500"/>
                        </button>
                        <h2 className="text-lg font-bold text-slate-800 capitalize">
                            {currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                        </h2>
                        <button 
                            onClick={() => changeMonth(1)} 
                            disabled={!canGoForward}
                            className="p-1 hover:bg-white rounded-md transition-all shadow-sm disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:shadow-none"
                        >
                            <ChevronRight size={20} className="text-slate-500"/>
                        </button>
                    </div>

                    {/* Calendar Grid */}
                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2">
                            {['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'].map(day => (
                            <div key={day} className="text-center text-xs font-bold text-blue-600 uppercase py-1">
                                {day}
                            </div>
                            ))}
                        </div>

                        <div className="grid grid-cols-7 gap-1">
                            {Array.from({ length: startDay }).map((_, i) => (
                            <div key={`empty-${i}`} className="aspect-square"></div>
                            ))}

                            {Array.from({ length: daysInMonth }).map((_, i) => {
                            const day = i + 1;
                            const record = getRecordForDay(day);
                            const isSelected = selectedDay && selectedDay.getDate() === day && selectedDay.getMonth() === currentCalendarDate.getMonth();

                            // Blue box logic for Presente
                            const isPresent = record?.status === 'Presente';

                            return (
                                <button
                                    key={day}
                                    onClick={() => handleDayClick(day)}
                                    disabled={loading}
                                    className={`
                                        aspect-square rounded flex items-start justify-end p-1 text-xs font-medium transition-all relative border
                                        ${isSelected ? 'ring-2 ring-blue-400 ring-offset-1 z-10' : 'border-transparent'}
                                        ${isPresent 
                                            ? 'bg-blue-600 text-white hover:bg-blue-700' 
                                            : 'bg-white text-slate-700 hover:bg-slate-50 border-slate-100'}
                                    `}
                                >
                                    <span>{day}</span>
                                    {record?.status === 'Ausente' && <span className="absolute bottom-1 left-1 w-1.5 h-1.5 bg-red-500 rounded-full"></span>}
                                    {record?.status === 'Licencia' && <span className="absolute bottom-1 left-1 w-1.5 h-1.5 bg-orange-500 rounded-full"></span>}
                                </button>
                            );
                            })}
                        </div>
                    </div>
                </div>

                {/* Legend */}
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-4 text-xs">
                    <div className="flex items-center gap-2"><div className="w-4 h-4 bg-blue-600 rounded"></div> Asistencia</div>
                    <div className="flex items-center gap-2"><div className="w-4 h-4 bg-white border border-slate-200 rounded relative"><span className="absolute bottom-0.5 left-0.5 w-1.5 h-1.5 bg-red-500 rounded-full"></span></div> Ausente</div>
                </div>
            </div>

            {/* RIGHT COLUMN: DETAILS TABLE */}
            <div className="lg:col-span-8">
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
                    <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                        <div>
                            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                                <span className="text-2xl">👷</span> Detalle de Asistencia
                            </h3>
                            <p className="text-slate-500 font-medium mt-1">
                                {selectedDay ? `Fecha: ${selectedDateStr}` : 'Seleccione un día en el calendario'}
                            </p>
                        </div>

                        {/* Generate PDF Button */}
                        <button 
                            type="button"
                            onClick={handlePrint}
                            disabled={generatingPdf}
                            className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-700 transition-colors flex items-center gap-2 disabled:opacity-70"
                        >
                            {generatingPdf ? (
                                <><Loader2 size={16} className="animate-spin" /> Generando PDF...</>
                            ) : (
                                <><Printer size={16} /> Descargar Reporte (PDF)</>
                            )}
                        </button>
                    </div>

                    <div className="p-6 flex-1 overflow-x-auto">
                        {selectedDay ? (
                            logs.length > 0 ? (
                                <>
                                    <table className="w-full text-left border-collapse">
                                        <thead>
                                            <tr className="bg-slate-100 border-b border-slate-200 text-xs uppercase text-slate-500 font-bold">
                                                <th className="p-3 rounded-tl-lg">Nombre</th>
                                                <th className="p-3">Departamento</th>
                                                <th className="p-3">Fecha y Hora</th>
                                                <th className="p-3 rounded-tr-lg">Dispositivo</th>
                                            </tr>
                                        </thead>
                                        <tbody className="text-sm">
                                            {logs.map((log, idx) => (
                                                <tr key={idx} className="border-b border-slate-50 hover:bg-slate-50">
                                                    <td className="p-3 font-medium text-slate-800">{log.userName}</td>
                                                    <td className="p-3 text-slate-600 flex items-center gap-1"><MapPin size={14} className="text-slate-400"/> {log.department}</td>
                                                    <td className="p-3 text-slate-600 font-mono">{log.dateTime}</td>
                                                    <td className="p-3 text-slate-600 flex items-center gap-1"><Tablet size={14} className="text-slate-400"/> {log.deviceId}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px]">
                                    <Calendar size={48} className="mb-4 opacity-20" />
                                    <p className="font-medium">No hay registros de asistencia para este día.</p>
                                    <p className="text-sm opacity-70 mt-2">
                                        {currentRecord?.status === 'Ausente' ? 'El trabajador estuvo ausente.' : 'Sin datos.'}
                                    </p>
                                </div>
                            )
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px]">
                                <p>Seleccione un día del calendario para ver el detalle.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

        </div>
      )}

      {/* --- HIDDEN PDF REPORT TEMPLATE --- */}
      {/* 
         This div is rendered off-screen but is used by html2canvas to generate the PDF image.
         We set a fixed width of 800px which maps well to Letter PDF generation quality.
      */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
          <div ref={reportRef} className="w-[800px] bg-white text-slate-900 font-sans">

            {/* PART 1: HEADER & INFO - CORPORATE STYLE */}
            <div id="report-part-1" className="p-12 pb-0">
                {/* Corporate Letterhead */}
                <div className="flex items-end justify-between border-b-2 border-slate-900 pb-6 mb-8">
                    <div className="flex items-center gap-3">
                        {/* Icon Removed */}
                        <div>
                            <h1 className="text-2xl font-bold tracking-tight text-slate-900 uppercase">Agro Comice Ltda</h1>
                            <p className="text-slate-500 text-xs tracking-widest uppercase">Sistema Integrado de Gestión</p>
                        </div>
                    </div>
                    <div className="text-right">
                         <p className="text-xs text-slate-500 uppercase font-bold mb-1">Fecha Emisión</p>
                         <p className="text-base font-bold text-slate-800">{new Date().toLocaleDateString('es-ES', {year: 'numeric', month: 'long', day: 'numeric'})}</p>
                    </div>
                </div>

                <div className="mb-8">
                    <h2 className="text-xl font-bold text-slate-800 mb-6 uppercase tracking-tight">Reporte de Asistencia de Personal</h2>

                    {/* User Info & Filter Context */}
                    {selectedUser && (
                        /* Removed border and background styling */
                        <div className="grid grid-cols-2 gap-8 mt-6">
                            <div>
                                <h3 className="text-xs font-bold uppercase text-slate-500 mb-1 tracking-wide">Trabajador</h3>
                                <p className="text-lg font-bold text-slate-900">{getSelectedUserInfo()?.name}</p>
                                <p className="text-sm text-slate-600">{getSelectedUserInfo()?.role}</p>
                            </div>
                            <div>
                                <h3 className="text-xs font-bold uppercase text-slate-500 mb-1 tracking-wide">Periodo del Reporte</h3>
                                <p className="text-lg font-bold text-slate-900 capitalize">{currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}</p>
                                <p className="text-sm text-slate-600">Rango: {formatDateForReport(startDate)} al {formatDateForReport(endDate)}</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* PART 2: DETAIL TABLE */}
            {selectedDay && logs.length > 0 && (
                <div id="report-part-2" className="p-12 pt-4">
                     {/* Title modified: No blue line, clean text */}
                     <h3 className="font-bold text-lg mb-4 text-slate-800 border-b border-slate-200 pb-2">
                         Detalle del Día: {selectedDay.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'})}
                     </h3>

                     <table className="w-full text-left border border-slate-200">
                         <thead>
                             <tr className="bg-slate-100 border-b border-slate-200">
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Nombre</th>
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Departamento</th>
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Fecha y Hora</th>
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Dispositivo</th>
                             </tr>
                         </thead>
                         <tbody>
                             {logs.map((log, i) => (
                                 <tr key={i} className="border-b border-slate-100">
                                     <td className="p-3 text-sm font-medium text-slate-800">{log.userName}</td>
                                     <td className="p-3 text-sm text-slate-600">{log.department}</td>
                                     <td className="p-3 text-sm font-mono text-slate-600">{log.dateTime}</td>
                                     <td className="p-3 text-sm text-slate-600">{log.deviceId}</td>
                                 </tr>
                             ))}
                         </tbody>
                     </table>

                    <div className="mt-8 pt-8 border-t border-slate-200 text-center text-xs text-slate-400">
                        <p>Documento generado electrónicamente por Sistema Agro Comice Ltda.</p>
                        <p className="mt-1">Uso Exclusivo Interno.</p>
                    </div>
                </div>
            )}

            {/* Fallback if no logs */}
            {(!selectedDay || logs.length === 0) && (
                <div className="p-12 pt-0">
                     <div className="p-6 bg-slate-50 border border-slate-200 rounded-sm text-center text-slate-500 text-sm italic mb-8">
                        * No se ha seleccionado un día específico con registros para el detalle.
                    </div>
                </div>
            )}

          </div>
      </div>
    </div>
  );
};

export default Attendance;

import React, { useState, useEffect, useRef } from 'react';
import { User, AttendanceRecord, AttendanceLog } from '../types';
import { getUsers, getAttendanceByRange, getAttendanceLogs } from '../services/dataService';
import { ChevronLeft, ChevronRight, Search, Calendar, MapPin, Tablet, Printer, Loader2 } from 'lucide-react';
import { useAuth } from '../AuthContext';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

const Attendance: React.FC = () => {
  const { permissions } = useAuth();

  // Search State
  const [users, setUsers] = useState<User[]>([]);
  const [selectedUser, setSelectedUser] = useState<string>('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Data State
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [logs, setLogs] = useState<AttendanceLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [generatingPdf, setGeneratingPdf] = useState(false);

  // Calendar View State
  const [currentCalendarDate, setCurrentCalendarDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);

  // PDF Report Ref
  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    getUsers().then(data => {
      setUsers(data);
      // Default to Alfonso (ID 1) as he has most data in the sample
      const defaultUser = data.find(u => u.id === '1') || data[0];
      if (defaultUser) setSelectedUser(defaultUser.id);

      // Default Dates: Today
      const today = new Date();
      // Adjust for local timezone to ensure we get the correct "today" string yyyy-mm-dd
      const localToday = new Date(today.getTime() - (today.getTimezoneOffset() * 60000));
      const todayStr = localToday.toISOString().split('T')[0];

      setStartDate(todayStr);
      setEndDate(todayStr);

      setCurrentCalendarDate(new Date(today.getFullYear(), today.getMonth(), 1));
    });
  }, []);

  // Fetch logs when a day is selected
  useEffect(() => {
    if (selectedDay && selectedUser) {
        const dateStr = selectedDay.toISOString().split('T')[0];
        getAttendanceLogs(selectedUser, dateStr).then(setLogs);
    } else {
        setLogs([]);
    }
  }, [selectedDay, selectedUser]);

  const handleSearch = async () => {
    if (!selectedUser || !startDate || !endDate) {
        alert("Por favor seleccione usuario y rango de fechas");
        return;
    }

    setLoading(true);
    setHasSearched(true);
    // Reset selection to clear previous detail view
    setSelectedDay(null); 

    // Sync calendar view to start date
    const startObj = new Date(startDate);
    // Fix timezone offset issue for calendar navigation
    const startObjUTC = new Date(startObj.getUTCFullYear(), startObj.getUTCMonth(), 1);
    setCurrentCalendarDate(startObjUTC);

    try {
        const data = await getAttendanceByRange(selectedUser, startDate, endDate);
        setRecords(data);
    } catch (e) {
        console.error(e);
    } finally {
        setLoading(false);
    }
  };

  const daysInMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), 1).getDay(); 

  // Fix: Calendar uses Sunday as 0. Our header is Dom, Lun... so we use standard getDay()
  const startDay = firstDayOfMonth; 

  const handleDayClick = (day: number) => {
    const newDate = new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth(), day);
    setSelectedDay(newDate);
  };

  const changeMonth = (delta: number) => {
    setCurrentCalendarDate(new Date(currentCalendarDate.getFullYear(), currentCalendarDate.getMonth() + delta, 1));
    setSelectedDay(null);
  };

  const getRecordForDay = (day: number) => {
    const dateStr = `${currentCalendarDate.getFullYear()}-${String(currentCalendarDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    // Check if record exists in the fetched data
    return records.find(r => r.date === dateStr);
  };

  const selectedDateStr = selectedDay ? selectedDay.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
  const selectedISODate = selectedDay ? selectedDay.toISOString().split('T')[0] : '';
  const currentRecord = records.find(r => r.date === selectedISODate);

  // --- Logic for navigation restriction ---
  // Normalize dates to the first of the month for comparison
  const getMonthTime = (d: Date) => new Date(d.getFullYear(), d.getMonth(), 1).getTime();

  const currentMonthTime = getMonthTime(currentCalendarDate);
  const startMonthTime = startDate ? getMonthTime(new Date(startDate)) : -Infinity;
  const endMonthTime = endDate ? getMonthTime(new Date(endDate)) : Infinity;

  const canGoBack = currentMonthTime > startMonthTime;
  const canGoForward = currentMonthTime < endMonthTime;

  // Helper for Print View
  const getSelectedUserInfo = () => users.find(u => u.id === selectedUser);

  // Helper date format dd-mm-yyyy
  const formatDateForReport = (dateStr: string) => {
      if (!dateStr) return '';
      const parts = dateStr.split('-');
      if (parts.length === 3) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return dateStr;
  };

  // Generate PDF Handler
  const handlePrint = async () => {
    if (!reportRef.current) return;

    try {
        setGeneratingPdf(true);

        // Wait a bit to ensure rendering
        await new Promise(resolve => setTimeout(resolve, 300));

        // Get elements
        const headerPart = document.getElementById('report-part-1');
        const tablePart = document.getElementById('report-part-2');

        const pdf = new jsPDF('p', 'mm', 'letter'); // Tamaño Carta
        const pageWidth = 216; // Letter width in mm approx
        const pageHeight = 279; // Letter height in mm approx
        const margin = 15; // 15mm margin
        const printWidth = pageWidth - (margin * 2);

        // Render Header & Info (Part 1)
        let currentY = margin;
        if (headerPart) {
            const canvas1 = await html2canvas(headerPart, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            // Scale to print width
            const imgH1 = (canvas1.height * printWidth) / canvas1.width;

            pdf.addImage(canvas1.toDataURL('image/png'), 'PNG', margin, currentY, printWidth, imgH1);
            // Add explicit gap after header
            currentY += imgH1 + 10; 
        }

        // Render Table (Part 2)
        if (tablePart && selectedDay) {
            const canvas2 = await html2canvas(tablePart, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
            const imgH2 = (canvas2.height * printWidth) / canvas2.width;

            // Check if it fits on the current page
            const spaceLeft = pageHeight - margin - currentY;

            if (imgH2 > spaceLeft) {
                pdf.addPage();
                currentY = margin;
            }

            pdf.addImage(canvas2.toDataURL('image/png'), 'PNG', margin, currentY, printWidth, imgH2);
        }

        const userName = getSelectedUserInfo()?.name.replace(/\s+/g, '_') || 'Reporte';
        pdf.save(`Asistencia_${userName}_${currentCalendarDate.getMonth()+1}_${currentCalendarDate.getFullYear()}.pdf`);

    } catch (error) {
        console.error("Error generating PDF:", error);
        alert("Hubo un error al generar el PDF. Por favor intente nuevamente.");
    } finally {
        setGeneratingPdf(false);
    }
  };

  return (
    <div className="space-y-6 relative">

      {/* SCREEN VIEW HEADER & FILTERS */}
      <div className="space-y-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <Search className="text-blue-600" /> Búsqueda Asistencia
            </h1>
            <p className="text-slate-500 mt-1">Consulta y gestiona los registros históricos de asistencia del personal.</p>
        </div>

        {/* FILTER BAR */}
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">Usuario</label>
                <select 
                    value={selectedUser} 
                    onChange={(e) => setSelectedUser(e.target.value)}
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-700 font-medium"
                >
                    {users.map(u => <option key={u.id} value={u.id}>{u.name} ({u.role})</option>)}
                </select>
            </div>

            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">Fecha Inicio</label>
                <input 
                    type="date" 
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-700"
                />
            </div>

            <div>
                <label className="block text-xs font-semibold text-slate-500 mb-1 uppercase tracking-wide">Fecha Término</label>
                <input 
                    type="date" 
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-700"
                />
            </div>

            <div>
                <button 
                    onClick={handleSearch}
                    disabled={loading}
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-2.5 rounded-lg transition-colors flex items-center justify-center gap-2 disabled:opacity-70"
                >
                    {loading ? <span className="animate-spin w-4 h-4 border-2 border-white border-t-transparent rounded-full"></span> : <Search size={18} />}
                    Buscar
                </button>
            </div>
        </div>
      </div>

      {!hasSearched && (
        <div className="text-center py-20 bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl">
            <Search size={48} className="mx-auto text-slate-300 mb-4" />
            <p className="text-slate-500 text-lg">Seleccione filtros y presione "Buscar" para ver la asistencia.</p>
        </div>
      )}

      {hasSearched && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-fade-in">

            {/* LEFT COLUMN: COMPACT CALENDAR */}
            <div className="lg:col-span-4 flex flex-col gap-4">
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    {/* Calendar Header */}
                    <div className="bg-slate-50 p-4 border-b border-slate-200 flex items-center justify-between">
                        <button 
                            onClick={() => changeMonth(-1)} 
                            disabled={!canGoBack}
                            className="p-1 hover:bg-white rounded-md transition-all shadow-sm disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:shadow-none"
                        >
                            <ChevronLeft size={20} className="text-slate-500"/>
                        </button>
                        <h2 className="text-lg font-bold text-slate-800 capitalize">
                            {currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                        </h2>
                        <button 
                            onClick={() => changeMonth(1)} 
                            disabled={!canGoForward}
                            className="p-1 hover:bg-white rounded-md transition-all shadow-sm disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:shadow-none"
                        >
                            <ChevronRight size={20} className="text-slate-500"/>
                        </button>
                    </div>

                    {/* Calendar Grid */}
                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2">
                            {['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'].map(day => (
                            <div key={day} className="text-center text-xs font-bold text-blue-600 uppercase py-1">
                                {day}
                            </div>
                            ))}
                        </div>

                        <div className="grid grid-cols-7 gap-1">
                            {Array.from({ length: startDay }).map((_, i) => (
                            <div key={`empty-${i}`} className="aspect-square"></div>
                            ))}

                            {Array.from({ length: daysInMonth }).map((_, i) => {
                            const day = i + 1;
                            const record = getRecordForDay(day);
                            const isSelected = selectedDay && selectedDay.getDate() === day && selectedDay.getMonth() === currentCalendarDate.getMonth();

                            // Blue box logic for Presente
                            const isPresent = record?.status === 'Presente';

                            return (
                                <button
                                    key={day}
                                    onClick={() => handleDayClick(day)}
                                    disabled={loading}
                                    className={`
                                        aspect-square rounded flex items-start justify-end p-1 text-xs font-medium transition-all relative border
                                        ${isSelected ? 'ring-2 ring-blue-400 ring-offset-1 z-10' : 'border-transparent'}
                                        ${isPresent 
                                            ? 'bg-blue-600 text-white hover:bg-blue-700' 
                                            : 'bg-white text-slate-700 hover:bg-slate-50 border-slate-100'}
                                    `}
                                >
                                    <span>{day}</span>
                                    {record?.status === 'Ausente' && <span className="absolute bottom-1 left-1 w-1.5 h-1.5 bg-red-500 rounded-full"></span>}
                                    {record?.status === 'Licencia' && <span className="absolute bottom-1 left-1 w-1.5 h-1.5 bg-orange-500 rounded-full"></span>}
                                </button>
                            );
                            })}
                        </div>
                    </div>
                </div>

                {/* Legend */}
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-4 text-xs">
                    <div className="flex items-center gap-2"><div className="w-4 h-4 bg-blue-600 rounded"></div> Asistencia</div>
                    <div className="flex items-center gap-2"><div className="w-4 h-4 bg-white border border-slate-200 rounded relative"><span className="absolute bottom-0.5 left-0.5 w-1.5 h-1.5 bg-red-500 rounded-full"></span></div> Ausente</div>
                </div>
            </div>

            {/* RIGHT COLUMN: DETAILS TABLE */}
            <div className="lg:col-span-8">
                <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
                    <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                        <div>
                            <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                                <span className="text-2xl">👷</span> Detalle de Asistencia
                            </h3>
                            <p className="text-slate-500 font-medium mt-1">
                                {selectedDay ? `Fecha: ${selectedDateStr}` : 'Seleccione un día en el calendario'}
                            </p>
                        </div>

                        {/* Generate PDF Button */}
                        <button 
                            type="button"
                            onClick={handlePrint}
                            disabled={generatingPdf}
                            className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-700 transition-colors flex items-center gap-2 disabled:opacity-70"
                        >
                            {generatingPdf ? (
                                <><Loader2 size={16} className="animate-spin" /> Generando PDF...</>
                            ) : (
                                <><Printer size={16} /> Descargar Reporte (PDF)</>
                            )}
                        </button>
                    </div>

                    <div className="p-6 flex-1 overflow-x-auto">
                        {selectedDay ? (
                            logs.length > 0 ? (
                                <>
                                    <table className="w-full text-left border-collapse">
                                        <thead>
                                            <tr className="bg-slate-100 border-b border-slate-200 text-xs uppercase text-slate-500 font-bold">
                                                <th className="p-3 rounded-tl-lg">Nombre</th>
                                                <th className="p-3">Departamento</th>
                                                <th className="p-3">Fecha y Hora</th>
                                                <th className="p-3 rounded-tr-lg">Dispositivo</th>
                                            </tr>
                                        </thead>
                                        <tbody className="text-sm">
                                            {logs.map((log, idx) => (
                                                <tr key={idx} className="border-b border-slate-50 hover:bg-slate-50">
                                                    <td className="p-3 font-medium text-slate-800">{log.userName}</td>
                                                    <td className="p-3 text-slate-600 flex items-center gap-1"><MapPin size={14} className="text-slate-400"/> {log.department}</td>
                                                    <td className="p-3 text-slate-600 font-mono">{log.dateTime}</td>
                                                    <td className="p-3 text-slate-600 flex items-center gap-1"><Tablet size={14} className="text-slate-400"/> {log.deviceId}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </>
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px]">
                                    <Calendar size={48} className="mb-4 opacity-20" />
                                    <p className="font-medium">No hay registros de asistencia para este día.</p>
                                    <p className="text-sm opacity-70 mt-2">
                                        {currentRecord?.status === 'Ausente' ? 'El trabajador estuvo ausente.' : 'Sin datos.'}
                                    </p>
                                </div>
                            )
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[300px]">
                                <p>Seleccione un día del calendario para ver el detalle.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

        </div>
      )}

      {/* --- HIDDEN PDF REPORT TEMPLATE --- */}
      {/* 
         This div is rendered off-screen but is used by html2canvas to generate the PDF image.
         We set a fixed width of 800px which maps well to Letter PDF generation quality.
      */}
      <div style={{ position: 'absolute', left: '-9999px', top: 0 }}>
          <div ref={reportRef} className="w-[800px] bg-white text-slate-900 font-sans">

            {/* PART 1: HEADER & INFO - CORPORATE STYLE */}
            <div id="report-part-1" className="p-12 pb-0">
                {/* Corporate Letterhead */}
                <div className="flex items-end justify-between border-b-2 border-slate-900 pb-6 mb-8">
                    <div className="flex items-center gap-3">
                        {/* Icon Removed */}
                        <div>
                            <h1 className="text-2xl font-bold tracking-tight text-slate-900 uppercase">Agro Comice Ltda</h1>
                            <p className="text-slate-500 text-xs tracking-widest uppercase">Sistema Integrado de Gestión</p>
                        </div>
                    </div>
                    <div className="text-right">
                         <p className="text-xs text-slate-500 uppercase font-bold mb-1">Fecha Emisión</p>
                         <p className="text-base font-bold text-slate-800">{new Date().toLocaleDateString('es-ES', {year: 'numeric', month: 'long', day: 'numeric'})}</p>
                    </div>
                </div>

                <div className="mb-8">
                    <h2 className="text-xl font-bold text-slate-800 mb-6 uppercase tracking-tight">Reporte de Asistencia de Personal</h2>

                    {/* User Info & Filter Context */}
                    {selectedUser && (
                        /* Removed border and background styling */
                        <div className="grid grid-cols-2 gap-8 mt-6">
                            <div>
                                <h3 className="text-xs font-bold uppercase text-slate-500 mb-1 tracking-wide">Trabajador</h3>
                                <p className="text-lg font-bold text-slate-900">{getSelectedUserInfo()?.name}</p>
                                <p className="text-sm text-slate-600">{getSelectedUserInfo()?.role}</p>
                            </div>
                            <div>
                                <h3 className="text-xs font-bold uppercase text-slate-500 mb-1 tracking-wide">Periodo del Reporte</h3>
                                <p className="text-lg font-bold text-slate-900 capitalize">{currentCalendarDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}</p>
                                <p className="text-sm text-slate-600">Rango: {formatDateForReport(startDate)} al {formatDateForReport(endDate)}</p>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* PART 2: DETAIL TABLE */}
            {selectedDay && logs.length > 0 && (
                <div id="report-part-2" className="p-12 pt-4">
                     {/* Title modified: No blue line, clean text */}
                     <h3 className="font-bold text-lg mb-4 text-slate-800 border-b border-slate-200 pb-2">
                         Detalle del Día: {selectedDay.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'})}
                     </h3>

                     <table className="w-full text-left border border-slate-200">
                         <thead>
                             <tr className="bg-slate-100 border-b border-slate-200">
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Nombre</th>
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Departamento</th>
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Fecha y Hora</th>
                                 <th className="p-3 text-sm font-bold text-slate-700 uppercase">Dispositivo</th>
                             </tr>
                         </thead>
                         <tbody>
                             {logs.map((log, i) => (
                                 <tr key={i} className="border-b border-slate-100">
                                     <td className="p-3 text-sm font-medium text-slate-800">{log.userName}</td>
                                     <td className="p-3 text-sm text-slate-600">{log.department}</td>
                                     <td className="p-3 text-sm font-mono text-slate-600">{log.dateTime}</td>
                                     <td className="p-3 text-sm text-slate-600">{log.deviceId}</td>
                                 </tr>
                             ))}
                         </tbody>
                     </table>

                    <div className="mt-8 pt-8 border-t border-slate-200 text-center text-xs text-slate-400">
                        <p>Documento generado electrónicamente por Sistema Agro Comice Ltda.</p>
                        <p className="mt-1">Uso Exclusivo Interno.</p>
                    </div>
                </div>
            )}

            {/* Fallback if no logs */}
            {(!selectedDay || logs.length === 0) && (
                <div className="p-12 pt-0">
                     <div className="p-6 bg-slate-50 border border-slate-200 rounded-sm text-center text-slate-500 text-sm italic mb-8">
                        * No se ha seleccionado un día específico con registros para el detalle.
                    </div>
                </div>
            )}

          </div>
      </div>
    </div>
  );
};

export default Attendance;

import React, { useEffect, useState } from 'react';
import { Activity, ActivityStatus, User } from '../types';
import { getActivities, saveActivity, deleteActivity, getUsers } from '../services/dataService';
import { Plus, Edit2, Trash2, X, Save, Paperclip, FileText, Calendar, CheckCircle2, Clock, AlertCircle, Ban, Eye, ChevronLeft, ChevronRight } from 'lucide-react';
import { useAuth } from '../AuthContext';
import { ConfirmModal, AlertModal } from '../components/Modals';

const ActivitiesPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [activities, setActivities] = useState<Activity[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingActivity, setEditingActivity] = useState<Partial<Activity>>({});

  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  // Modals
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [alertState, setAlertState] = useState<{isOpen: boolean, title: string, message: string, type: 'success'|'error'|'info'}>({
      isOpen: false, title: '', message: '', type: 'info'
  });

  const canCreate = permissions?.['Actividades']?.create;
  const canEdit = permissions?.['Actividades']?.edit;
  const canDelete = permissions?.['Actividades']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [acts, usrs] = await Promise.all([getActivities(), getUsers()]);
    setActivities(acts);
    setUsers(usrs);
  };

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay(); 
  const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const changeMonth = (delta: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + delta, 1);
    setCurrentMonth(newDate);
    setSelectedDate(null);
  };

  const handleDayClick = (day: number) => {
      const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
      if (selectedDate && newDate.getTime() === selectedDate.getTime()) {
          setSelectedDate(null);
      } else {
          setSelectedDate(newDate);
      }
  };

  const getActivitiesForDay = (day: number) => {
      const dateStr = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
      return activities.filter(act => {
          // Filtro de Seguridad: Trabajador solo ve sus asignaciones
          if (currentUser?.role === 'Trabajador' && act.assigneeId !== currentUser.id) {
              return false;
          }
          return dateStr >= act.startDate && dateStr <= act.endDate;
      });
  };

  const getProcessedActivities = () => {
      let filtered = [];
      if (selectedDate) {
          const dateStr = selectedDate.toISOString().split('T')[0];
          filtered = activities.filter(act => dateStr >= act.startDate && dateStr <= act.endDate);
      } else {
          const targetMonth = currentMonth.getMonth();
          const targetYear = currentMonth.getFullYear();
          filtered = activities.filter(act => {
              const startParts = act.startDate.split('-');
              const y = parseInt(startParts[0]);
              const m = parseInt(startParts[1]) - 1;
              return y === targetYear && m === targetMonth;
          });
      }

      // Filtro de Seguridad: Trabajador solo ve sus asignaciones
      if (currentUser?.role === 'Trabajador') {
          filtered = filtered.filter(act => act.assigneeId === currentUser.id);
      }

      return filtered.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  const processedActivities = getProcessedActivities();

  const groupedActivities = {
      'Pendiente': processedActivities.filter(a => a.status === 'Pendiente'),
      'En Progreso': processedActivities.filter(a => a.status === 'En Progreso'),
      'Completada': processedActivities.filter(a => a.status === 'Completada'),
      'Cancelada': processedActivities.filter(a => a.status === 'Cancelada'),
  };

  const statusOrder: ActivityStatus[] = ['Pendiente', 'En Progreso', 'Completada', 'Cancelada'];

  const handleNew = () => {
    if (!canCreate) return;
    setEditingActivity({
        name: '',
        startDate: new Date().toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        description: '',
        status: 'Pendiente',
        assigneeId: currentUser?.id || '',
        attachments: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleEdit = (act: Activity) => {
    if (!canEdit) return;
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (act: Activity) => {
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  // 1. Trigger
  const handleDeleteClick = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        setAlertState({isOpen: true, title: 'Acceso Denegado', message: 'No tiene permisos para eliminar actividades.', type: 'error'});
        return;
    }
    setDeleteId(id);
  };

  // 2. Execute
  const confirmDelete = async () => {
    if (!deleteId) return;

    try {
        await deleteActivity(deleteId);
        setAlertState({
            isOpen: true, 
            title: 'Actividad Eliminada', 
            message: 'La actividad ha sido eliminada correctamente.', 
            type: 'success'
        });
        loadData();
    } catch (error) {
        console.error(error);
        setAlertState({
            isOpen: true,
            title: 'Error',
            message: 'No se pudo eliminar la actividad. Es posible que existan otros registros vinculados a ella.',
            type: 'error'
        });
    } finally {
        setDeleteId(null);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingActivity.name && editingActivity.startDate) {
        try {
            await saveActivity(editingActivity as Activity);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            setAlertState({isOpen: true, title: 'Error', message: 'Error al guardar la actividad.', type: 'error'});
        }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingActivity(prev => ({
                      ...prev,
                      attachments: [...(prev.attachments || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removeAttachment = (index: number) => {
      setEditingActivity(prev => ({
          ...prev,
          attachments: prev.attachments?.filter((_, i) => i !== index)
      }));
  };

  const getStatusIcon = (status?: ActivityStatus) => {
      switch(status) {
          case 'Pendiente': return <Clock size={14}/>;
          case 'En Progreso': return <AlertCircle size={14}/>;
          case 'Completada': return <CheckCircle2 size={14}/>;
          case 'Cancelada': return <Ban size={14}/>;
          default: return null;
      }
  };

  const formatDate = (dateStr: string | undefined) => {
      if (!dateStr) return '';
      const parts = dateStr.split('-');
      if (parts.length === 3) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return dateStr;
  };

  return (
    <div className="space-y-6">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Actividades y Tareas</h1>
            <p className="text-slate-500">Gestión operativa y planificación.</p>
        </div>

        <div className="flex items-center gap-3">
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nueva Actividad</span>
            </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          <div className="lg:col-span-1 lg:order-last space-y-4">
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden sticky top-24">
                    <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                         <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronLeft size={20}/></button>
                         <h3 className="font-bold text-slate-800 capitalize text-lg">
                             {currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                         </h3>
                         <button onClick={() => changeMonth(1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronRight size={20}/></button>
                    </div>

                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2 text-center">
                             {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                                 <span key={d} className="text-xs font-bold text-slate-400">{d}</span>
                             ))}
                        </div>
                        <div className="grid grid-cols-7 gap-1">
                            {Array.from({ length: startDay }).map((_, i) => (
                                <div key={`empty-${i}`} className="aspect-square"></div>
                            ))}
                            {Array.from({ length: daysInMonth }).map((_, i) => {
                                const day = i + 1;
                                const dayActivities = getActivitiesForDay(day);
                                const hasActivity = dayActivities.length > 0;
                                const isSelected = selectedDate && 
                                                   selectedDate.getDate() === day && 
                                                   selectedDate.getMonth() === currentMonth.getMonth();

                                let bgClass = 'bg-white text-slate-600 hover:bg-slate-50 border border-transparent';
                                if (hasActivity) {
                                    if (dayActivities.some(a => a.status === 'En Progreso')) {
                                        bgClass = 'bg-orange-50 border border-orange-200 text-orange-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Pendiente')) {
                                        bgClass = 'bg-blue-50 border border-blue-200 text-blue-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Completada')) {
                                        bgClass = 'bg-green-50 border border-green-200 text-green-700 font-bold';
                                    }
                                }
                                const ringClass = isSelected ? 'ring-2 ring-blue-600 ring-offset-2 z-10' : '';

                                return (
                                    <button 
                                        key={day} 
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square flex items-center justify-center rounded-lg transition-all text-sm ${bgClass} ${ringClass}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="mt-6 flex flex-wrap gap-3 text-[10px] text-slate-500 justify-center border-t border-slate-100 pt-4">
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-blue-500"></span> Pendiente</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-orange-500"></span> En Progreso</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-green-500"></span> Completada</div>
                        </div>
                    </div>
               </div>
          </div>

          <div className="lg:col-span-2">
              <div className="bg-blue-50/50 border border-blue-100 p-3 rounded-lg text-sm text-blue-800 flex items-center justify-between mb-6">
                  <div className="flex items-center gap-2">
                    <Calendar size={16} />
                    <span>
                        Viendo: <span className="font-bold capitalize">
                            {selectedDate 
                                ? selectedDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' }) 
                                : currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })
                            }
                        </span>
                    </span>
                  </div>
                  {selectedDate && (
                      <button onClick={() => setSelectedDate(null)} className="text-xs bg-white px-2 py-1 rounded border border-blue-200 hover:bg-blue-50 text-blue-600 font-medium flex items-center gap-1">
                          <X size={12}/> Ver todo el mes
                      </button>
                  )}
              </div>

              <div className="space-y-8">
                  {statusOrder.map(status => {
                      const items = groupedActivities[status];
                      if (items.length === 0) return null;

                      return (
                          <div key={status} className="animate-fade-in">
                              <h3 className={`font-bold text-lg mb-4 flex items-center gap-2 
                                ${status === 'Pendiente' ? 'text-blue-700' : 
                                  status === 'En Progreso' ? 'text-orange-700' :
                                  status === 'Completada' ? 'text-green-700' : 'text-slate-600'}
                              `}>
                                  {getStatusIcon(status)} 
                                  {status} 
                                  <span className="text-sm font-normal text-slate-400 bg-white px-2 py-0.5 rounded-full border border-slate-100 shadow-sm ml-2">
                                      {items.length}
                                  </span>
                              </h3>

                              <div className="grid grid-cols-1 gap-4">
                                  {items.map(act => {
                                      const assignee = users.find(u => u.id === act.assigneeId);
                                      return (
                                          <div key={act.id} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 flex flex-col md:flex-row justify-between gap-4 hover:shadow-md transition-shadow relative overflow-hidden group">
                                              <div className={`absolute left-0 top-0 bottom-0 w-1 ${
                                                  status === 'Pendiente' ? 'bg-blue-500' : 
                                                  status === 'En Progreso' ? 'bg-orange-500' :
                                                  status === 'Completada' ? 'bg-green-500' : 'bg-slate-400'
                                              }`}></div>

                                              <div className="flex-1 space-y-2 pl-2">
                                                  <div className="flex items-start justify-between md:justify-start gap-4">
                                                    <h3 className="font-bold text-base text-slate-800">{act.name}</h3>
                                                  </div>
                                                  <p className="text-slate-600 text-sm line-clamp-2">{act.description}</p>

                                                  <div className="flex flex-wrap gap-4 text-xs text-slate-500 mt-2 items-center">
                                                      <div className="flex items-center gap-1 bg-slate-50 px-2 py-1 rounded border border-slate-100">
                                                          <Calendar size={12} className="text-slate-400"/>
                                                          <span className="font-medium text-slate-700">{formatDate(act.startDate)}</span>
                                                      </div>
                                                      <div className="flex items-center gap-1">
                                                          <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-600">
                                                              {assignee?.name.charAt(0)}
                                                          </div>
                                                          {assignee?.name || 'Sin asignar'}
                                                      </div>
                                                      {act.attachments.length > 0 && (
                                                          <div className="flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded">
                                                              <Paperclip size={12} /> {act.attachments.length}
                                                          </div>
                                                      )}
                                                  </div>
                                              </div>

                                              <div className="flex items-center gap-2 border-t pt-3 md:border-t-0 md:pt-0 md:border-l md:pl-4 border-slate-100 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                                  <button onClick={() => handleView(act)} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors">
                                                      <Eye size={18} />
                                                  </button>
                                                  {canEdit && (
                                                      <button onClick={() => handleEdit(act)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                                          <Edit2 size={18} />
                                                      </button>
                                                  )}
                                                  {canDelete && (
                                                      <button 
                                                        onClick={(e) => handleDeleteClick(act.id, e)} 
                                                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                        title="Eliminar Actividad"
                                                      >
                                                          <Trash2 size={18} />
                                                      </button>
                                                  )}
                                              </div>
                                          </div>
                                      )
                                  })}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      </div>

      <ConfirmModal 
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={confirmDelete}
        title="¿Eliminar Actividad?"
        message="¿Está seguro que desea eliminar esta Actividad? Esta acción no se puede deshacer."
        confirmText="Eliminar"
      />

      <AlertModal
        isOpen={alertState.isOpen}
        onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
        title={alertState.title}
        message={alertState.message}
        type={alertState.type}
      />

      {isModalOpen && (
          <div className="fixed inset-0 bg-slate-900/50 flex items-center justify-center z-50 backdrop-blur-sm p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh] animate-fade-in">
                  <div className="flex justify-between items-center p-6 border-b border-slate-100">
                      <h2 className="text-xl font-bold text-slate-800">
                          {isViewMode ? 'Detalle de Actividad' : (editingActivity.id ? 'Editar Actividad' : 'Nueva Actividad')}
                      </h2>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                          <X size={24} />
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-6">

                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Nombre Actividad</label>
                          <input 
                              type="text" required disabled={isViewMode}
                              value={editingActivity.name}
                              onChange={e => setEditingActivity({...editingActivity, name: e.target.value})}
                              className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              placeholder="Ej: Mantenimiento Riego"
                          />
                      </div>

                      <div>
                          <label className="block text-sm font-medium text-slate-700 mb-1">Descripción</label>
                          <textarea 
                              required disabled={isViewMode}
                              value={editingActivity.description}
                              onChange={e => setEditingActivity({...editingActivity, description: e.target.value})}
                              className="w-full p-2 border border-slate-300 rounded-lg outline-none h-24 focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                          />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha Inicio</label>
                              <input 
                                  type="date" required disabled={isViewMode}
                                  value={editingActivity.startDate}
                                  onChange={e => setEditingActivity({...editingActivity, startDate: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              />
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Fecha Término</label>
                              <input 
                                  type="date" required disabled={isViewMode}
                                  value={editingActivity.endDate}
                                  onChange={e => setEditingActivity({...editingActivity, endDate: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              />
                          </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Encargado</label>
                              <select 
                                  value={editingActivity.assigneeId} disabled={isViewMode}
                                  onChange={e => setEditingActivity({...editingActivity, assigneeId: e.target.value})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              >
                                  <option value="">Seleccionar...</option>
                                  {users.map(u => (
                                      <option key={u.id} value={u.id}>{u.name}</option>
                                  ))}
                              </select>
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-slate-700 mb-1">Estado</label>
                              <select 
                                  value={editingActivity.status} disabled={isViewMode}
                                  onChange={e => setEditingActivity({...editingActivity, status: e.target.value as ActivityStatus})}
                                  className="w-full p-2 border border-slate-300 rounded-lg outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-slate-100"
                              >
                                  <option value="Pendiente">Pendiente</option>
                                  <option value="En Progreso">En Progreso</option>
                                  <option value="Completada">Completada</option>
                                  <option value="Cancelada">Cancelada</option>
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-sm font-bold text-slate-700 mb-2">Evidencia y Documentos</label>
                          {!isViewMode && (
                            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center hover:bg-slate-50 transition-colors">
                                <input 
                                    type="file" multiple 
                                    id="file-upload" 
                                    className="hidden" 
                                    onChange={handleFileUpload}
                                />
                                <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center gap-2">
                                    <Paperclip className="text-slate-400" size={24} />
                                    <span className="text-blue-600 font-medium">Adjuntar archivos</span>
                                    <span className="text-xs text-slate-400">PDF, JPG, PNG (Max 5MB)</span>
                                </label>
                            </div>
                          )}
                          {editingActivity.attachments && editingActivity.attachments.length > 0 ? (
                              <div className="mt-4 space-y-2">
                                  {editingActivity.attachments.map((file, idx) => (
                                      <div key={idx} className="flex items-center justify-between p-2 bg-slate-50 rounded border border-slate-200 text-sm">
                                          <div className="flex items-center gap-2 truncate">
                                              <FileText size={16} className="text-slate-500" />
                                              <span className="truncate max-w-[300px]">{file.name}</span>
                                          </div>
                                          {!isViewMode && (
                                              <button type="button" onClick={() => removeAttachment(idx)} className="text-red-500 hover:text-red-700">
                                                  <X size={16} />
                                              </button>
                                          )}
                                      </div>
                                  ))}
                              </div>
                          ) : isViewMode && (
                              <div className="text-slate-400 text-sm italic p-2">Sin adjuntos</div>
                          )}
                      </div>
                  </form>

                  <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
                      <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg">
                          {isViewMode ? 'Cerrar' : 'Cancelar'}
                      </button>
                      {!isViewMode && (
                        <button type="button" onClick={(e) => handleSave(e as any)} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2">
                            <Save size={18} /> Guardar
                        </button>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default ActivitiesPage;

import React, { useEffect, useState } from 'react';
import { Activity, ActivityStatus, User } from '../types';
import { getActivities, saveActivity, deleteActivity, getUsers } from '../services/dataService';
import { Plus, Edit2, Trash2, X, Save, Calendar, CheckCircle2, Clock, AlertCircle, Ban, Eye, ChevronLeft, ChevronRight, Upload, ImageIcon, ZoomIn } from 'lucide-react';
import { useAuth } from '../AuthContext';
import { ConfirmModal, AlertModal } from '../components/Modals';

const ActivitiesPage: React.FC = () => {
  const { permissions, user: currentUser } = useAuth();
  const [activities, setActivities] = useState<Activity[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isViewMode, setIsViewMode] = useState(false);
  const [editingActivity, setEditingActivity] = useState<Partial<Activity>>({});

  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);

  // Image Preview State
  const [previewImage, setPreviewImage] = useState<string | null>(null);

  // Modals
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [alertState, setAlertState] = useState<{isOpen: boolean, title: string, message: string, type: 'success'|'error'|'info'}>({
      isOpen: false, title: '', message: '', type: 'info'
  });

  const canCreate = permissions?.['Actividades']?.create;
  const canEdit = permissions?.['Actividades']?.edit;
  const canDelete = permissions?.['Actividades']?.delete;

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [acts, usrs] = await Promise.all([getActivities(), getUsers()]);
    setActivities(acts);
    setUsers(usrs);
  };

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay(); 
  const startDay = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const changeMonth = (delta: number) => {
    const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + delta, 1);
    setCurrentMonth(newDate);
    setSelectedDate(null);
  };

  const handleDayClick = (day: number) => {
      const newDate = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
      if (selectedDate && newDate.getTime() === selectedDate.getTime()) {
          setSelectedDate(null);
      } else {
          setSelectedDate(newDate);
      }
  };

  const getActivitiesForDay = (day: number) => {
      const dateStr = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
      return activities.filter(act => {
          // Filtro de Seguridad: Trabajador solo ve sus asignaciones
          if (currentUser?.role === 'Trabajador' && act.assigneeId !== currentUser.id) {
              return false;
          }
          return dateStr >= act.startDate && dateStr <= act.endDate;
      });
  };

  const getProcessedActivities = () => {
      let filtered = [];
      if (selectedDate) {
          const dateStr = selectedDate.toISOString().split('T')[0];
          filtered = activities.filter(act => dateStr >= act.startDate && dateStr <= act.endDate);
      } else {
          const targetMonth = currentMonth.getMonth();
          const targetYear = currentMonth.getFullYear();
          filtered = activities.filter(act => {
              const startParts = act.startDate.split('-');
              const y = parseInt(startParts[0]);
              const m = parseInt(startParts[1]) - 1;
              return y === targetYear && m === targetMonth;
          });
      }

      // Filtro de Seguridad: Trabajador solo ve sus asignaciones
      if (currentUser?.role === 'Trabajador') {
          filtered = filtered.filter(act => act.assigneeId === currentUser.id);
      }

      return filtered.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  const processedActivities = getProcessedActivities();

  const groupedActivities = {
      'Pendiente': processedActivities.filter(a => a.status === 'Pendiente'),
      'En Progreso': processedActivities.filter(a => a.status === 'En Progreso'),
      'Completada': processedActivities.filter(a => a.status === 'Completada'),
      'Cancelada': processedActivities.filter(a => a.status === 'Cancelada'),
  };

  const statusOrder: ActivityStatus[] = ['Pendiente', 'En Progreso', 'Completada', 'Cancelada'];

  const handleNew = () => {
    if (!canCreate) return;
    setEditingActivity({
        name: '',
        startDate: new Date().toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        description: '',
        status: 'Pendiente',
        assigneeId: currentUser?.id || '',
        attachments: []
    });
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleEdit = (act: Activity) => {
    if (!canEdit) return;
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(false);
    setIsModalOpen(true);
  };

  const handleView = (act: Activity) => {
    setEditingActivity(JSON.parse(JSON.stringify(act)));
    setIsViewMode(true);
    setIsModalOpen(true);
  };

  // 1. Trigger
  const handleDeleteClick = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!canDelete) {
        setAlertState({isOpen: true, title: 'Acceso Denegado', message: 'No tiene permisos para eliminar actividades.', type: 'error'});
        return;
    }
    setDeleteId(id);
  };

  // 2. Execute
  const confirmDelete = async () => {
    if (!deleteId) return;

    try {
        await deleteActivity(deleteId);
        setAlertState({
            isOpen: true, 
            title: 'Actividad Eliminada', 
            message: 'La actividad ha sido eliminada correctamente.', 
            type: 'success'
        });
        loadData();
    } catch (error) {
        console.error(error);
        setAlertState({
            isOpen: true,
            title: 'Error',
            message: 'No se pudo eliminar la actividad. Es posible que existan otros registros vinculados a ella.',
            type: 'error'
        });
    } finally {
        setDeleteId(null);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingActivity.name && editingActivity.startDate) {
        try {
            await saveActivity(editingActivity as Activity);
            setIsModalOpen(false);
            loadData();
        } catch (error) {
            setAlertState({isOpen: true, title: 'Error', message: 'Error al guardar la actividad.', type: 'error'});
        }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files && files.length > 0) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  setEditingActivity(prev => ({
                      ...prev,
                      attachments: [...(prev.attachments || []), {
                          name: file.name,
                          type: file.type,
                          url: reader.result as string
                      }]
                  }));
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removeAttachment = (index: number) => {
      setEditingActivity(prev => ({
          ...prev,
          attachments: prev.attachments?.filter((_, i) => i !== index)
      }));
  };

  const getStatusIcon = (status?: ActivityStatus) => {
      switch(status) {
          case 'Pendiente': return <Clock size={14}/>;
          case 'En Progreso': return <AlertCircle size={14}/>;
          case 'Completada': return <CheckCircle2 size={14}/>;
          case 'Cancelada': return <Ban size={14}/>;
          default: return null;
      }
  };

  const formatDate = (dateStr: string | undefined) => {
      if (!dateStr) return '';
      const parts = dateStr.split('-');
      if (parts.length === 3) {
          return `${parts[2]}-${parts[1]}-${parts[0]}`;
      }
      return dateStr;
  };

  return (
    <div className="space-y-6">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-3xl font-bold text-slate-800">Actividades y Tareas</h1>
            <p className="text-slate-500">Gestión operativa y planificación.</p>
        </div>

        <div className="flex items-center gap-3">
            {canCreate && (
            <button onClick={handleNew} className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2 transition-colors shadow-sm">
                <Plus size={18} /> <span className="hidden sm:inline">Nueva Actividad</span>
            </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          <div className="lg:col-span-1 lg:order-last space-y-4">
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden sticky top-24">
                    <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                         <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronLeft size={20}/></button>
                         <h3 className="font-bold text-slate-800 capitalize text-lg">
                             {currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
                         </h3>
                         <button onClick={() => changeMonth(1)} className="p-1 hover:bg-white rounded-md transition-shadow text-slate-500"><ChevronRight size={20}/></button>
                    </div>

                    <div className="p-4">
                        <div className="grid grid-cols-7 mb-2 text-center">
                             {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                                 <span key={d} className="text-xs font-bold text-slate-400">{d}</span>
                             ))}
                        </div>
                        <div className="grid grid-cols-7 gap-1">
                            {Array.from({ length: startDay }).map((_, i) => (
                                <div key={`empty-${i}`} className="aspect-square"></div>
                            ))}
                            {Array.from({ length: daysInMonth }).map((_, i) => {
                                const day = i + 1;
                                const dayActivities = getActivitiesForDay(day);
                                const hasActivity = dayActivities.length > 0;
                                const isSelected = selectedDate && 
                                                   selectedDate.getDate() === day && 
                                                   selectedDate.getMonth() === currentMonth.getMonth();

                                let bgClass = 'bg-white text-slate-600 hover:bg-slate-50 border border-transparent';
                                if (hasActivity) {
                                    if (dayActivities.some(a => a.status === 'En Progreso')) {
                                        bgClass = 'bg-orange-50 border border-orange-200 text-orange-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Pendiente')) {
                                        bgClass = 'bg-blue-50 border border-blue-200 text-blue-700 font-bold';
                                    } else if (dayActivities.some(a => a.status === 'Completada')) {
                                        bgClass = 'bg-green-50 border border-green-200 text-green-700 font-bold';
                                    }
                                }
                                const ringClass = isSelected ? 'ring-2 ring-blue-600 ring-offset-2 z-10' : '';

                                return (
                                    <button 
                                        key={day} 
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square flex items-center justify-center rounded-lg transition-all text-sm ${bgClass} ${ringClass}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="mt-6 flex flex-wrap gap-3 text-[10px] text-slate-500 justify-center border-t border-slate-100 pt-4">
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-blue-500"></span> Pendiente</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-orange-500"></span> En Progreso</div>
                            <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-green-500"></span> Completada</div>
                        </div>
                    </div>
               </div>
          </div>

          <div className="lg:col-span-2">
              <div className="bg-blue-50/50 border border-blue-100 p-3 rounded-lg text-sm text-blue-800 flex items-center justify-between mb-6">
                  <div className="flex items-center gap-2">
                    <Calendar size={16} />
                    <span>
                        Viendo: <span className="font-bold capitalize">
                            {selectedDate 
                                ? selectedDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' }) 
                                : currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })
                            }
                        </span>
                    </span>
                  </div>
                  {selectedDate && (
                      <button onClick={() => setSelectedDate(null)} className="text-xs bg-white px-2 py-1 rounded border border-blue-200 hover:bg-blue-50 text-blue-600 font-medium flex items-center gap-1">
                          <X size={12}/> Ver todo el mes
                      </button>
                  )}
              </div>

              <div className="space-y-8">
                  {statusOrder.map(status => {
                      const items = groupedActivities[status];
                      if (items.length === 0) return null;

                      return (
                          <div key={status} className="animate-fade-in">
                              <h3 className={`font-bold text-lg mb-4 flex items-center gap-2 
                                ${status === 'Pendiente' ? 'text-blue-700' : 
                                  status === 'En Progreso' ? 'text-orange-700' :
                                  status === 'Completada' ? 'text-green-700' : 'text-slate-600'}
                              `}>
                                  {getStatusIcon(status)} 
                                  {status} 
                                  <span className="text-sm font-normal text-slate-400 bg-white px-2 py-0.5 rounded-full border border-slate-100 shadow-sm ml-2">
                                      {items.length}
                                  </span>
                              </h3>

                              <div className="grid grid-cols-1 gap-4">
                                  {items.map(act => {
                                      const assignee = users.find(u => u.id === act.assigneeId);
                                      return (
                                          <div key={act.id} className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 flex flex-col md:flex-row justify-between gap-4 hover:shadow-md transition-shadow relative overflow-hidden group">
                                              <div className={`absolute left-0 top-0 bottom-0 w-1 ${
                                                  status === 'Pendiente' ? 'bg-blue-500' : 
                                                  status === 'En Progreso' ? 'bg-orange-500' :
                                                  status === 'Completada' ? 'bg-green-500' : 'bg-slate-400'
                                              }`}></div>

                                              <div className="flex-1 space-y-2 pl-2">
                                                  <div className="flex items-start justify-between md:justify-start gap-4">
                                                    <h3 className="font-bold text-base text-slate-800">{act.name}</h3>
                                                  </div>
                                                  <p className="text-slate-600 text-sm line-clamp-2">{act.description}</p>

                                                  <div className="flex flex-wrap gap-4 text-xs text-slate-500 mt-2 items-center">
                                                      <div className="flex items-center gap-1 bg-slate-50 px-2 py-1 rounded border border-slate-100">
                                                          <Calendar size={12} className="text-slate-400"/>
                                                          <span className="font-medium text-slate-700">{formatDate(act.startDate)}</span>
                                                      </div>
                                                      <div className="flex items-center gap-1">
                                                          <div className="w-5 h-5 rounded-full bg-slate-200 flex items-center justify-center text-[10px] font-bold text-slate-600">
                                                              {assignee?.name.charAt(0)}
                                                          </div>
                                                          {assignee?.name || 'Sin asignar'}
                                                      </div>
                                                      {act.attachments.length > 0 && (
                                                          <div className="flex items-center gap-1 text-blue-600 bg-blue-50 px-2 py-1 rounded">
                                                              <ImageIcon size={12} /> {act.attachments.length}
                                                          </div>
                                                      )}
                                                  </div>
                                              </div>

                                              <div className="flex items-center gap-2 border-t pt-3 md:border-t-0 md:pt-0 md:border-l md:pl-4 border-slate-100 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                                                  <button onClick={() => handleView(act)} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors">
                                                      <Eye size={18} />
                                                  </button>
                                                  {canEdit && (
                                                      <button onClick={() => handleEdit(act)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                                          <Edit2 size={18} />
                                                      </button>
                                                  )}
                                                  {canDelete && (
                                                      <button 
                                                        onClick={(e) => handleDeleteClick(act.id, e)} 
                                                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                        title="Eliminar Actividad"
                                                      >
                                                          <Trash2 size={18} />
                                                      </button>
                                                  )}
                                              </div>
                                          </div>
                                      )
                                  })}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      </div>

      <ConfirmModal 
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={confirmDelete}
        title="¿Eliminar Actividad?"
        message="¿Está seguro que desea eliminar esta Actividad? Esta acción no se puede deshacer."
        confirmText="Eliminar"
      />

      <AlertModal
        isOpen={alertState.isOpen}
        onClose={() => setAlertState(prev => ({ ...prev, isOpen: false }))}
        title={alertState.title}
        message={alertState.message}
        type={alertState.type}
      />

       {/* Image Preview Modal (Lightbox) */}
       {previewImage && (
          <div 
            className="fixed inset-0 z-[150] bg-black/90 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in"
            onClick={() => setPreviewImage(null)}
          >
              <button 
                onClick={() => setPreviewImage(null)}
                className="absolute top-4 right-4 text-white/70 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors"
