};

import React, { useEffect, useState, useRef } from 'react';
import { MeterReading, User } from '../types';
import { getPaginatedMeterReadings, saveMeterReading, deleteMeterReading, getUsers } from '../services/dataService';
import { Plus, Trash2, X, Save, Eye, Gauge, Droplets, Zap, Flame, Calendar, MapPin, User as UserIcon, Upload, ImageIcon, ZoomIn, Loader2, Fuel, TreePine, ChevronRight } from 'lucide-react';
import { useAuth } from '../AuthContext';
import { ConfirmModal, AlertModal } from '../components/Modals';

// --- SUB-COMPONENT: Service Section (Carrusel) ---
interface ServiceSectionProps {
    location: string;
    service: string;
    users: User[];
    refreshTrigger: number;
    canDelete: boolean;
    onView: (r: MeterReading) => void;
    onDelete: (id: string) => void;
    filterActive: boolean; // Si hay filtro, quizas queramos ocultar si está vacío
}

const ServiceSection: React.FC<ServiceSectionProps> = ({ 
    location, service, users, refreshTrigger, canDelete, onView, onDelete, filterActive 
}) => {
    const [readings, setReadings] = useState<MeterReading[]>([]);
    const [loading, setLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);
    const [page, setPage] = useState(0);
    const PAGE_SIZE = 5;

    // Si cambia el trigger (se creó/borró algo globalmente), recargamos el inicio
    useEffect(() => {
        loadInitial();
    }, [refreshTrigger, location, service]);

    const loadInitial = async () => {
        setLoading(true);
        try {
            const data = await getPaginatedMeterReadings(location, service, 0, PAGE_SIZE - 1);
            setReadings(data);
            setPage(1);
            setHasMore(data.length === PAGE_SIZE);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    const loadMore = async () => {
        const from = page * PAGE_SIZE;
        const to = from + PAGE_SIZE - 1;
        setLoading(true);
        try {
            const data = await getPaginatedMeterReadings(location, service, from, to);
            if (data.length > 0) {
                setReadings(prev => [...prev, ...data]);
                setPage(prev => prev + 1);
                if (data.length < PAGE_SIZE) setHasMore(false);
            } else {
                setHasMore(false);
            }
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    const getUserName = (id: string) => users.find(u => u.id === id)?.name || 'Usuario desconocido';

    const formatDate = (dateStr: string) => {
        if (!dateStr) return '';
        const parts = dateStr.split('-');
        if (parts.length === 3) return `${parts[2]}-${parts[1]}-${parts[0]}`;
        return dateStr;
    };

    const getServiceIcon = (type?: string) => {
        switch(type) {
            case 'Agua': return <Droplets size={16} className="text-blue-500" />;
            case 'Gas': return <Flame size={16} className="text-orange-500" />;
            case 'Luz': return <Zap size={16} className="text-yellow-500" />;
            case 'Leña': return <TreePine size={16} className="text-amber-700" />;
            case 'Bencina Maquinas': return <Fuel size={16} className="text-red-500" />;
            default: return <Gauge size={16} className="text-slate-500" />;
        }
    };

    // Si estamos filtrando y no hay datos, y ya cargó, no mostrar nada
    if (filterActive && readings.length === 0 && !loading) return null;
    // Si no estamos filtrando, pero no hay datos, ocultar también para limpiar vista
    if (readings.length === 0 && !loading) return null;

    return (
        <div className="mb-8">
            <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider mb-4 flex items-center gap-2">
                {getServiceIcon(service)} {service} 
                <span className="bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full text-xs font-normal border border-slate-200">
                   Recientes
                </span>
            </h3>

            {/* Carrusel Container */}
            <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x">
                {readings.map(reading => (
                    <div key={reading.id} className="min-w-[240px] w-[240px] snap-start bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow group flex flex-col">
                         {/* Imagen */}
                         <div className="h-32 bg-slate-100 relative overflow-hidden cursor-pointer" onClick={() => onView(reading)}>
                            {reading.photos && reading.photos.length > 0 ? (
                                <>
                                    <img src={reading.photos[0].url} alt="Lectura" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/>
                                    {reading.photos.length > 1 && (
                                        <div className="absolute top-2 right-2 bg-black/60 text-white px-1.5 py-0.5 rounded text-[10px] backdrop-blur-sm flex items-center gap-1">
                                            <ImageIcon size={10} /> +{reading.photos.length - 1}
                                        </div>
                                    )}
                                </>
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-slate-300">
                                    <ImageIcon size={32} />
                                </div>
                            )}
                        </div>

                        {/* Info */}
                        <div className="p-3 flex-1 flex flex-col justify-between">
                            <div className="flex items-center gap-1.5 text-xs text-slate-500 mb-1">
                                <Calendar size={12} /> {formatDate(reading.date)}
                            </div>

                            <div className="border-t border-slate-100 pt-2 mt-2 flex justify-between items-center">
                                <div className="flex items-center gap-1.5 overflow-hidden">
                                    <div className="w-5 h-5 rounded-full bg-slate-100 flex items-center justify-center font-bold text-[10px] text-slate-500 shrink-0">
                                        {getUserName(reading.userId).charAt(0)}
                                    </div>
                                    <span className="truncate text-xs text-slate-600 max-w-[80px]" title={getUserName(reading.userId)}>{getUserName(reading.userId)}</span>
                                </div>

                                <div className="flex items-center gap-1">
                                    <button onClick={() => onView(reading)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">
                                        <Eye size={16} />
                                    </button>
                                    {canDelete && (
                                        <button onClick={(e) => { e.stopPropagation(); onDelete(reading.id); }} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors">
                                            <Trash2 size={16} />
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                ))}

                {/* Load More Button / Placeholder */}
                {hasMore && (
                    <div className="min-w-[100px] flex items-center justify-center snap-start">
                         <button 
                            onClick={loadMore}
                            disabled={loading}
                            className="flex flex-col items-center gap-2 text-slate-400 hover:text-blue-600 transition-colors p-4 rounded-xl hover:bg-blue-50"
                        >
                            {loading ? <Loader2 className="animate-spin" /> : <ChevronRight size={32} />}
                            <span className="text-xs font-bold whitespace-nowrap">Ver más</span>
                        </button>
                    </div>
                )}
            </div>
             {readings.length === 0 && loading && (
                <div className="flex gap-4">
                    {[1,2,3].map(i => (
                        <div key={i} className="min-w-[240px] h-[200px] bg-slate-100 rounded-lg animate-pulse"></div>
                    ))}
                </div>
            )}
        </div>
    );
};


