export const getUsers = async (): Promise<User[]> => {
    const { data, error } = await supabase
        .from('users')
        .select('*')
        .order('name', { ascending: true }); // Ordenado alfabéticamente

    if (error) throw error;
    return data.map((u: any) => ({
        id: u.id,
        name: u.name,
        email: u.email,
        role: u.role,
        avatar: u.avatar,
        password: u.password,
        active: u.active ?? true // Default true si viene null
    }));
};

export const saveUser = async (user: User): Promise<User> => {
    // Prepare payload. If password changes, encrypt it.
    const payload: any = {
        name: user.name,
        email: user.email,
        role: user.role,
        avatar: user.avatar,
        active: user.active
    };

    // Only update password if provided (for edits) or required (for new)
    if (user.password) {
        payload.password = mockEncrypt(user.password);
    }

    if (user.id && user.id.length > 10) { // Simple check if UUID-ish
        // Update
        const { data, error } = await supabase
            .from('users')
            .update(payload)
            .eq('id', user.id)
            .select()
            .single();
        if (error) throw error;
        return { ...user, ...data };
    } else {
